INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C1','sci',4,2,'u4',1,'북극곰의 편지 — 북극은 원래 많이 추운 곳이었는데 요즈음에는 많이 춥지 않고 빙하의 크기도 많이 작아짐 · 그 까닭은 기후 변화 · 북극곰이 북극에서 살기 어려워짐 · 빙하가 작아지는 것을 막아 사는 곳을 지키고 싶어 친구들의 도움을 청함',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C2','sci',4,2,'u4',1,'줄어드는 빙하 놀이의 차례와 안전 — 모둠 친구들과 북극곰이 되어 흰 종이 위에 올라감 → 신호에 따라 반으로 접어 올라감 → 반복해서 접으며 버팀(발 전체가 종이 밖으로 나가지 않게) → 느낀 점 이야기 · 서로 밀거나 넘어지지 않게 조심하고 신호를 잘 들음',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C3','sci',4,2,'u4',1,'반으로 접는 종이의 뜻 — 흰 종이 = 빙하 · 반으로 접는 것 = 기후 변화로 녹아서 크기가 점점 작아지는 빙하 · 접을수록 올라설 자리는 줄고 모둠 친구 수는 그대로라 버티기 힘듦 = 북극곰이 살기 어려워지는 모습 · 누가 이기는지 겨루는 놀이가 아님',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C4','sci',4,2,'u4',1,'느낀 점과 기후 변화에 대한 관심 — 북극곰의 마음을 이해함 · 지구가 뜨거워지지 않도록 돕고 싶은 마음 · 기후 변화에 관심을 가짐 · 북극의 일이라도 우리와 상관있음 · 무섭기만 한 것이 아니라 도울 수 있음',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C5','sci',4,2,'u4',2,'심해지는 자연재해 — 가뭄·폭염·홍수·폭설·한파 같은 심각한 자연재해가 점점 심해짐 · 뉴스와 경험(비가 많이 와 도로와 집이 잠김, 따가운 폭염) · 우리나라에서도 일어남',ARRAY['[4과16-01] 기후 변화 현상의 예를 알고, 기후 변화가 인간의 활동과 관련되어 있음을 토의할 수 있다(지도서 성취기준 · W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C6','sci',4,2,'u4',2,'연평균 기온의 변화 — 우리나라 연평균 기온 그래프를 보면 연도별 평균 기온이 점차 상승함',ARRAY['[4과16-01] 기후 변화 현상의 예를 알고, 기후 변화가 인간의 활동과 관련되어 있음을 토의할 수 있다(지도서 성취기준 · W7 확인)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C7','sci',4,2,'u4',2,'기온의 변화 — 폭염과 한파 — 폭염 = 낮 최고기온이 33 ℃ 이상인 매우 더운 날씨, 폭염 일수가 늘어 여름에 장기간 폭염 · 한파 = 기온이 영하 12 ℃ 이하로 떨어지는 날씨, 한파 일수가 늘어 겨울에 강한 한파',ARRAY['[4과16-01] 기후 변화 현상의 예를 알고, 기후 변화가 인간의 활동과 관련되어 있음을 토의할 수 있다(지도서 성취기준 · W7 확인)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C8','sci',4,2,'u4',2,'강수량의 변화 — 홍수와 가뭄 — 연간 강수량이 늘어 홍수가 심해질 수 있음 · 가을~봄 강수량은 줄어 가뭄이 심해질 수 있음 · 강수량이 급격히 늘면 기습 폭우로 인한 홍수·폭설, 급격히 줄면 극심한 가뭄',ARRAY['[4과16-01] 기후 변화 현상의 예를 알고, 기후 변화가 인간의 활동과 관련되어 있음을 토의할 수 있다(지도서 성취기준 · W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C9','sci',4,2,'u4',2,'더 커지고 더 자주 — 폭염·한파·가뭄·홍수·폭설 등의 규모가 점차 커지고 더욱 자주 발생 · 기후 변화로 온도가 높아지고 건조한 날씨가 늘어 산불이 더 자주 일어남',ARRAY['[4과16-01] 기후 변화 현상의 예를 알고, 기후 변화가 인간의 활동과 관련되어 있음을 토의할 수 있다(지도서 성취기준 · W7 확인)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C10','sci',4,2,'u4',3,'기후 변화와 인간의 활동 — 기후 변화는 자연에 의해서도 일어나지만 인간의 활동과도 관련이 있음 · 인간의 활동과 기후 변화는 밀접한 관련이 있음',ARRAY['[4과16-01] 기후 변화 현상의 예를 알고, 기후 변화가 인간의 활동과 관련되어 있음을 토의할 수 있다(지도서 성취기준 · W7 확인)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C11','sci',4,2,'u4',3,'숲 파괴 — 도시나 도로, 건물을 짓기 위해 나무를 베어 숲을 파괴함 · 숲을 파괴할수록 기후 변화가 심각해질 수 있음',ARRAY['[4과16-01] 기후 변화 현상의 예를 알고, 기후 변화가 인간의 활동과 관련되어 있음을 토의할 수 있다(지도서 성취기준 · W7 확인)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C12','sci',4,2,'u4',3,'화석 연료 사용 — 교통수단을 움직이거나 공장에서 물건을 만들 때 화석 연료를 사용함 · 가까운 거리를 갈 때에도 승용차를 이용하는 것은 화석 연료를 과도하게 쓰는 것',ARRAY['[4과16-01] 기후 변화 현상의 예를 알고, 기후 변화가 인간의 활동과 관련되어 있음을 토의할 수 있다(지도서 성취기준 · W7 확인)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C13','sci',4,2,'u4',3,'쓰레기와 에너지 — 무분별하게 많은 양의 쓰레기를 버림·일회용품을 많이 씀 · 과도하게 쓰는 전기 에너지를 만들기 위해 화석 연료를 사용함 · 쓰지 않는 텔레비전과 컴퓨터를 켜 둠, 냉방과 난방을 필요 이상으로 함, 낮은 층도 승강기',ARRAY['[4과16-01] 기후 변화 현상의 예를 알고, 기후 변화가 인간의 활동과 관련되어 있음을 토의할 수 있다(지도서 성취기준 · W7 확인)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C14','sci',4,2,'u4',3,'환경을 생각하지 않는 활동 — 사람이 하는 모든 일이 아니라 숲 파괴·화석 연료 사용·많은 쓰레기처럼 환경을 생각하지 않는 활동이 기후 변화를 더욱 심각하게 만듦 · 나무 심기·계단 이용은 그 반대',ARRAY['[4과16-01] 기후 변화 현상의 예를 알고, 기후 변화가 인간의 활동과 관련되어 있음을 토의할 수 있다(지도서 성취기준 · W7 확인)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C15','sci',4,2,'u4',3,'조사하고 토의할 때 — 나와 다른 사람의 개인 정보를 누리망에 함부로 올리지 않음 · 조사한 정보의 출처를 확인하고 옳은 정보와 거짓 정보를 구분함 · 토의할 때 다른 사람의 의견을 주의 깊게 들음',ARRAY['[4과16-01] 기후 변화 현상의 예를 알고, 기후 변화가 인간의 활동과 관련되어 있음을 토의할 수 있다(지도서 성취기준 · W7 확인)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C16','sci',4,2,'u4',4,'해수면 상승 — 해수면 상승 = 바닷물의 높이가 높아지는 현상 · 기후 변화로 극지방의 빙하가 녹으면 해수면이 상승함 · 극지방 동물이 살 곳이 사라지고 물에 잠기는 곳이 생길 수 있음',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C17','sci',4,2,'u4',4,'모형실험 방법과 안전 — 바닷가 마을에 무엇이 있는지 생각 → 붙임딱지를 이쑤시개에 붙여 깃발 → 플라스틱 통 바닥에 색깔 점토를 붙이고 깃발을 꽂아 마을 → 천천히 물을 부으며 잠기는 부분 관찰 → 피해 예측 · 이쑤시개 전 면장갑, 장난 X, 물을 흘리지 않게',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C18','sci',4,2,'u4',4,'모형의 뜻과 결과 — 점토 = 육지와 섬 · 깃발 = 주택가·농경지 같은 곳 · 물을 붓는 것 = 해수면 상승 · 깃발 꽂은 곳이 잠김 = 살 수 있는 땅이 줄어듦 · 해안 도시와 고도가 낮은 땅이 잠길 수 있음 · 실험 전 예상과 실험에서 관찰을 나눔',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C19','sci',4,2,'u4',4,'세계 곳곳의 피해 — 남태평양의 몇몇 섬이 바닷물에 잠겨 사라질 수도 있음 · 비의 양이 적어져 사막이 늘어남 · 바닷물 온도가 높아져 산호초가 하얗게 변함 · 사막화·생태계 파괴가 더 많이 진행됨',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C20','sci',4,2,'u4',4,'빙하와 빙산 — 빙하 = 육지에 오랫동안 쌓인 눈이 얼음덩어리로 변해 육지를 덮고 있는 것 · 빙산 = 빙하에서 떨어져 나와 물에 떠 있는 얼음덩어리 · 컵에 넣은 얼음이 녹아도 물의 높이는 변하지 않음 — 떠 있는 빙산이 녹는다고 해수면이 오르는 것이 아님',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C21','sci',4,2,'u4',4,'심각성에 관심 갖기 — 모형실험으로 인간의 피해를 예측하고 기후 변화의 심각성에 관심을 가지고 탐구함 · 무섭기만 한 것이 아님',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C22','sci',4,2,'u4',5,'이미 우리 생활과 환경에 — 기후 변화는 먼 미래의 일이 아니라 이미 우리 생활과 환경에 영향을 미침 · 생활이 불편해진 모습(폭염으로 야외 활동 X, 폭설로 자동차 X, 한파로 외출 X, 홍수로 지하실에 물) · 환경이 달라진 모습(생태계 파괴) · 부정적인 영향',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C23','sci',4,2,'u4',5,'파괴되는 생태계와 심각해지는 자연재해 — 육지와 바다의 많은 동물과 식물이 살 곳을 잃고 사라짐 · 세계 곳곳에 폭염·홍수·태풍·산불 등이 자주 일어나 집이나 농작물에 피해',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C24','sci',4,2,'u4',5,'부족해지는 물과 위협받는 건강 — 비가 적게 와 마실 물이 부족해지고 물과 식량이 부족해짐 · 온열 질환 = 폭염으로 몸의 체온이 급격히 올라가면서 발생하는 질환, 열사병 환자 증가 · 모기·진드기 같은 해충이 많아져 감염병이 증가할 수 있음',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C25','sci',4,2,'u4',5,'동해안 오징어 — 기후 변화로 해마다 동해안의 수온이 상승해 오징어가 다른 곳으로 이동해서 줄어듦',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C26','sci',4,2,'u4',5,'조사하고 삼각책으로 설명하기 — 모둠별 조사 → 그림 → 글 → 풀칠·기자 그림 → 설명 · 신뢰할 수 있는 공공 사이트, 출처 확인, 전달해도 되는 내용인지 판단 · 모서리에 손이 스치지 않게 · 꾸밈보다 설명 · 다른 모둠 설명을 듣고 새로 알게 된 것을 씀',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C27','sci',4,2,'u4',6,'함께 하는 대응 — 인간은 기후 변화의 심각성을 깨닫고 대응하기 위해 노력함 · 국가와 사회, 과학자, 사람들이 함께 대응함(나 혼자서만·나라에서만이 아님)',ARRAY['[4과16-03] 기후 변화 대응 방법을 조사하고, 생활 속에서 실천할 수 있다(지도서 성취기준 · W7 확인)']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C28','sci',4,2,'u4',6,'국가와 사회의 노력 — 국가와 사회는 숲을 되살리고, 화석 연료 사용을 줄이기 위한 법과 제도를 만듦 · 누가 하는 노력인지 나눔(국가와 사회·과학자 / 사람들)',ARRAY['[4과16-03] 기후 변화 대응 방법을 조사하고, 생활 속에서 실천할 수 있다(지도서 성취기준 · W7 확인)']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C29','sci',4,2,'u4',6,'과학자의 새로운 기술 — 과학자는 기후 변화에 강한 씨앗, 친환경 에너지 개발 등 새로운 기술을 연구함 · 사과를 재배할 수 있는 곳이 줄어 무더운 여름철에 수확할 수 있는 새 품종 서머킹을 개발(재배하기 쉽고 새콤달콤)',ARRAY['[4과16-03] 기후 변화 대응 방법을 조사하고, 생활 속에서 실천할 수 있다(지도서 성취기준 · W7 확인)']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C30','sci',4,2,'u4',6,'친환경 에너지 — 화석 연료 사용을 줄이고 태양 에너지, 풍력 에너지 등 친환경 에너지를 개발하고 사용함',ARRAY['[4과16-03] 기후 변화 대응 방법을 조사하고, 생활 속에서 실천할 수 있다(지도서 성취기준 · W7 확인)']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C31','sci',4,2,'u4',6,'생활 속 대응 방법 — 가까운 거리는 걷거나 대중교통·친환경 자동차 · 전기 절약, 일회용품 줄이기, 샤워 짧게, 세탁물 모아서, 재활용과 친환경 제품, 음식물 쓰레기 줄이기 · 학교에서 급식 먹을 만큼, 빈 교실 전등 끄기 · 대응 방법과 그 까닭을 함께 씀',ARRAY['[4과16-03] 기후 변화 대응 방법을 조사하고, 생활 속에서 실천할 수 있다(지도서 성취기준 · W7 확인)']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C32','sci',4,2,'u4',7,'함께 실천하는 까닭 — 기후 변화 대응 방법은 일상생활에서 함께 실천하는 것이 중요함 · 많은 사람이 함께 실천해 기후 변화가 더 심해지는 것을 막기 위해 · 걱정만 하기보다 나부터 실천',ARRAY['[4과16-03] 기후 변화 대응 방법을 조사하고, 생활 속에서 실천할 수 있다(지도서 성취기준 · W7 확인)']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C33','sci',4,2,'u4',7,'나만의 대응 계획표 — 실천할 수 있는 대응 방법 → 평소 나의 부족한 점 → 목표와 실천 내용 → 한눈에 들어오는 제목 → 소개 · 목표와 실천 내용이 이어지고, 생활 속에서 실제로 실천할 수 있고, 꾸준히 할 수 있게',ARRAY['[4과16-03] 기후 변화 대응 방법을 조사하고, 생활 속에서 실천할 수 있다(지도서 성취기준 · W7 확인)']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C34','sci',4,2,'u4',7,'꾸준히 실천하고 점검하기 — 계획을 세운 뒤에는 꾸준히 실천하고 점검함 · 계획표를 잘 보이는 곳에 붙임, 점검표로 매일 실천·점검, 여러 사람 앞에서 약속 · 미루면 방해 · 매일 실천하는 습관',ARRAY['[4과16-03] 기후 변화 대응 방법을 조사하고, 생활 속에서 실천할 수 있다(지도서 성취기준 · W7 확인)']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C35','sci',4,2,'u4',7,'평가하기와 퀴즈 대회 — 평가 기준 = 대응 방법이 잘 나타남, 실천할 수 있는 계획, 일주일 동안 잘 실천, 목표와 실천 내용이 제목에 드러남 · 먼저 끝냈는지·색칠 양은 기준이 아님 · 퀴즈 다섯 문제를 차례대로 풀고 틀리면 배운 내용을 다시 확인',ARRAY['[4과16-03] 기후 변화 대응 방법을 조사하고, 생활 속에서 실천할 수 있다(지도서 성취기준 · W7 확인)']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C36','sci',4,2,'u4',8,'영구 동토와 빙하 — 영구 동토 = 2년 이상 땅의 온도가 0 °C 이하로 유지되어 여름에도 얼어 있는 땅 · 빙하 = 지구 환경의 변화를 알 수 있는 냉동 타임캡슐 · 기후 변화로 녹고 있음',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C37','sci',4,2,'u4',8,'녹으면서 드러나는 것 — 영구 동토가 녹으며 오래전 묻혔던 지층이 드러나고 얼음 속에 묻혀 있던 미생물이 되살아남 · 빙하 속에 있던 세균이 드러날 수 있음 · 얼어 있을 때와 녹으면서를 나눔',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C38','sci',4,2,'u4',8,'과학자의 빙하 연구 — 빙하에 깊게 구멍을 뚫어 잘 보존된 얼음층을 캐낸 뒤 연구함 · 세균이 우리 사회에 미칠 영향은 앞으로 연구가 더 필요함(이미 다 밝혀진 것이 아님)',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u4-C39','sci',4,2,'u4',8,'우리가 할 일 — 기후 변화에 대응하면 영구 동토와 빙하를 지킬 수 있음 · 일회용품 줄이기, 가까운 곳은 걸어서 이동 · 걱정만 하거나 상관없다고 여기지 않음',ARRAY['[4과16-02] 기후 변화의 심각성에 관심을 가지고, 기후 변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X01','sci',4,'u4',ARRAY['SC4-2-u4-C1']::text[],'요즈음 북극이 더 추워졌거나 빙하가 커졌다고 거꾸로 안다','많이 춥지 않고 작아졌어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X02','sci',4,'u4',ARRAY['SC4-2-u4-C1']::text[],'북극곰이 편지를 보낸 까닭이나 북극이 달라진 까닭을 엉뚱하게 안다(선물·이사·놀이 비법·북극곰 탓)','사는 곳을 지키고 싶어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X03','sci',4,'u4',ARRAY['SC4-2-u4-C2']::text[],'놀이에서 자리를 차지하려고 친구를 밀거나 신호 없이 마음대로 접는다','밀지 않고 신호대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X04','sci',4,'u4',ARRAY['SC4-2-u4-C3']::text[],'종이 접기 놀이를 누가 오래 버티는지 겨루는 승부로 여긴다','작아지는 빙하의 모습') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X05','sci',4,'u4',ARRAY['SC4-2-u4-C3']::text[],'접는 종이의 뜻을 엉뚱하게 안다(종이 아끼기·종이접기 솜씨·먹이)','흰 종이는 빙하') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X06','sci',4,'u4',ARRAY['SC4-2-u4-C3']::text[],'종이를 접어도 올라설 자리가 그대로이거나 친구 수가 함께 줄어 버티기 쉬워진다고 여긴다','자리는 줄고 친구는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X07','sci',4,'u4',ARRAY['SC4-2-u4-C4','SC4-2-u4-C39']::text[],'멀리 떨어진 북극·빙하의 일이라 우리와 상관없다고 여긴다','친구들의 도움이 필요해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X08','sci',4,'u4',ARRAY['SC4-2-u4-C4','SC4-2-u4-C21','SC4-2-u4-C32','SC4-2-u4-C39']::text[],'기후 변화는 무섭기만 하고 할 수 있는 일이 없다고 여겨 걱정만 한다','나부터 할 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X09','sci',4,'u4',ARRAY['SC4-2-u4-C5']::text[],'기후 변화 현상은 다른 나라에서만 일어난다고 여긴다','우리나라에서도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X10','sci',4,'u4',ARRAY['SC4-2-u4-C5','SC4-2-u4-C9']::text[],'자연재해가 점점 줄어들거나 약해지고 있다고 여긴다','더 커지고 더 자주') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X11','sci',4,'u4',ARRAY['SC4-2-u4-C6']::text[],'우리나라 연평균 기온이 낮아지거나 늘 같다고 여긴다','점차 상승해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X12','sci',4,'u4',ARRAY['SC4-2-u4-C7']::text[],'폭염과 한파의 뜻이나 나타나는 계절을 뒤바꾼다','여름 폭염 · 겨울 한파') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X13','sci',4,'u4',ARRAY['SC4-2-u4-C8']::text[],'강수량이 늘 때와 줄 때 생기는 일을 뒤바꾼다(늘면 가뭄, 줄면 홍수)','늘면 홍수 · 줄면 가뭄') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X14','sci',4,'u4',ARRAY['SC4-2-u4-C8']::text[],'카드 속 변화의 방향을 거꾸로 안다(가을~봄 강수량이 늘었다, 한파 일수가 줄었다)','셋은 늘고 하나는 줄었어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X15','sci',4,'u4',ARRAY['SC4-2-u4-C7','SC4-2-u4-C8']::text[],'기온의 변화와 강수량의 변화를 가르지 못한다','덥고 추움 · 비와 눈의 양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X16','sci',4,'u4',ARRAY['SC4-2-u4-C9']::text[],'산불이 잦아지는 까닭을 비·한파·폭설로 여긴다','덥고 건조해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X17','sci',4,'u4',ARRAY['SC4-2-u4-C10']::text[],'기후 변화는 자연에 의해서만 일어나고 인간의 활동과는 관련이 없다고 여긴다','인간의 활동과도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X18','sci',4,'u4',ARRAY['SC4-2-u4-C14']::text[],'사람이 하는 모든 일이 기후 변화를 심각하게 만든다고 여긴다','환경을 생각하지 않는 활동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X19','sci',4,'u4',ARRAY['SC4-2-u4-C14']::text[],'나무 심기·계단 이용·전등 끄기처럼 지구를 돕는 활동을 기후 변화를 심각하게 만드는 활동으로 여긴다','돕는 활동은 반대예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X20','sci',4,'u4',ARRAY['SC4-2-u4-C11']::text[],'숲을 파괴해도 기후 변화와 관계없거나 오히려 줄어든다고 여긴다','숲 파괴') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X21','sci',4,'u4',ARRAY['SC4-2-u4-C12']::text[],'승용차·공장처럼 화석 연료를 쓰는 활동이 기후 변화와 관계없다고 여긴다','화석 연료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X22','sci',4,'u4',ARRAY['SC4-2-u4-C13']::text[],'일회용품을 더 쓰거나 쓰레기를 많이 버려도 괜찮다고 여긴다','쓰레기를 줄여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X23','sci',4,'u4',ARRAY['SC4-2-u4-C13']::text[],'난방·전기 사용과 기후 변화의 관계를 잘못 안다(전기가 필요 없다, 많이 쓸수록 기후 변화가 줄어든다)','전기가 많이 필요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X24','sci',4,'u4',ARRAY['SC4-2-u4-C15']::text[],'토의할 때 내 의견만 주장하거나 개인 정보를 누리망에 함부로 올린다','주의 깊게 듣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X25','sci',4,'u4',ARRAY['SC4-2-u4-C15','SC4-2-u4-C26']::text[],'조사한 정보를 출처를 확인하지 않고 옮기거나 누리망 정보는 모두 옳다고 여긴다','출처 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X26','sci',4,'u4',ARRAY['SC4-2-u4-C16']::text[],'빙하가 녹으면 해수면이 낮아지거나 다른 것(강수량·산의 높이)이 높아진다고 여긴다','바닷물의 높이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X27','sci',4,'u4',ARRAY['SC4-2-u4-C16']::text[],'해수면 상승의 뜻을 잘못 안다(눈이 쌓임·비가 많이 옴·사막이 됨)','바닷물의 높이가 높아짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X28','sci',4,'u4',ARRAY['SC4-2-u4-C17']::text[],'이쑤시개로 장난치거나 물을 한꺼번에 쏟는 등 모형실험의 안전을 지키지 않는다','면장갑 · 천천히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X29','sci',4,'u4',ARRAY['SC4-2-u4-C18']::text[],'해수면이 오르면 육지가 넓어지거나 높은 산만 잠긴다고 여긴다','살 수 있는 땅이 줄어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X30','sci',4,'u4',ARRAY['SC4-2-u4-C18']::text[],'모형의 각 부분이 뜻하는 것을 뒤바꾼다(물 붓기 = 육지, 점토 = 바닷물)','점토는 땅 · 물 붓기는 해수면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X31','sci',4,'u4',ARRAY['SC4-2-u4-C18']::text[],'실험 전에 예상한 것과 실험에서 관찰한 것을 가르지 못하거나 실험의 목적을 놀이로만 여긴다','실험 전 · 실험 뒤') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X32','sci',4,'u4',ARRAY['SC4-2-u4-C20']::text[],'빙하와 빙산을 같게 여겨 물에 떠 있는 빙산이 녹으면 해수면이 올라간다고 여긴다','컵 속 얼음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X33','sci',4,'u4',ARRAY['SC4-2-u4-C19']::text[],'세계 곳곳의 피해를 거꾸로 안다(사막이 줄어듦, 산호초가 더 알록달록해짐)','사막화 · 하얗게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X34','sci',4,'u4',ARRAY['SC4-2-u4-C18','SC4-2-u4-C22']::text[],'기후 변화의 피해는 우리 생활과 상관없거나 먼 미래의 일이라고 여긴다','이미 우리 곁에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X35','sci',4,'u4',ARRAY['SC4-2-u4-C22']::text[],'기후 변화가 자연재해를 줄이거나 물·식량을 풍부하게 하는 좋은 점이 있다고 여긴다','부정적인 영향') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X36','sci',4,'u4',ARRAY['SC4-2-u4-C22']::text[],'생활이 불편해진 모습과 환경이 달라진 모습을 가르지 못한다','생활 · 환경') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X37','sci',4,'u4',ARRAY['SC4-2-u4-C24']::text[],'온열 질환의 뜻을 잘못 알거나 폭염과 관계없다고 여긴다(한파·비·과식)','폭염 · 체온') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X38','sci',4,'u4',ARRAY['SC4-2-u4-C23','SC4-2-u4-C24']::text[],'네 가지 영향(생태계·자연재해·물·건강)과 그 설명을 뒤바꾼다','그림 이름을 읽어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X39','sci',4,'u4',ARRAY['SC4-2-u4-C25']::text[],'동해안 오징어가 줄어드는 까닭을 엉뚱하게 안다(바닷물이 차가워짐·비)','수온 상승 · 이동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X40','sci',4,'u4',ARRAY['SC4-2-u4-C26']::text[],'삼각책은 예쁘게 꾸미는 것이 가장 중요하다고 여기거나 설명 듣기·모서리 안전을 소홀히 한다','설명이 중요해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X41','sci',4,'u4',ARRAY['SC4-2-u4-C27']::text[],'기후 변화 대응은 나 혼자서만, 또는 나라에서만 할 수 있다고 여긴다','함께 대응해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X42','sci',4,'u4',ARRAY['SC4-2-u4-C28']::text[],'누가 하는 노력인지(국가와 사회·과학자 / 사람들) 뒤바꾼다','누가 하나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X43','sci',4,'u4',ARRAY['SC4-2-u4-C29']::text[],'과학자의 기술 연구나 서머킹을 개발한 까닭을 잘못 안다','새로운 기술') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X44','sci',4,'u4',ARRAY['SC4-2-u4-C31']::text[],'비닐봉지 자주 쓰기·전등 켜 두기·음식 남기기를 대응 방법으로 여긴다','아끼고 줄여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X45','sci',4,'u4',ARRAY['SC4-2-u4-C30']::text[],'친환경 에너지를 잘못 안다(화석 연료를 더 많이 쓰는 것)','태양 · 바람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X46','sci',4,'u4',ARRAY['SC4-2-u4-C32']::text[],'실천은 가끔 하거나 다른 사람을 기다리거나 칭찬받으려고 하는 것이라 여긴다','함께 꾸준히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X47','sci',4,'u4',ARRAY['SC4-2-u4-C33']::text[],'계획표의 칸(목표·부족한 점·실천 내용·제목·방법)에 들어갈 내용을 뒤바꾼다','칸마다 할 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X48','sci',4,'u4',ARRAY['SC4-2-u4-C33']::text[],'목표와 이어지지 않거나 실천할 수 없거나 하루만 하는 계획을 알맞다고 여긴다','이어지고 할 수 있고 꾸준히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X49','sci',4,'u4',ARRAY['SC4-2-u4-C34']::text[],'미루기·창문 열고 난방하기처럼 방해되는 것을 괜찮다고 여기거나 점검을 하지 않는다','점검표 · 미루지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X50','sci',4,'u4',ARRAY['SC4-2-u4-C35']::text[],'평가할 때 먼저 끝냈는지·색칠 양·꾸밈을 본다고 여기거나 틀린 퀴즈를 확인하지 않는다','대응 방법 · 실천') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X51','sci',4,'u4',ARRAY['SC4-2-u4-C36']::text[],'영구 동토의 뜻을 잘못 알거나 영구 동토와 빙하가 녹지 않는다고 여긴다','여름에도 얼어 있는 땅') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X52','sci',4,'u4',ARRAY['SC4-2-u4-C36']::text[],'빙하를 냉동 타임캡슐이라 부르는 까닭을 잘못 안다(음식 보관·절대 녹지 않음·사람이 만듦)','지구 환경의 변화') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X53','sci',4,'u4',ARRAY['SC4-2-u4-C37']::text[],'얼어 있을 때와 녹으면서 생기는 일을 뒤바꾼다','녹으면서 드러나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X54','sci',4,'u4',ARRAY['SC4-2-u4-C38']::text[],'세균이 미칠 영향은 이미 모두 밝혀졌다거나 빙하 연구가 필요 없다고 여긴다','앞으로 연구가 더 필요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u4-X55','sci',4,'u4',ARRAY['SC4-2-u4-C39']::text[],'영구 동토를 지키는 데 일회용품 더 쓰기·자동차 타기가 도움이 되거나 관계없다고 여긴다','대응 방법을 떠올려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_basic#1','sci',4,2,'u4','L01','g4_2_sci_u4_L01_basic','lesson_basic','SC4-2-u4-C1',1,'mc','auto','북극곰의 편지에서 요즈음 북극은 어떻게 달라졌다고 했나요?',ARRAY['SC4-2-u4-X01']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C1","difficulty":1,"kind":"mc","stem":"북극곰의 편지에서 요즈음 북극은 어떻게 달라졌다고 했나요?","options":[{"t":"많이 춥지 않고 빙하의 크기도 많이 작아졌다","correct":true},{"t":"원래보다 훨씬 더 추워졌다","mis":"SC4-2-u4-X01"},{"t":"빙하의 크기가 더 커졌다","mis":"SC4-2-u4-X01"},{"t":"꽃이 가득 피는 곳이 되었다","mis":"SC4-2-u4-X01"}],"explanation":["편지의 셋째 줄을 읽어요.","「요즈음에는」 뒤를 봐요.","춥지 않고 빙하가 작아졌어요."],"asset":{"type":"passage","lines":["친구들아, 안녕? 나는 북극에 사는 북극곰이야.","북극은 원래 많이 추운 곳이었어.","요즈음에는 많이 춥지 않고, 빙하의 크기도 많이 작아졌어.","그 까닭이 기후 변화 때문이래.","북극에서 계속 살려면 친구들의 도움이 필요해."],"title":"북극곰의 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_basic#2','sci',4,2,'u4','L01','g4_2_sci_u4_L01_basic','lesson_basic','SC4-2-u4-C2',1,'ox','auto','줄어드는 빙하 놀이를 할 때에는 모둠원끼리 서로 밀거나 넘어지지 않게 조심해요.',ARRAY['SC4-2-u4-X03']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C2","difficulty":1,"kind":"ox","stem":"줄어드는 빙하 놀이를 할 때에는 모둠원끼리 서로 밀거나 넘어지지 않게 조심해요.","answer":"O","reason_options":[{"t":"좁아지는 종이 위에서 밀면 친구가 넘어져 다칠 수 있기 때문에","correct":true},{"t":"자리를 차지하려면 친구를 밀어도 되기 때문에","mis":"SC4-2-u4-X03"}],"mis":"SC4-2-u4-X03","explanation":["좁은 종이 위를 떠올려요.","넘어질 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_basic#3','sci',4,2,'u4','L01','g4_2_sci_u4_L01_basic','lesson_basic','SC4-2-u4-C3',1,'mc','auto','줄어드는 빙하 놀이에서 흰 종이는 무엇을 나타내나요?',ARRAY['SC4-2-u4-X05','SC4-2-u4-X04']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C3","difficulty":1,"kind":"mc","stem":"줄어드는 빙하 놀이에서 흰 종이는 무엇을 나타내나요?","options":[{"t":"북극의 빙하","correct":true},{"t":"북극곰이 먹는 먹이","mis":"SC4-2-u4-X05"},{"t":"놀이에서 이긴 모둠이 받는 상","mis":"SC4-2-u4-X04"},{"t":"종이접기 연습장","mis":"SC4-2-u4-X05"}],"explanation":["북극곰이 올라서는 곳이에요.","하얗고 차가운 곳이에요.","빙하예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_basic#4','sci',4,2,'u4','L01','g4_2_sci_u4_L01_basic','lesson_basic','SC4-2-u4-C1',1,'sa','auto','편지를 보낸 북극곰이 사는 곳은 어디인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u4-C1","difficulty":1,"kind":"sa","stem":"편지를 보낸 북극곰이 사는 곳은 어디인가요? 두 글자로 쓰세요.","answer":["북극"],"explanation":["편지 첫 줄을 읽어요.","아주 추운 곳이에요.","북극이에요."],"asset":{"type":"passage","lines":["친구들아, 안녕? 나는 북극에 사는 북극곰이야.","북극은 원래 많이 추운 곳이었어.","요즈음에는 많이 춥지 않고, 빙하의 크기도 많이 작아졌어.","그 까닭이 기후 변화 때문이래.","북극에서 계속 살려면 친구들의 도움이 필요해."],"title":"북극곰의 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_basic#5','sci',4,2,'u4','L01','g4_2_sci_u4_L01_basic','lesson_basic','SC4-2-u4-C1',2,'mc','auto','북극곰이 친구들에게 편지를 보낸 까닭은 무엇인가요?',ARRAY['SC4-2-u4-X02','SC4-2-u4-X04']::text[],false,'{"seq":5,"concept":"SC4-2-u4-C1","difficulty":2,"kind":"mc","stem":"북극곰이 친구들에게 편지를 보낸 까닭은 무엇인가요?","options":[{"t":"빙하가 작아지는 것을 막아 지금 사는 곳을 지키고 싶어서","correct":true},{"t":"생일 선물을 받고 싶어서","mis":"SC4-2-u4-X02"},{"t":"친구들이 사는 곳으로 이사 오고 싶어서","mis":"SC4-2-u4-X02"},{"t":"놀이에서 이기는 방법을 알려 주려고","mis":"SC4-2-u4-X04"}],"explanation":["편지 끝 줄을 읽어요.","도움이 필요하대요.","사는 곳을 지키고 싶어서예요."],"asset":{"type":"passage","lines":["친구들아, 안녕? 나는 북극에 사는 북극곰이야.","북극은 원래 많이 추운 곳이었어.","요즈음에는 많이 춥지 않고, 빙하의 크기도 많이 작아졌어.","그 까닭이 기후 변화 때문이래.","북극에서 계속 살려면 친구들의 도움이 필요해."],"title":"북극곰의 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_basic#6','sci',4,2,'u4','L01','g4_2_sci_u4_L01_basic','lesson_basic','SC4-2-u4-C3',2,'match','auto','놀이 차례와 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-2-u4-C3","difficulty":2,"kind":"match","stem":"놀이 차례와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"종이 위에 올라가요","r":"북극곰이 되어 빙하 위에 있어요"},{"l":"종이를 반으로 접어요","r":"빙하의 크기가 작아지는 모습이에요"},{"l":"작아지는 종이 위에서 버텨요","r":"북극곰이 살기가 어려워지는 모습이에요"},{"l":"느낀 점을 이야기해요","r":"북극곰을 돕고 싶은 마음을 나누어요"}],"mis":"SC4-2-u4-X05","explanation":["흰 종이는 빙하예요.","접으면 작아져요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_basic#7','sci',4,2,'u4','L01','g4_2_sci_u4_L01_basic','lesson_basic','SC4-2-u4-C3',2,'mc','auto','종이를 접을수록 무엇이 달라졌나요?',ARRAY['SC4-2-u4-X06']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C3","difficulty":2,"kind":"mc","stem":"종이를 접을수록 무엇이 달라졌나요?","options":[{"t":"올라설 자리는 줄어들고 모둠 친구 수는 그대로였다","correct":true},{"t":"올라설 자리와 모둠 친구 수가 함께 줄어들었다","mis":"SC4-2-u4-X06"},{"t":"올라설 자리가 점점 넓어졌다","mis":"SC4-2-u4-X06"},{"t":"아무것도 달라지지 않았다","mis":"SC4-2-u4-X06"}],"explanation":["표의 두 칸을 견줘요.","자리는 8, 4, 2, 1칸이에요.","친구는 늘 4명이에요."],"asset":{"type":"passage","lines":["처음 — 올라설 자리 8칸 · 모둠 친구 4명","한 번 접음 — 올라설 자리 4칸 · 모둠 친구 4명","두 번 접음 — 올라설 자리 2칸 · 모둠 친구 4명","세 번 접음 — 올라설 자리 1칸 · 모둠 친구 4명"],"title":"흰 종이를 접을 때마다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_basic#8','sci',4,2,'u4','L01','g4_2_sci_u4_L01_basic','lesson_basic','SC4-2-u4-C1',2,'ox','auto','북극곰의 편지에 따르면 북극의 빙하가 작아진 까닭은 기후 변화 때문이에요.',ARRAY['SC4-2-u4-X02']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C1","difficulty":2,"kind":"ox","stem":"북극곰의 편지에 따르면 북극의 빙하가 작아진 까닭은 기후 변화 때문이에요.","answer":"O","reason_options":[{"t":"편지에 그 까닭이 기후 변화 때문이라고 쓰여 있기 때문에","correct":true},{"t":"북극곰들이 빙하 위에서 너무 많이 뛰어놀았기 때문에","mis":"SC4-2-u4-X02"}],"mis":"SC4-2-u4-X02","explanation":["편지 넷째 줄을 읽어요.","까닭이 쓰여 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["친구들아, 안녕? 나는 북극에 사는 북극곰이야.","북극은 원래 많이 추운 곳이었어.","요즈음에는 많이 춥지 않고, 빙하의 크기도 많이 작아졌어.","그 까닭이 기후 변화 때문이래.","북극에서 계속 살려면 친구들의 도움이 필요해."],"title":"북극곰의 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_basic#9','sci',4,2,'u4','L01','g4_2_sci_u4_L01_basic','lesson_basic','SC4-2-u4-C4',2,'mc','auto','놀이를 하며 느낀 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u4-X04','SC4-2-u4-X08','SC4-2-u4-X07']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C4","difficulty":2,"kind":"mc","stem":"놀이를 하며 느낀 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"점점 작아지는 종이 위에서 버티며 북극곰의 마음을 이해하게 됐다","correct":true},{"t":"가장 오래 버틴 모둠이 이긴 것이 가장 중요하다","mis":"SC4-2-u4-X04"},{"t":"무섭기만 하고 할 수 있는 일이 없다","mis":"SC4-2-u4-X08"},{"t":"북극의 일이라 우리와는 상관없다","mis":"SC4-2-u4-X07"}],"explanation":["놀이의 뜻을 떠올려요.","북극곰이 되어 보았어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_basic#10','sci',4,2,'u4','L01','g4_2_sci_u4_L01_basic','lesson_basic','SC4-2-u4-C2',3,'mc','auto','종이를 접을 때 가장 알맞은 행동은 무엇인가요?',ARRAY['SC4-2-u4-X03']::text[],false,'{"seq":10,"concept":"SC4-2-u4-C2","difficulty":3,"kind":"mc","stem":"종이를 접을 때 가장 알맞은 행동은 무엇인가요?","options":[{"t":"선생님의 신호를 잘 듣고 신호에 맞추어 접는다","correct":true},{"t":"신호를 기다리지 않고 마음대로 접는다","mis":"SC4-2-u4-X03"},{"t":"자리를 차지하려고 친구를 민다","mis":"SC4-2-u4-X03"},{"t":"발이 종이 밖으로 나가도 버틴 것으로 친다","mis":"SC4-2-u4-X03"}],"explanation":["놀이 차례를 떠올려요.","신호에 따라 접어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_challenge#1','sci',4,2,'u4','L01','g4_2_sci_u4_L01_challenge','lesson_challenge','SC4-2-u4-C1',2,'blank','auto','「북극은 (    ) 많이 추운 곳인데, 요즈음에는 많이 춥지 않아요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u4-X01']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C1","difficulty":2,"kind":"blank","stem":"「북극은 (    ) 많이 추운 곳인데, 요즈음에는 많이 춥지 않아요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"원래","correct":true},{"t":"앞으로","mis":"SC4-2-u4-X01"},{"t":"갑자기","mis":"SC4-2-u4-X01"},{"t":"내일부터","mis":"SC4-2-u4-X01"}],"explanation":["예전과 지금을 견줘요.","예전에는 추웠어요.","원래예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_challenge#2','sci',4,2,'u4','L01','g4_2_sci_u4_L01_challenge','lesson_challenge','SC4-2-u4-C3',2,'mc','auto','흰 종이를 반으로 접는 것은 무엇을 의미할까요?',ARRAY['SC4-2-u4-X04','SC4-2-u4-X05']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C3","difficulty":2,"kind":"mc","stem":"흰 종이를 반으로 접는 것은 무엇을 의미할까요?","options":[{"t":"기후 변화로 녹아서 크기가 점점 작아지는 빙하","correct":true},{"t":"누가 더 오래 버티는지 겨루는 규칙","mis":"SC4-2-u4-X04"},{"t":"종이를 아껴 쓰자는 약속","mis":"SC4-2-u4-X05"},{"t":"종이접기 솜씨를 기르는 연습","mis":"SC4-2-u4-X05"}],"explanation":["흰 종이는 빙하예요.","접으면 작아져요.","작아지는 빙하예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_challenge#3','sci',4,2,'u4','L01','g4_2_sci_u4_L01_challenge','lesson_challenge','SC4-2-u4-C3',3,'error','auto','놀이를 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u4-X04','SC4-2-u4-X06','SC4-2-u4-X05']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C3","difficulty":3,"kind":"error","stem":"놀이를 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「우리 모둠이 가장 오래 버텼으니 이긴 거야.」","correct":true,"mis_target":"SC4-2-u4-X04"},{"t":"친구 나 — 「종이가 작아질수록 버티기 힘들었어.」","mis":"SC4-2-u4-X06"},{"t":"친구 다 — 「작아지는 종이는 녹는 빙하를 뜻해.」","mis":"SC4-2-u4-X05"}],"explanation":["놀이의 뜻을 떠올려요.","겨루는 놀이가 아니에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_challenge#4','sci',4,2,'u4','L01','g4_2_sci_u4_L01_challenge','lesson_challenge','SC4-2-u4-C1',3,'mc','auto','편지를 읽고 원래 북극과 요즈음 북극을 바르게 견준 것은 무엇인가요?',ARRAY['SC4-2-u4-X01']::text[],false,'{"seq":4,"concept":"SC4-2-u4-C1","difficulty":3,"kind":"mc","stem":"편지를 읽고 원래 북극과 요즈음 북극을 바르게 견준 것은 무엇인가요?","options":[{"t":"원래는 많이 추웠지만 요즈음에는 많이 춥지 않다","correct":true},{"t":"원래는 춥지 않았지만 요즈음에는 많이 춥다","mis":"SC4-2-u4-X01"},{"t":"원래도 요즈음도 빙하의 크기는 같다","mis":"SC4-2-u4-X01"},{"t":"원래는 빙하가 작았지만 요즈음에는 커졌다","mis":"SC4-2-u4-X01"}],"explanation":["둘째와 셋째 줄을 견줘요.","날씨와 빙하가 달라졌어요.","첫 번째예요."],"asset":{"type":"passage","lines":["친구들아, 안녕? 나는 북극에 사는 북극곰이야.","북극은 원래 많이 추운 곳이었어.","요즈음에는 많이 춥지 않고, 빙하의 크기도 많이 작아졌어.","그 까닭이 기후 변화 때문이래.","북극에서 계속 살려면 친구들의 도움이 필요해."],"title":"북극곰의 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_challenge#5','sci',4,2,'u4','L01','g4_2_sci_u4_L01_challenge','lesson_challenge','SC4-2-u4-C4',3,'ox','auto','북극에서 일어나는 일이니 우리와는 상관없어요.',ARRAY['SC4-2-u4-X07']::text[],false,'{"seq":5,"concept":"SC4-2-u4-C4","difficulty":3,"kind":"ox","stem":"북극에서 일어나는 일이니 우리와는 상관없어요.","answer":"X","reason_options":[{"t":"북극곰이 친구들의 도움이 필요하다고 했고 기후 변화는 우리 모두의 관심이 필요하기 때문에","correct":true},{"t":"멀리 떨어진 곳의 일은 우리와 관계가 없기 때문에","mis":"SC4-2-u4-X07"}],"mis":"SC4-2-u4-X07","explanation":["편지 끝 줄을 떠올려요.","도움이 필요하대요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_challenge#6','sci',4,2,'u4','L01','g4_2_sci_u4_L01_challenge','lesson_challenge','SC4-2-u4-C3',3,'mc','auto','세 번 접었을 때 버티기가 가장 힘든 까닭은 무엇인가요?',ARRAY['SC4-2-u4-X06','SC4-2-u4-X04']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C3","difficulty":3,"kind":"mc","stem":"세 번 접었을 때 버티기가 가장 힘든 까닭은 무엇인가요?","options":[{"t":"올라설 자리는 가장 작아졌는데 모둠 친구 수는 그대로이기 때문에","correct":true},{"t":"모둠 친구 수가 가장 많아졌기 때문에","mis":"SC4-2-u4-X06"},{"t":"종이가 가장 넓어졌기 때문에","mis":"SC4-2-u4-X06"},{"t":"다른 모둠과 겨루어 이겨야 하기 때문에","mis":"SC4-2-u4-X04"}],"explanation":["마지막 줄을 읽어요.","자리는 1칸이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["처음 — 올라설 자리 8칸 · 모둠 친구 4명","한 번 접음 — 올라설 자리 4칸 · 모둠 친구 4명","두 번 접음 — 올라설 자리 2칸 · 모둠 친구 4명","세 번 접음 — 올라설 자리 1칸 · 모둠 친구 4명"],"title":"흰 종이를 접을 때마다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_challenge#7','sci',4,2,'u4','L01','g4_2_sci_u4_L01_challenge','lesson_challenge','SC4-2-u4-C4',3,'mc','auto','놀이를 마친 뒤 가장 알맞은 다짐은 무엇인가요?',ARRAY['SC4-2-u4-X08','SC4-2-u4-X04','SC4-2-u4-X07']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C4","difficulty":3,"kind":"mc","stem":"놀이를 마친 뒤 가장 알맞은 다짐은 무엇인가요?","options":[{"t":"지구가 뜨거워지지 않도록 돕고 싶은 마음으로 기후 변화에 관심을 가진다","correct":true},{"t":"너무 무서워서 아무것도 하지 않는다","mis":"SC4-2-u4-X08"},{"t":"다음 놀이에서 꼭 이기도록 연습한다","mis":"SC4-2-u4-X04"},{"t":"북극곰 일이니 모른 척한다","mis":"SC4-2-u4-X07"}],"explanation":["느낀 점을 떠올려요.","돕고 싶은 마음이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_challenge#8','sci',4,2,'u4','L01','g4_2_sci_u4_L01_challenge','lesson_challenge','SC4-2-u4-C3',4,'mc','auto','친구가 「종이를 접는 건 그냥 놀이 규칙이야. 빙하랑은 상관없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X04','SC4-2-u4-X05','SC4-2-u4-X06']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C3","difficulty":4,"kind":"mc","stem":"친구가 「종이를 접는 건 그냥 놀이 규칙이야. 빙하랑은 상관없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「흰 종이는 빙하이고, 접을수록 작아지는 종이는 기후 변화로 녹아 작아지는 빙하를 뜻해.」","correct":true},{"t":"「맞아, 오래 버티는 게 제일 중요해.」","mis":"SC4-2-u4-X04"},{"t":"「종이를 아끼려고 접는 거야.」","mis":"SC4-2-u4-X05"},{"t":"「접을수록 올라설 자리가 넓어져.」","mis":"SC4-2-u4-X06"}],"explanation":["흰 종이의 뜻을 떠올려요.","작아지는 빙하예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_challenge#9','sci',4,2,'u4','L01','g4_2_sci_u4_L01_challenge','lesson_challenge','SC4-2-u4-C4',4,'mc','auto','친구가 「기후 변화 이야기는 너무 무서워. 내가 할 수 있는 일은 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X08','SC4-2-u4-X07','SC4-2-u4-X04']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C4","difficulty":4,"kind":"mc","stem":"친구가 「기후 변화 이야기는 너무 무서워. 내가 할 수 있는 일은 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「북극곰의 마음을 이해했으니 기후 변화에 관심을 가지고 도울 방법을 함께 찾아보자.」","correct":true},{"t":"「맞아, 걱정만 하자.」","mis":"SC4-2-u4-X08"},{"t":"「북극 일은 우리랑 상관없어.」","mis":"SC4-2-u4-X07"},{"t":"「놀이에서 이기면 괜찮아져.」","mis":"SC4-2-u4-X04"}],"explanation":["느낀 점을 떠올려요.","도울 수 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L01_challenge#10','sci',4,2,'u4','L01','g4_2_sci_u4_L01_challenge','lesson_challenge','SC4-2-u4-C3',4,'essay','teacher','줄어드는 빙하 놀이에서 종이를 반으로 접는 것이 무엇을 뜻하는지 쓰고, 놀이를 하며 든 생각을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u4-C3","difficulty":4,"kind":"essay","stem":"줄어드는 빙하 놀이에서 종이를 반으로 접는 것이 무엇을 뜻하는지 쓰고, 놀이를 하며 든 생각을 쓰세요.","answer_guide":{"answer":"예: 흰 종이를 반으로 접는 것은 기후 변화로 녹아서 크기가 점점 작아지는 빙하를 뜻한다. 작아지는 종이 위에서 버티기 힘들어 북극곰의 마음을 이해하게 되었고, 기후 변화에 관심을 가지고 돕고 싶은 마음이 생겼다.","scoring_points":["접는 종이의 뜻을 썼는가","작아지는 자리와 버티기 힘든 까닭을 이었는가","관심이나 돕고 싶은 마음을 썼는가"]},"explanation":["놀이를 떠올려요.","뜻을 써요.","든 생각을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_basic#1','sci',4,2,'u4','L02','g4_2_sci_u4_L02_basic','lesson_basic','SC4-2-u4-C5',1,'mc','auto','가뭄, 폭염, 홍수, 폭설, 한파 같은 자연재해는 요즈음 어떻게 되고 있나요?',ARRAY['SC4-2-u4-X10','SC4-2-u4-X09']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C5","difficulty":1,"kind":"mc","stem":"가뭄, 폭염, 홍수, 폭설, 한파 같은 자연재해는 요즈음 어떻게 되고 있나요?","options":[{"t":"점점 심해지고 있다","correct":true},{"t":"점점 약해지고 있다","mis":"SC4-2-u4-X10"},{"t":"예전과 똑같다","mis":"SC4-2-u4-X10"},{"t":"다른 나라에서만 일어난다","mis":"SC4-2-u4-X09"}],"explanation":["뉴스를 떠올려요.","더 자주, 더 크게 일어나요.","점점 심해지고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_basic#2','sci',4,2,'u4','L02','g4_2_sci_u4_L02_basic','lesson_basic','SC4-2-u4-C8',1,'mc','auto','기후 변화로 비가 갑자기 많이 내리면 무엇이 발생하기도 하나요?',ARRAY['SC4-2-u4-X13','SC4-2-u4-X12']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C8","difficulty":1,"kind":"mc","stem":"기후 변화로 비가 갑자기 많이 내리면 무엇이 발생하기도 하나요?","options":[{"t":"홍수","correct":true},{"t":"한파","mis":"SC4-2-u4-X13"},{"t":"폭염","mis":"SC4-2-u4-X12"},{"t":"가뭄","mis":"SC4-2-u4-X13"}],"explanation":["비가 많이 와요.","물이 넘쳐요.","홍수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_basic#3','sci',4,2,'u4','L02','g4_2_sci_u4_L02_basic','lesson_basic','SC4-2-u4-C6',1,'ox','auto','우리나라 연평균 기온 그래프를 보면 연도별 평균 기온이 점차 상승하고 있어요.',ARRAY['SC4-2-u4-X11']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C6","difficulty":1,"kind":"ox","stem":"우리나라 연평균 기온 그래프를 보면 연도별 평균 기온이 점차 상승하고 있어요.","answer":"O","reason_options":[{"t":"그래프에서 평균 기온이 점점 높아지기 때문에","correct":true},{"t":"평균 기온은 해마다 늘 똑같기 때문에","mis":"SC4-2-u4-X11"}],"mis":"SC4-2-u4-X11","explanation":["그래프를 떠올려요.","점점 높아져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_basic#4','sci',4,2,'u4','L02','g4_2_sci_u4_L02_basic','lesson_basic','SC4-2-u4-C7',1,'sa','auto','낮 최고기온이 33 ℃ 이상인 매우 더운 날씨를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u4-C7","difficulty":1,"kind":"sa","stem":"낮 최고기온이 33 ℃ 이상인 매우 더운 날씨를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["폭염"],"explanation":["아주 더운 날씨예요.","여름에 나타나요.","폭염이에요."],"mis":"SC4-2-u4-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_basic#5','sci',4,2,'u4','L02','g4_2_sci_u4_L02_basic','lesson_basic','SC4-2-u4-C8',2,'match','auto','카드의 변화와 나타날 수 있는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-2-u4-C8","difficulty":2,"kind":"match","stem":"카드의 변화와 나타날 수 있는 일을 알맞게 이으세요.","pairs":[{"l":"폭염 일수가 늘었어요","r":"여름에 장기간 폭염이 발생해요"},{"l":"한파 일수가 늘었어요","r":"겨울에 강한 한파가 발생해요"},{"l":"연간 강수량이 늘었어요","r":"홍수가 심해질 수 있어요"},{"l":"가을~봄 강수량이 줄었어요","r":"가뭄이 심해질 수 있어요"}],"mis":"SC4-2-u4-X13","explanation":["카드 네 장을 떠올려요.","비가 늘면 홍수, 줄면 가뭄이에요.","하나씩 이어요."],"asset":{"type":"passage","lines":["폭염 일수 — 예전보다 늘었어요.","한파 일수 — 예전보다 늘었어요.","연간 강수량 — 예전보다 늘었어요.","가을~봄 강수량 — 예전보다 줄었어요."],"title":"기후 변화 현상 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_basic#6','sci',4,2,'u4','L02','g4_2_sci_u4_L02_basic','lesson_basic','SC4-2-u4-C7',2,'mc','auto','기온이 영하 12 ℃ 이하로 떨어지는 날씨를 무엇이라고 하나요?',ARRAY['SC4-2-u4-X12','SC4-2-u4-X15']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C7","difficulty":2,"kind":"mc","stem":"기온이 영하 12 ℃ 이하로 떨어지는 날씨를 무엇이라고 하나요?","options":[{"t":"한파","correct":true},{"t":"폭염","mis":"SC4-2-u4-X12"},{"t":"홍수","mis":"SC4-2-u4-X15"},{"t":"가뭄","mis":"SC4-2-u4-X15"}],"explanation":["아주 추운 날씨예요.","겨울에 나타나요.","한파예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_basic#7','sci',4,2,'u4','L02','g4_2_sci_u4_L02_basic','lesson_basic','SC4-2-u4-C8',2,'mc','auto','카드에서 예전보다 줄어든 것은 무엇인가요?',ARRAY['SC4-2-u4-X14']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C8","difficulty":2,"kind":"mc","stem":"카드에서 예전보다 줄어든 것은 무엇인가요?","options":[{"t":"가을~봄 강수량","correct":true},{"t":"폭염 일수","mis":"SC4-2-u4-X14"},{"t":"한파 일수","mis":"SC4-2-u4-X14"},{"t":"연간 강수량","mis":"SC4-2-u4-X14"}],"explanation":["네 줄을 읽어요.","하나만 줄었어요.","가을~봄 강수량이에요."],"asset":{"type":"passage","lines":["폭염 일수 — 예전보다 늘었어요.","한파 일수 — 예전보다 늘었어요.","연간 강수량 — 예전보다 늘었어요.","가을~봄 강수량 — 예전보다 줄었어요."],"title":"기후 변화 현상 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_basic#8','sci',4,2,'u4','L02','g4_2_sci_u4_L02_basic','lesson_basic','SC4-2-u4-C5',2,'ox','auto','기후 변화 현상은 다른 나라에서만 일어나고 우리나라에서는 일어나지 않아요.',ARRAY['SC4-2-u4-X09']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C5","difficulty":2,"kind":"ox","stem":"기후 변화 현상은 다른 나라에서만 일어나고 우리나라에서는 일어나지 않아요.","answer":"X","reason_options":[{"t":"우리나라에서도 폭염, 한파, 가뭄, 홍수, 폭설이 일어나고 있기 때문에","correct":true},{"t":"우리나라는 기후 변화가 없는 나라이기 때문에","mis":"SC4-2-u4-X09"}],"mis":"SC4-2-u4-X09","explanation":["카드의 사진을 떠올려요.","우리나라 이야기예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_basic#9','sci',4,2,'u4','L02','g4_2_sci_u4_L02_basic','lesson_basic','SC4-2-u4-C9',2,'mc','auto','최근 폭염, 한파, 가뭄, 홍수, 폭설은 어떻게 나타나고 있나요?',ARRAY['SC4-2-u4-X10','SC4-2-u4-X09']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C9","difficulty":2,"kind":"mc","stem":"최근 폭염, 한파, 가뭄, 홍수, 폭설은 어떻게 나타나고 있나요?","options":[{"t":"규모가 점차 커지고 더욱 자주 발생한다","correct":true},{"t":"규모가 작아지고 드물게 발생한다","mis":"SC4-2-u4-X10"},{"t":"규모는 커지지만 아주 드물게 발생한다","mis":"SC4-2-u4-X10"},{"t":"우리나라에서는 하나도 발생하지 않는다","mis":"SC4-2-u4-X09"}],"explanation":["카드를 모두 보았어요.","크기와 횟수를 봐요.","커지고 자주 일어나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_basic#10','sci',4,2,'u4','L02','g4_2_sci_u4_L02_basic','lesson_basic','SC4-2-u4-C9',3,'mc','auto','사람과 동물, 식물에게 큰 피해를 주는 산불이 더 자주 일어나는 까닭은 무엇일까요?',ARRAY['SC4-2-u4-X16']::text[],false,'{"seq":10,"concept":"SC4-2-u4-C9","difficulty":3,"kind":"mc","stem":"사람과 동물, 식물에게 큰 피해를 주는 산불이 더 자주 일어나는 까닭은 무엇일까요?","options":[{"t":"기후 변화로 온도가 높아지고 건조한 날씨가 늘어나기 때문에","correct":true},{"t":"비가 갑자기 많이 내리기 때문에","mis":"SC4-2-u4-X16"},{"t":"겨울에 강한 한파가 발생하기 때문에","mis":"SC4-2-u4-X16"},{"t":"폭설로 눈이 많이 쌓이기 때문에","mis":"SC4-2-u4-X16"}],"explanation":["불이 잘 붙는 날씨를 떠올려요.","덥고 메말라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_challenge#1','sci',4,2,'u4','L02','g4_2_sci_u4_L02_challenge','lesson_challenge','SC4-2-u4-C8',2,'blank','auto','「강수량이 급격히 줄어들면 극심한 (    )이 발생해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u4-X13','SC4-2-u4-X15']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C8","difficulty":2,"kind":"blank","stem":"「강수량이 급격히 줄어들면 극심한 (    )이 발생해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"가뭄","correct":true},{"t":"홍수","mis":"SC4-2-u4-X13"},{"t":"폭설","mis":"SC4-2-u4-X13"},{"t":"한파","mis":"SC4-2-u4-X15"}],"explanation":["비가 적게 와요.","땅이 메말라요.","가뭄이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_challenge#2','sci',4,2,'u4','L02','g4_2_sci_u4_L02_challenge','lesson_challenge','SC4-2-u4-C7',2,'mc','auto','여름에 많이 나타나는 기후 변화 현상은 무엇인가요?',ARRAY['SC4-2-u4-X12','SC4-2-u4-X15']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C7","difficulty":2,"kind":"mc","stem":"여름에 많이 나타나는 기후 변화 현상은 무엇인가요?","options":[{"t":"오래 이어지는 폭염","correct":true},{"t":"강한 한파","mis":"SC4-2-u4-X12"},{"t":"영하 12 ℃ 이하로 떨어지는 날씨","mis":"SC4-2-u4-X12"},{"t":"가을~봄에 줄어드는 강수량","mis":"SC4-2-u4-X15"}],"explanation":["여름 날씨를 떠올려요.","아주 더워요.","폭염이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_challenge#3','sci',4,2,'u4','L02','g4_2_sci_u4_L02_challenge','lesson_challenge','SC4-2-u4-C8',3,'error','auto','카드를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u4-X14','SC4-2-u4-X13']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C8","difficulty":3,"kind":"error","stem":"카드를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「가을~봄 강수량이 늘어서 가뭄이 심해질 수 있어.」","correct":true,"mis_target":"SC4-2-u4-X14"},{"t":"친구 가 — 「연간 강수량이 늘어서 홍수가 심해질 수 있어.」","mis":"SC4-2-u4-X13"},{"t":"친구 다 — 「폭염 일수와 한파 일수가 모두 늘었어.」","mis":"SC4-2-u4-X14"}],"explanation":["넷째 줄을 읽어요.","가을~봄 강수량은 줄었어요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["폭염 일수 — 예전보다 늘었어요.","한파 일수 — 예전보다 늘었어요.","연간 강수량 — 예전보다 늘었어요.","가을~봄 강수량 — 예전보다 줄었어요."],"title":"기후 변화 현상 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_challenge#4','sci',4,2,'u4','L02','g4_2_sci_u4_L02_challenge','lesson_challenge','SC4-2-u4-C7',3,'mc','auto','카드에 나온 변화 가운데 「기온」의 변화끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u4-X15']::text[],false,'{"seq":4,"concept":"SC4-2-u4-C7","difficulty":3,"kind":"mc","stem":"카드에 나온 변화 가운데 「기온」의 변화끼리 묶은 것은 무엇인가요?","options":[{"t":"폭염 일수, 한파 일수","correct":true},{"t":"연간 강수량, 가을~봄 강수량","mis":"SC4-2-u4-X15"},{"t":"폭염 일수, 연간 강수량","mis":"SC4-2-u4-X15"},{"t":"한파 일수, 가을~봄 강수량","mis":"SC4-2-u4-X15"}],"explanation":["덥고 추운 것을 찾아요.","강수량은 비와 눈의 양이에요.","폭염과 한파예요."],"asset":{"type":"passage","lines":["폭염 일수 — 예전보다 늘었어요.","한파 일수 — 예전보다 늘었어요.","연간 강수량 — 예전보다 늘었어요.","가을~봄 강수량 — 예전보다 줄었어요."],"title":"기후 변화 현상 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_challenge#5','sci',4,2,'u4','L02','g4_2_sci_u4_L02_challenge','lesson_challenge','SC4-2-u4-C8',3,'ox','auto','강수량이 급격히 늘어나면 기습 폭우로 인한 홍수나 폭설이 발생할 수 있어요.',ARRAY['SC4-2-u4-X13']::text[],false,'{"seq":5,"concept":"SC4-2-u4-C8","difficulty":3,"kind":"ox","stem":"강수량이 급격히 늘어나면 기습 폭우로 인한 홍수나 폭설이 발생할 수 있어요.","answer":"O","reason_options":[{"t":"비나 눈이 한꺼번에 많이 내리기 때문에","correct":true},{"t":"강수량이 늘면 땅이 메말라 가뭄이 생기기 때문에","mis":"SC4-2-u4-X13"}],"mis":"SC4-2-u4-X13","explanation":["비가 많이 오면 어떻게 될까요?","물이 넘쳐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_challenge#6','sci',4,2,'u4','L02','g4_2_sci_u4_L02_challenge','lesson_challenge','SC4-2-u4-C6',3,'mc','auto','우리나라 연평균 기온 그래프를 보고 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u4-X11']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C6","difficulty":3,"kind":"mc","stem":"우리나라 연평균 기온 그래프를 보고 알 수 있는 것은 무엇인가요?","options":[{"t":"연도별 평균 기온이 점차 상승한다","correct":true},{"t":"연도별 평균 기온이 점차 낮아진다","mis":"SC4-2-u4-X11"},{"t":"연도별 평균 기온이 늘 똑같다","mis":"SC4-2-u4-X11"},{"t":"그래프로는 기온을 알 수 없다","mis":"SC4-2-u4-X11"}],"explanation":["그래프 모양을 떠올려요.","점점 올라가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_challenge#7','sci',4,2,'u4','L02','g4_2_sci_u4_L02_challenge','lesson_challenge','SC4-2-u4-C5',3,'mc','auto','「지난여름 비가 많이 내려 도로와 집들이 물에 잠겼어요.」 이 경험은 무엇과 관련 있나요?',ARRAY['SC4-2-u4-X15','SC4-2-u4-X09','SC4-2-u4-X10']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C5","difficulty":3,"kind":"mc","stem":"「지난여름 비가 많이 내려 도로와 집들이 물에 잠겼어요.」 이 경험은 무엇과 관련 있나요?","options":[{"t":"기후 변화로 심해지는 홍수","correct":true},{"t":"기후 변화로 심해지는 한파","mis":"SC4-2-u4-X15"},{"t":"다른 나라에서만 일어나는 일","mis":"SC4-2-u4-X09"},{"t":"점점 줄어드는 자연재해","mis":"SC4-2-u4-X10"}],"explanation":["비가 많이 왔어요.","물에 잠겼어요.","홍수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_challenge#8','sci',4,2,'u4','L02','g4_2_sci_u4_L02_challenge','lesson_challenge','SC4-2-u4-C9',4,'mc','auto','친구가 「요즘 산불이 자주 나는 건 비가 많이 와서야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X16','SC4-2-u4-X10']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C9","difficulty":4,"kind":"mc","stem":"친구가 「요즘 산불이 자주 나는 건 비가 많이 와서야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「기후 변화로 온도가 높아지고 건조한 날씨가 늘어서 산불이 더 자주 일어나는 거야.」","correct":true},{"t":"「맞아, 비가 많이 오면 불이 잘 나.」","mis":"SC4-2-u4-X16"},{"t":"「한파 때문이야.」","mis":"SC4-2-u4-X16"},{"t":"「산불은 예전보다 줄어들었어.」","mis":"SC4-2-u4-X10"}],"explanation":["불이 잘 붙는 날씨를 떠올려요.","덥고 건조해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_challenge#9','sci',4,2,'u4','L02','g4_2_sci_u4_L02_challenge','lesson_challenge','SC4-2-u4-C8',4,'mc','auto','친구가 「연간 강수량이 늘었으니 가뭄 걱정은 전혀 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X14','SC4-2-u4-X13','SC4-2-u4-X15']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C8","difficulty":4,"kind":"mc","stem":"친구가 「연간 강수량이 늘었으니 가뭄 걱정은 전혀 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「한 해 강수량은 늘었지만 가을~봄 강수량은 줄어서 가뭄이 심해질 수 있어.」","correct":true},{"t":"「맞아, 비가 많으면 가뭄은 없어.」","mis":"SC4-2-u4-X14"},{"t":"「강수량이 늘면 가뭄이 생겨.」","mis":"SC4-2-u4-X13"},{"t":"「강수량은 기온의 변화야.」","mis":"SC4-2-u4-X15"}],"explanation":["카드 두 장을 견줘요.","가을~봄 강수량은 줄었어요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["폭염 일수 — 예전보다 늘었어요.","한파 일수 — 예전보다 늘었어요.","연간 강수량 — 예전보다 늘었어요.","가을~봄 강수량 — 예전보다 줄었어요."],"title":"기후 변화 현상 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L02_challenge#10','sci',4,2,'u4','L02','g4_2_sci_u4_L02_challenge','lesson_challenge','SC4-2-u4-C9',4,'essay','teacher','기후 변화 현상 카드 가운데 두 장을 골라 어떻게 달라졌는지와 나타날 수 있는 일을 쓰고, 우리나라의 자연재해가 어떻게 되고 있는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u4-C9","difficulty":4,"kind":"essay","stem":"기후 변화 현상 카드 가운데 두 장을 골라 어떻게 달라졌는지와 나타날 수 있는 일을 쓰고, 우리나라의 자연재해가 어떻게 되고 있는지 쓰세요.","answer_guide":{"answer":"예: 폭염 일수가 늘어 여름에 장기간 폭염이 발생하고, 연간 강수량이 늘어 홍수가 심해질 수 있다. 우리나라에서도 폭염, 한파, 가뭄, 홍수, 폭설 등의 규모가 점차 커지고 더욱 자주 발생하고 있다.","scoring_points":["카드 한 장의 변화와 나타날 일을 썼는가","카드 또 한 장의 변화와 나타날 일을 썼는가","자연재해가 커지고 자주 발생함을 썼는가"]},"explanation":["카드를 골라요.","변화와 나타날 일을 이어요.","우리나라를 정리해요."],"asset":{"type":"passage","lines":["폭염 일수 — 예전보다 늘었어요.","한파 일수 — 예전보다 늘었어요.","연간 강수량 — 예전보다 늘었어요.","가을~봄 강수량 — 예전보다 줄었어요."],"title":"기후 변화 현상 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_basic#1','sci',4,2,'u4','L03','g4_2_sci_u4_L03_basic','lesson_basic','SC4-2-u4-C10',1,'mc','auto','기후 변화는 무엇과 관련이 있나요?',ARRAY['SC4-2-u4-X17','SC4-2-u4-X18']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C10","difficulty":1,"kind":"mc","stem":"기후 변화는 무엇과 관련이 있나요?","options":[{"t":"자연에 의해서도 일어나지만 인간의 활동과도 관련이 있다","correct":true},{"t":"자연에 의해서만 일어난다","mis":"SC4-2-u4-X17"},{"t":"인간의 활동과 아무 관련이 없다","mis":"SC4-2-u4-X17"},{"t":"사람이 하는 모든 일 때문에만 일어난다","mis":"SC4-2-u4-X18"}],"explanation":["오늘 공부의 첫 문장을 떠올려요.","자연과 사람 둘 다예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_basic#2','sci',4,2,'u4','L03','g4_2_sci_u4_L03_basic','lesson_basic','SC4-2-u4-C13',1,'mc','auto','쓰레기 양을 줄이는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u4-X22']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C13","difficulty":1,"kind":"mc","stem":"쓰레기 양을 줄이는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"일회용품의 사용을 줄인다","correct":true},{"t":"일회용품을 더 많이 사용한다","mis":"SC4-2-u4-X22"},{"t":"물건을 자주 새로 산다","mis":"SC4-2-u4-X22"},{"t":"포장을 여러 겹으로 한다","mis":"SC4-2-u4-X22"}],"explanation":["쓰레기가 생기는 까닭을 떠올려요.","한 번 쓰고 버리는 물건이에요.","일회용품을 줄여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_basic#3','sci',4,2,'u4','L03','g4_2_sci_u4_L03_basic','lesson_basic','SC4-2-u4-C15',1,'ox','auto','토의할 때에는 다른 사람의 의견을 주의 깊게 들어요.',ARRAY['SC4-2-u4-X24']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C15","difficulty":1,"kind":"ox","stem":"토의할 때에는 다른 사람의 의견을 주의 깊게 들어요.","answer":"O","reason_options":[{"t":"친구의 생각을 들어야 함께 더 좋은 생각을 모을 수 있기 때문에","correct":true},{"t":"내 의견만 계속 주장하면 토의를 빨리 끝낼 수 있기 때문에","mis":"SC4-2-u4-X24"}],"mis":"SC4-2-u4-X24","explanation":["토의의 약속을 떠올려요.","듣는 것이 중요해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_basic#4','sci',4,2,'u4','L03','g4_2_sci_u4_L03_basic','lesson_basic','SC4-2-u4-C12',1,'sa','auto','교통수단을 움직이거나 공장에서 물건을 만들 때 쓰는 연료를 무엇이라고 하나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u4-C12","difficulty":1,"kind":"sa","stem":"교통수단을 움직이거나 공장에서 물건을 만들 때 쓰는 연료를 무엇이라고 하나요? 다섯 글자로 쓰세요.","answer":["화석 연료","화석연료"],"explanation":["붙임딱지 둘째 장이에요.","「화석」으로 시작해요.","화석 연료예요."],"mis":"SC4-2-u4-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_basic#5','sci',4,2,'u4','L03','g4_2_sci_u4_L03_basic','lesson_basic','SC4-2-u4-C11',2,'match','auto','붙임딱지와 그림 속 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-2-u4-C11","difficulty":2,"kind":"match","stem":"붙임딱지와 그림 속 모습을 알맞게 이으세요.","pairs":[{"l":"숲을 파괴하고 건물을 지어요","r":"건물을 짓기 위해 나무를 베어요"},{"l":"화석 연료를 사용해요","r":"교통수단을 움직이거나 공장에서 물건을 만들어요"},{"l":"쓰레기를 많이 버려요","r":"무분별하게 많은 양을 버려요"},{"l":"에너지를 많이 사용해요","r":"과도하게 쓰는 전기 에너지를 만들어요"}],"mis":"SC4-2-u4-X20","explanation":["붙임딱지 네 장을 떠올려요.","그림 속 모습을 찾아요.","하나씩 이어요."],"asset":{"type":"passage","lines":["숲을 파괴하고 건물을 지어요","화석 연료를 사용해요","쓰레기를 많이 버려요","에너지를 많이 사용해요"],"title":"인간의 활동 붙임딱지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_basic#6','sci',4,2,'u4','L03','g4_2_sci_u4_L03_basic','lesson_basic','SC4-2-u4-C13',2,'mc','auto','난방을 필요 이상으로 하는 것은 기후 변화에 어떤 영향을 줄까요?',ARRAY['SC4-2-u4-X23']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C13","difficulty":2,"kind":"mc","stem":"난방을 필요 이상으로 하는 것은 기후 변화에 어떤 영향을 줄까요?","options":[{"t":"전기가 많이 필요해 기후 변화가 심각해지는 데 영향을 준다","correct":true},{"t":"기후 변화와 아무 관련이 없다","mis":"SC4-2-u4-X23"},{"t":"난방을 많이 할수록 기후 변화가 줄어든다","mis":"SC4-2-u4-X23"},{"t":"난방에는 전기가 필요 없다","mis":"SC4-2-u4-X23"}],"explanation":["난방 기구를 떠올려요.","전기가 많이 들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_basic#7','sci',4,2,'u4','L03','g4_2_sci_u4_L03_basic','lesson_basic','SC4-2-u4-C12',2,'mc','auto','화석 연료를 과도하게 사용하는 모습은 무엇인가요?',ARRAY['SC4-2-u4-X19']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C12","difficulty":2,"kind":"mc","stem":"화석 연료를 과도하게 사용하는 모습은 무엇인가요?","options":[{"t":"가까운 거리를 갈 때에도 승용차를 이용한다","correct":true},{"t":"가까운 거리는 걸어서 간다","mis":"SC4-2-u4-X19"},{"t":"낮은 층은 계단으로 올라간다","mis":"SC4-2-u4-X19"},{"t":"나무를 심고 가꾼다","mis":"SC4-2-u4-X19"}],"explanation":["연료를 쓰는 것을 찾아요.","승용차가 연료를 써요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_basic#8','sci',4,2,'u4','L03','g4_2_sci_u4_L03_basic','lesson_basic','SC4-2-u4-C14',2,'ox','auto','사람이 하는 모든 일이 기후 변화를 심각하게 만들어요.',ARRAY['SC4-2-u4-X18']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C14","difficulty":2,"kind":"ox","stem":"사람이 하는 모든 일이 기후 변화를 심각하게 만들어요.","answer":"X","reason_options":[{"t":"숲 파괴, 화석 연료 사용처럼 환경을 생각하지 않는 활동이 기후 변화를 심각하게 만들기 때문에","correct":true},{"t":"사람은 무엇을 하든 기후 변화를 심각하게 만들기 때문에","mis":"SC4-2-u4-X18"}],"mis":"SC4-2-u4-X18","explanation":["붙임딱지 네 장을 떠올려요.","어떤 활동인지 봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_basic#9','sci',4,2,'u4','L03','g4_2_sci_u4_L03_basic','lesson_basic','SC4-2-u4-C15',2,'mc','auto','조사하고 토의할 때 알맞은 행동은 무엇인가요?',ARRAY['SC4-2-u4-X24','SC4-2-u4-X25']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C15","difficulty":2,"kind":"mc","stem":"조사하고 토의할 때 알맞은 행동은 무엇인가요?","options":[{"t":"조사한 정보의 출처를 확인하고 옳은 정보와 거짓 정보를 구분한다","correct":true},{"t":"친구의 개인 정보를 누리망에 올린다","mis":"SC4-2-u4-X24"},{"t":"아무 정보나 확인하지 않고 옮긴다","mis":"SC4-2-u4-X25"},{"t":"친구 말은 듣지 않고 내 의견만 주장한다","mis":"SC4-2-u4-X24"}],"explanation":["조사의 약속을 떠올려요.","출처를 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_basic#10','sci',4,2,'u4','L03','g4_2_sci_u4_L03_basic','lesson_basic','SC4-2-u4-C14',3,'mc','auto','기후 변화를 더욱 심각하게 만드는 활동만 모은 것은 무엇인가요?',ARRAY['SC4-2-u4-X19','SC4-2-u4-X18']::text[],false,'{"seq":10,"concept":"SC4-2-u4-C14","difficulty":3,"kind":"mc","stem":"기후 변화를 더욱 심각하게 만드는 활동만 모은 것은 무엇인가요?","options":[{"t":"숲 파괴, 화석 연료 사용, 많은 쓰레기 버리기","correct":true},{"t":"나무 심기, 계단 이용, 전등 끄기","mis":"SC4-2-u4-X19"},{"t":"숲 파괴, 나무 심기, 계단 이용","mis":"SC4-2-u4-X19"},{"t":"밥 먹기, 잠자기, 책 읽기","mis":"SC4-2-u4-X18"}],"explanation":["붙임딱지를 떠올려요.","환경을 생각하지 않는 활동이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_challenge#1','sci',4,2,'u4','L03','g4_2_sci_u4_L03_challenge','lesson_challenge','SC4-2-u4-C11',2,'blank','auto','「도시나 도로를 만들기 위해 (    )을 파괴하는 것은 기후 변화를 더욱 심각하게 만들어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u4-X20','SC4-2-u4-X19']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C11","difficulty":2,"kind":"blank","stem":"「도시나 도로를 만들기 위해 (    )을 파괴하는 것은 기후 변화를 더욱 심각하게 만들어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"숲","correct":true},{"t":"바다","mis":"SC4-2-u4-X20"},{"t":"하늘","mis":"SC4-2-u4-X20"},{"t":"계단","mis":"SC4-2-u4-X19"}],"explanation":["나무를 베어요.","나무가 많은 곳이에요.","숲이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_challenge#2','sci',4,2,'u4','L03','g4_2_sci_u4_L03_challenge','lesson_challenge','SC4-2-u4-C13',2,'mc','auto','에너지를 많이 사용하는 생활 습관은 무엇인가요?',ARRAY['SC4-2-u4-X19','SC4-2-u4-X23']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C13","difficulty":2,"kind":"mc","stem":"에너지를 많이 사용하는 생활 습관은 무엇인가요?","options":[{"t":"사용하지 않을 때에도 텔레비전과 컴퓨터를 켜 놓는다","correct":true},{"t":"쓰지 않는 텔레비전과 컴퓨터는 꺼 둔다","mis":"SC4-2-u4-X19"},{"t":"낮은 층은 계단으로 올라간다","mis":"SC4-2-u4-X19"},{"t":"창문을 닫고 알맞은 온도로 난방한다","mis":"SC4-2-u4-X23"}],"explanation":["전기를 낭비하는 모습을 찾아요.","켜 둔 채 두어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_challenge#3','sci',4,2,'u4','L03','g4_2_sci_u4_L03_challenge','lesson_challenge','SC4-2-u4-C14',3,'error','auto','인간의 활동에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u4-X18','SC4-2-u4-X20','SC4-2-u4-X21']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C14","difficulty":3,"kind":"error","stem":"인간의 활동에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「밥을 먹고 잠을 자는 것처럼 사람이 하는 모든 일이 기후 변화를 심각하게 만들어.」","correct":true,"mis_target":"SC4-2-u4-X18"},{"t":"친구 가 — 「숲을 파괴하면 기후 변화가 심각해질 수 있어.」","mis":"SC4-2-u4-X20"},{"t":"친구 나 — 「가까운 거리도 승용차를 타면 화석 연료를 많이 쓰는 거야.」","mis":"SC4-2-u4-X21"}],"explanation":["어떤 활동이 문제인지 떠올려요.","환경을 생각하지 않는 활동이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_challenge#4','sci',4,2,'u4','L03','g4_2_sci_u4_L03_challenge','lesson_challenge','SC4-2-u4-C12',3,'mc','auto','「화석 연료를 사용해요」 붙임딱지에 알맞은 그림 속 모습은 무엇인가요?',ARRAY['SC4-2-u4-X19','SC4-2-u4-X22','SC4-2-u4-X21']::text[],false,'{"seq":4,"concept":"SC4-2-u4-C12","difficulty":3,"kind":"mc","stem":"「화석 연료를 사용해요」 붙임딱지에 알맞은 그림 속 모습은 무엇인가요?","options":[{"t":"교통수단을 움직이거나 공장에서 물건을 만든다","correct":true},{"t":"나무를 심어 숲을 가꾼다","mis":"SC4-2-u4-X19"},{"t":"쓰레기를 나누어 버린다","mis":"SC4-2-u4-X22"},{"t":"건물을 짓기 위해 나무를 벤다","mis":"SC4-2-u4-X21"}],"explanation":["연료를 쓰는 모습이에요.","자동차와 공장이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["숲을 파괴하고 건물을 지어요","화석 연료를 사용해요","쓰레기를 많이 버려요","에너지를 많이 사용해요"],"title":"인간의 활동 붙임딱지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_challenge#5','sci',4,2,'u4','L03','g4_2_sci_u4_L03_challenge','lesson_challenge','SC4-2-u4-C10',3,'ox','auto','기후 변화는 자연에 의해서만 일어나요.',ARRAY['SC4-2-u4-X17']::text[],false,'{"seq":5,"concept":"SC4-2-u4-C10","difficulty":3,"kind":"ox","stem":"기후 변화는 자연에 의해서만 일어나요.","answer":"X","reason_options":[{"t":"자연에 의해서도 일어나지만 인간의 활동과도 관련이 있기 때문에","correct":true},{"t":"사람은 기후에 아무 영향을 주지 못하기 때문에","mis":"SC4-2-u4-X17"}],"mis":"SC4-2-u4-X17","explanation":["오늘 공부의 첫 문장을 떠올려요.","인간의 활동과도 관련이 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_challenge#6','sci',4,2,'u4','L03','g4_2_sci_u4_L03_challenge','lesson_challenge','SC4-2-u4-C13',3,'mc','auto','「무분별하게 많은 양의 쓰레기를 버리는 것」과 같은 무리인 활동은 무엇인가요?',ARRAY['SC4-2-u4-X22','SC4-2-u4-X19']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C13","difficulty":3,"kind":"mc","stem":"「무분별하게 많은 양의 쓰레기를 버리는 것」과 같은 무리인 활동은 무엇인가요?","options":[{"t":"일회용품을 많이 사용한다","correct":true},{"t":"일회용품의 사용을 줄인다","mis":"SC4-2-u4-X22"},{"t":"물건을 다시 쓰고 나누어 쓴다","mis":"SC4-2-u4-X19"},{"t":"계단을 이용한다","mis":"SC4-2-u4-X19"}],"explanation":["쓰레기를 늘리는 것을 찾아요.","한 번 쓰고 버려요.","일회용품이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_challenge#7','sci',4,2,'u4','L03','g4_2_sci_u4_L03_challenge','lesson_challenge','SC4-2-u4-C11',3,'mc','auto','숲을 파괴하고 건물을 지을수록 어떻게 될 수 있나요?',ARRAY['SC4-2-u4-X20','SC4-2-u4-X17']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C11","difficulty":3,"kind":"mc","stem":"숲을 파괴하고 건물을 지을수록 어떻게 될 수 있나요?","options":[{"t":"기후 변화가 더 심각해질 수 있다","correct":true},{"t":"기후 변화가 일어나지 않는다","mis":"SC4-2-u4-X20"},{"t":"기후 변화가 줄어든다","mis":"SC4-2-u4-X20"},{"t":"기후 변화와 아무 관련이 없다","mis":"SC4-2-u4-X17"}],"explanation":["붙임딱지 첫째 장을 떠올려요.","숲이 사라져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_challenge#8','sci',4,2,'u4','L03','g4_2_sci_u4_L03_challenge','lesson_challenge','SC4-2-u4-C15',4,'mc','auto','친구가 「내 생각이 맞으니까 친구들 말은 안 들어도 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X24','SC4-2-u4-X25']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C15","difficulty":4,"kind":"mc","stem":"친구가 「내 생각이 맞으니까 친구들 말은 안 들어도 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「토의할 때에는 다른 사람의 의견을 주의 깊게 들어야 더 좋은 생각을 모을 수 있어.」","correct":true},{"t":"「맞아, 내 의견만 계속 말하자.」","mis":"SC4-2-u4-X24"},{"t":"「친구 이름과 주소를 누리망에 올려서 물어보자.」","mis":"SC4-2-u4-X24"},{"t":"「출처는 확인하지 말고 빨리 옮기자.」","mis":"SC4-2-u4-X25"}],"explanation":["토의의 약속을 떠올려요.","듣는 것이 중요해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_challenge#9','sci',4,2,'u4','L03','g4_2_sci_u4_L03_challenge','lesson_challenge','SC4-2-u4-C14',4,'mc','auto','친구가 「인간의 활동은 모두 나쁘니까 아무것도 하지 말아야 해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X18','SC4-2-u4-X17','SC4-2-u4-X19']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C14","difficulty":4,"kind":"mc","stem":"친구가 「인간의 활동은 모두 나쁘니까 아무것도 하지 말아야 해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「모든 일이 아니라 숲 파괴, 화석 연료 사용, 많은 쓰레기처럼 환경을 생각하지 않는 활동이 기후 변화를 심각하게 만드는 거야.」","correct":true},{"t":"「맞아, 사람이 하는 모든 일이 문제야.」","mis":"SC4-2-u4-X18"},{"t":"「인간의 활동은 기후 변화와 상관없어.」","mis":"SC4-2-u4-X17"},{"t":"「나무를 심는 것도 기후 변화를 심각하게 만들어.」","mis":"SC4-2-u4-X19"}],"explanation":["어떤 활동이 문제인지 떠올려요.","환경을 생각하지 않는 활동이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L03_challenge#10','sci',4,2,'u4','L03','g4_2_sci_u4_L03_challenge','lesson_challenge','SC4-2-u4-C10',4,'essay','teacher','기후 변화를 더욱 심각하게 만드는 인간의 활동을 두 가지 쓰고, 각각 우리 생활에서 볼 수 있는 모습을 한 가지씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u4-C10","difficulty":4,"kind":"essay","stem":"기후 변화를 더욱 심각하게 만드는 인간의 활동을 두 가지 쓰고, 각각 우리 생활에서 볼 수 있는 모습을 한 가지씩 쓰세요.","answer_guide":{"answer":"예: 화석 연료를 사용하는 것 — 가까운 거리를 갈 때에도 승용차를 이용한다. 쓰레기를 많이 버리는 것 — 일회용품을 많이 사용한다.","scoring_points":["인간의 활동 하나와 생활 속 모습을 썼는가","인간의 활동 또 하나와 생활 속 모습을 썼는가","환경을 생각하지 않는 활동을 골랐는가"]},"explanation":["붙임딱지를 떠올려요.","두 가지를 골라요.","생활 모습을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_basic#1','sci',4,2,'u4','L04','g4_2_sci_u4_L04_basic','lesson_basic','SC4-2-u4-C16',1,'mc','auto','기후 변화로 빙하가 녹으면 무엇이 상승하나요?',ARRAY['SC4-2-u4-X26']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C16","difficulty":1,"kind":"mc","stem":"기후 변화로 빙하가 녹으면 무엇이 상승하나요?","options":[{"t":"해수면","correct":true},{"t":"강수량","mis":"SC4-2-u4-X26"},{"t":"한파","mis":"SC4-2-u4-X26"},{"t":"산의 높이","mis":"SC4-2-u4-X26"}],"explanation":["빙하가 녹으면 물이 돼요.","바닷물이 늘어요.","해수면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_basic#2','sci',4,2,'u4','L04','g4_2_sci_u4_L04_basic','lesson_basic','SC4-2-u4-C16',1,'mc','auto','해수면 상승은 어떤 현상인가요?',ARRAY['SC4-2-u4-X27']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C16","difficulty":1,"kind":"mc","stem":"해수면 상승은 어떤 현상인가요?","options":[{"t":"바닷물의 높이가 높아지는 현상","correct":true},{"t":"산에 눈이 많이 쌓이는 현상","mis":"SC4-2-u4-X27"},{"t":"비가 갑자기 많이 내리는 현상","mis":"SC4-2-u4-X27"},{"t":"땅이 메말라 사막이 되는 현상","mis":"SC4-2-u4-X27"}],"explanation":["해수면은 바닷물의 면이에요.","높아져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_basic#3','sci',4,2,'u4','L04','g4_2_sci_u4_L04_basic','lesson_basic','SC4-2-u4-C17',1,'ox','auto','이쑤시개를 사용하기 전에 면장갑을 껴요.',ARRAY['SC4-2-u4-X28']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C17","difficulty":1,"kind":"ox","stem":"이쑤시개를 사용하기 전에 면장갑을 껴요.","answer":"O","reason_options":[{"t":"뾰족한 이쑤시개에 손이 찔리지 않도록 보호하기 위해서","correct":true},{"t":"장갑을 끼면 물이 더 빨리 차오르기 때문에","mis":"SC4-2-u4-X28"}],"mis":"SC4-2-u4-X28","explanation":["이쑤시개를 떠올려요.","뾰족해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_basic#4','sci',4,2,'u4','L04','g4_2_sci_u4_L04_basic','lesson_basic','SC4-2-u4-C20',1,'sa','auto','빙하에서 떨어져 나와 물에 떠 있는 얼음덩어리를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u4-C20","difficulty":1,"kind":"sa","stem":"빙하에서 떨어져 나와 물에 떠 있는 얼음덩어리를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["빙산"],"explanation":["물에 떠 있어요.","「빙」으로 시작해요.","빙산이에요."],"mis":"SC4-2-u4-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_basic#5','sci',4,2,'u4','L04','g4_2_sci_u4_L04_basic','lesson_basic','SC4-2-u4-C18',2,'match','auto','모형실험의 모습과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-2-u4-C18","difficulty":2,"kind":"match","stem":"모형실험의 모습과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"색깔 점토","r":"육지와 섬"},{"l":"깃발","r":"주택가, 농경지 같은 곳"},{"l":"모형에 물을 붓는 것","r":"해수면의 높이가 상승하는 것"},{"l":"깃발 꽂은 곳이 잠기는 것","r":"우리가 살 수 있는 땅이 줄어드는 것"}],"mis":"SC4-2-u4-X30","explanation":["모형은 바닷가 마을이에요.","물은 바닷물이에요.","하나씩 이어요."],"asset":{"type":"passage","lines":["① 바닷가 마을에 무엇이 있는지 생각해요.","② 붙임딱지에 쓴 다음 이쑤시개에 붙여 깃발을 만들어요.","③ 통 바닥에 색깔 점토를 붙이고 깃발을 꽂아 마을을 만들어요.","④ 천천히 물을 부으며 물에 잠기는 부분을 관찰해요.","⑤ 깃발을 꽂은 곳이 잠기면 어떤 피해가 있을지 이야기해요."],"title":"해수면 상승 모형실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_basic#6','sci',4,2,'u4','L04','g4_2_sci_u4_L04_basic','lesson_basic','SC4-2-u4-C18',2,'mc','auto','해수면이 상승하면 어떤 피해가 생길까요?',ARRAY['SC4-2-u4-X29','SC4-2-u4-X34']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C18","difficulty":2,"kind":"mc","stem":"해수면이 상승하면 어떤 피해가 생길까요?","options":[{"t":"해안 도시와 고도가 낮은 많은 땅이 바닷물에 잠길 수 있다","correct":true},{"t":"바닷가 마을의 땅이 더 넓어진다","mis":"SC4-2-u4-X29"},{"t":"높은 산꼭대기만 바닷물에 잠긴다","mis":"SC4-2-u4-X29"},{"t":"우리가 사는 곳에는 아무 일도 생기지 않는다","mis":"SC4-2-u4-X34"}],"explanation":["모형실험을 떠올려요.","낮은 곳부터 잠겨요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_basic#7','sci',4,2,'u4','L04','g4_2_sci_u4_L04_basic','lesson_basic','SC4-2-u4-C19',2,'mc','auto','기후 변화로 바닷물의 온도가 높아지면 산호초는 어떻게 될까요?',ARRAY['SC4-2-u4-X33','SC4-2-u4-X34']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C19","difficulty":2,"kind":"mc","stem":"기후 변화로 바닷물의 온도가 높아지면 산호초는 어떻게 될까요?","options":[{"t":"하얗게 변한다","correct":true},{"t":"더 알록달록해진다","mis":"SC4-2-u4-X33"},{"t":"크기가 두 배로 커진다","mis":"SC4-2-u4-X33"},{"t":"아무 변화도 없다","mis":"SC4-2-u4-X34"}],"explanation":["세계 곳곳의 피해를 떠올려요.","색이 빠져요.","하얗게 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_basic#8','sci',4,2,'u4','L04','g4_2_sci_u4_L04_basic','lesson_basic','SC4-2-u4-C20',2,'ox','auto','물에 떠 있는 빙산이 녹으면 해수면이 올라가요.',ARRAY['SC4-2-u4-X32']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C20","difficulty":2,"kind":"ox","stem":"물에 떠 있는 빙산이 녹으면 해수면이 올라가요.","answer":"X","reason_options":[{"t":"컵 속 얼음이 녹아도 물의 높이가 변하지 않는 것처럼 떠 있는 얼음이 녹아도 물의 높이는 그대로이기 때문에","correct":true},{"t":"빙산과 빙하는 같은 것이기 때문에","mis":"SC4-2-u4-X32"}],"mis":"SC4-2-u4-X32","explanation":["컵 속 얼음을 떠올려요.","물의 높이를 견줘요.","그래서 X예요."],"asset":{"type":"passage","lines":["빙하 — 육지에 오랫동안 쌓인 눈이 얼음덩어리로 변해 육지를 덮고 있는 것","빙산 — 빙하에서 떨어져 나와 물에 떠 있는 얼음덩어리","물이 담긴 컵에 얼음을 넣고, 녹기 전과 후의 물의 높이를 비교해요."],"title":"빙하와 빙산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_basic#9','sci',4,2,'u4','L04','g4_2_sci_u4_L04_basic','lesson_basic','SC4-2-u4-C17',2,'mc','auto','모형실험에서 물을 부을 때 알맞은 방법은 무엇인가요?',ARRAY['SC4-2-u4-X28']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C17","difficulty":2,"kind":"mc","stem":"모형실험에서 물을 부을 때 알맞은 방법은 무엇인가요?","options":[{"t":"물을 흘리지 않도록 천천히 붓는다","correct":true},{"t":"물통의 물을 한꺼번에 쏟는다","mis":"SC4-2-u4-X28"},{"t":"이쑤시개로 친구와 장난친다","mis":"SC4-2-u4-X28"},{"t":"물을 바닥에 일부러 흘린다","mis":"SC4-2-u4-X28"}],"explanation":["④를 읽어요.","천천히 부어요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 바닷가 마을에 무엇이 있는지 생각해요.","② 붙임딱지에 쓴 다음 이쑤시개에 붙여 깃발을 만들어요.","③ 통 바닥에 색깔 점토를 붙이고 깃발을 꽂아 마을을 만들어요.","④ 천천히 물을 부으며 물에 잠기는 부분을 관찰해요.","⑤ 깃발을 꽂은 곳이 잠기면 어떤 피해가 있을지 이야기해요."],"title":"해수면 상승 모형실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_basic#10','sci',4,2,'u4','L04','g4_2_sci_u4_L04_basic','lesson_basic','SC4-2-u4-C19',3,'mc','auto','기후 변화로 세계 곳곳에서 일어나는 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u4-X33','SC4-2-u4-X29']::text[],false,'{"seq":10,"concept":"SC4-2-u4-C19","difficulty":3,"kind":"mc","stem":"기후 변화로 세계 곳곳에서 일어나는 일로 알맞은 것은 무엇인가요?","options":[{"t":"내리는 비의 양이 적어져 사막이 늘어난다","correct":true},{"t":"사막이 점점 줄어들고 숲이 늘어난다","mis":"SC4-2-u4-X33"},{"t":"남태평양의 섬들이 점점 넓어진다","mis":"SC4-2-u4-X29"},{"t":"바닷물의 온도가 낮아져 산호초가 알록달록해진다","mis":"SC4-2-u4-X33"}],"explanation":["세계 곳곳의 피해를 떠올려요.","비가 적게 와요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_challenge#1','sci',4,2,'u4','L04','g4_2_sci_u4_L04_challenge','lesson_challenge','SC4-2-u4-C20',2,'blank','auto','「(    )는 육지에 오랫동안 쌓인 눈이 얼음덩어리로 변해 육지를 덮고 있는 것이에요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u4-X32','SC4-2-u4-X27','SC4-2-u4-X33']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C20","difficulty":2,"kind":"blank","stem":"「(    )는 육지에 오랫동안 쌓인 눈이 얼음덩어리로 변해 육지를 덮고 있는 것이에요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"빙하","correct":true},{"t":"빙산","mis":"SC4-2-u4-X32"},{"t":"해수면","mis":"SC4-2-u4-X27"},{"t":"사막","mis":"SC4-2-u4-X33"}],"explanation":["육지를 덮고 있어요.","물에 떠 있지 않아요.","빙하예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_challenge#2','sci',4,2,'u4','L04','g4_2_sci_u4_L04_challenge','lesson_challenge','SC4-2-u4-C21',2,'mc','auto','모형실험을 하고 가져야 할 마음으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u4-X08','SC4-2-u4-X34','SC4-2-u4-X31']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C21","difficulty":2,"kind":"mc","stem":"모형실험을 하고 가져야 할 마음으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"기후 변화의 심각성에 관심을 가지고 탐구한다","correct":true},{"t":"무섭기만 하고 할 수 있는 일이 없다고 여긴다","mis":"SC4-2-u4-X08"},{"t":"먼 나라의 일이라 상관없다고 여긴다","mis":"SC4-2-u4-X34"},{"t":"물을 붓는 재미로만 실험한다","mis":"SC4-2-u4-X31"}],"explanation":["실험한 까닭을 떠올려요.","피해를 예측했어요.","관심을 가져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_challenge#3','sci',4,2,'u4','L04','g4_2_sci_u4_L04_challenge','lesson_challenge','SC4-2-u4-C18',3,'error','auto','모형실험을 하고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u4-X29','SC4-2-u4-X30','SC4-2-u4-X31']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C18","difficulty":3,"kind":"error","stem":"모형실험을 하고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「물을 부을수록 육지가 넓어졌어.」","correct":true,"mis_target":"SC4-2-u4-X29"},{"t":"친구 나 — 「물을 붓는 건 해수면이 높아지는 걸 뜻해.」","mis":"SC4-2-u4-X30"},{"t":"친구 다 — 「깃발을 꽂은 곳이 물에 잠겼어.」","mis":"SC4-2-u4-X31"}],"explanation":["물을 부으면 어떻게 되었나요?","땅이 잠겼어요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 바닷가 마을에 무엇이 있는지 생각해요.","② 붙임딱지에 쓴 다음 이쑤시개에 붙여 깃발을 만들어요.","③ 통 바닥에 색깔 점토를 붙이고 깃발을 꽂아 마을을 만들어요.","④ 천천히 물을 부으며 물에 잠기는 부분을 관찰해요.","⑤ 깃발을 꽂은 곳이 잠기면 어떤 피해가 있을지 이야기해요."],"title":"해수면 상승 모형실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_challenge#4','sci',4,2,'u4','L04','g4_2_sci_u4_L04_challenge','lesson_challenge','SC4-2-u4-C18',3,'mc','auto','모형실험에서 실험 전에 「예상한 것」은 무엇인가요?',ARRAY['SC4-2-u4-X31','SC4-2-u4-X29']::text[],false,'{"seq":4,"concept":"SC4-2-u4-C18","difficulty":3,"kind":"mc","stem":"모형실험에서 실험 전에 「예상한 것」은 무엇인가요?","options":[{"t":"물을 부으면 주택가와 농경지가 물에 잠길 것이다","correct":true},{"t":"물을 부었더니 주택가와 농경지 깃발을 꽂은 부분이 잠겼다","mis":"SC4-2-u4-X31"},{"t":"물을 부었더니 섬 깃발을 꽂은 부분도 잠겼다","mis":"SC4-2-u4-X31"},{"t":"물을 부으면 육지가 더 넓어질 것이다","mis":"SC4-2-u4-X29"}],"explanation":["예상은 실험 전이에요.","「~할 것이다」를 찾아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_challenge#5','sci',4,2,'u4','L04','g4_2_sci_u4_L04_challenge','lesson_challenge','SC4-2-u4-C16',3,'ox','auto','극지방의 빙하가 녹아내리면 극지방 동물들이 살 곳이 사라지고 물에 잠기는 곳이 생길 수 있어요.',ARRAY['SC4-2-u4-X26']::text[],false,'{"seq":5,"concept":"SC4-2-u4-C16","difficulty":3,"kind":"ox","stem":"극지방의 빙하가 녹아내리면 극지방 동물들이 살 곳이 사라지고 물에 잠기는 곳이 생길 수 있어요.","answer":"O","reason_options":[{"t":"빙하가 녹으면 해수면이 상승하기 때문에","correct":true},{"t":"빙하가 녹으면 해수면이 낮아지기 때문에","mis":"SC4-2-u4-X26"}],"mis":"SC4-2-u4-X26","explanation":["빙하가 녹으면 바닷물이 늘어요.","해수면이 올라가요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_challenge#6','sci',4,2,'u4','L04','g4_2_sci_u4_L04_challenge','lesson_challenge','SC4-2-u4-C20',3,'mc','auto','물이 담긴 컵에 얼음을 넣고 녹기 전과 후의 물의 높이를 비교하면 어떻게 되나요?',ARRAY['SC4-2-u4-X32']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C20","difficulty":3,"kind":"mc","stem":"물이 담긴 컵에 얼음을 넣고 녹기 전과 후의 물의 높이를 비교하면 어떻게 되나요?","options":[{"t":"얼음이 녹아도 물의 높이가 변하지 않는다","correct":true},{"t":"얼음이 녹으면 물의 높이가 크게 올라간다","mis":"SC4-2-u4-X32"},{"t":"얼음이 녹으면 물이 모두 사라진다","mis":"SC4-2-u4-X32"},{"t":"얼음이 녹으면 컵이 커진다","mis":"SC4-2-u4-X32"}],"explanation":["컵 속 얼음은 떠 있어요.","빙산과 같아요.","높이가 그대로예요."],"asset":{"type":"passage","lines":["빙하 — 육지에 오랫동안 쌓인 눈이 얼음덩어리로 변해 육지를 덮고 있는 것","빙산 — 빙하에서 떨어져 나와 물에 떠 있는 얼음덩어리","물이 담긴 컵에 얼음을 넣고, 녹기 전과 후의 물의 높이를 비교해요."],"title":"빙하와 빙산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_challenge#7','sci',4,2,'u4','L04','g4_2_sci_u4_L04_challenge','lesson_challenge','SC4-2-u4-C19',3,'mc','auto','「세계 곳곳에서 사막화, 생태계 파괴 등이 더 많이 진행되고 있어요.」 그 까닭은 무엇인가요?',ARRAY['SC4-2-u4-X33','SC4-2-u4-X26','SC4-2-u4-X34']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C19","difficulty":3,"kind":"mc","stem":"「세계 곳곳에서 사막화, 생태계 파괴 등이 더 많이 진행되고 있어요.」 그 까닭은 무엇인가요?","options":[{"t":"기후 변화가 심해지고 있기 때문에","correct":true},{"t":"기후 변화가 사라지고 있기 때문에","mis":"SC4-2-u4-X33"},{"t":"바닷물의 높이가 낮아지고 있기 때문에","mis":"SC4-2-u4-X26"},{"t":"우리와 상관없는 먼 미래의 일이기 때문에","mis":"SC4-2-u4-X34"}],"explanation":["세계 곳곳의 피해를 떠올려요.","기후 변화가 심해져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_challenge#8','sci',4,2,'u4','L04','g4_2_sci_u4_L04_challenge','lesson_challenge','SC4-2-u4-C20',4,'mc','auto','친구가 「빙산이든 빙하든 녹으면 해수면이 똑같이 올라가.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X32','SC4-2-u4-X26']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C20","difficulty":4,"kind":"mc","stem":"친구가 「빙산이든 빙하든 녹으면 해수면이 똑같이 올라가.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「빙하는 육지를 덮고 있는 얼음덩어리이고, 빙산은 물에 떠 있어서 녹아도 컵 속 얼음처럼 물의 높이가 변하지 않아.」","correct":true},{"t":"「맞아, 둘은 같은 거야.」","mis":"SC4-2-u4-X32"},{"t":"「빙하가 녹으면 해수면이 낮아져.」","mis":"SC4-2-u4-X26"},{"t":"「얼음은 녹아도 물이 되지 않아.」","mis":"SC4-2-u4-X32"}],"explanation":["빙하와 빙산의 뜻을 떠올려요.","컵 속 얼음을 떠올려요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["빙하 — 육지에 오랫동안 쌓인 눈이 얼음덩어리로 변해 육지를 덮고 있는 것","빙산 — 빙하에서 떨어져 나와 물에 떠 있는 얼음덩어리","물이 담긴 컵에 얼음을 넣고, 녹기 전과 후의 물의 높이를 비교해요."],"title":"빙하와 빙산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_challenge#9','sci',4,2,'u4','L04','g4_2_sci_u4_L04_challenge','lesson_challenge','SC4-2-u4-C18',4,'mc','auto','친구가 「바닷물이 조금 높아지는 건 우리가 사는 곳과 상관없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X34','SC4-2-u4-X29']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C18","difficulty":4,"kind":"mc","stem":"친구가 「바닷물이 조금 높아지는 건 우리가 사는 곳과 상관없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「해수면이 높아지면 해안 도시와 낮은 땅이 잠겨서 우리가 살 수 있는 땅이 줄어들어.」","correct":true},{"t":"「맞아, 아무 일도 생기지 않아.」","mis":"SC4-2-u4-X34"},{"t":"「땅이 더 넓어질 거야.」","mis":"SC4-2-u4-X29"},{"t":"「높은 산만 잠겨.」","mis":"SC4-2-u4-X29"}],"explanation":["모형실험을 떠올려요.","깃발이 잠겼어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L04_challenge#10','sci',4,2,'u4','L04','g4_2_sci_u4_L04_challenge','lesson_challenge','SC4-2-u4-C18',4,'essay','teacher','해수면 상승 모형실험의 결과를 쓰고, 이것으로 알 수 있는 기후 변화의 피해를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u4-C18","difficulty":4,"kind":"essay","stem":"해수면 상승 모형실험의 결과를 쓰고, 이것으로 알 수 있는 기후 변화의 피해를 쓰세요.","answer_guide":{"answer":"예: 모형에 물을 붓자 주택가와 농경지 깃발을 꽂아 둔 부분이 물에 잠겼다. 기후 변화로 빙하가 녹아 해수면이 상승하면 해안 도시와 고도가 낮은 땅이 바닷물에 잠겨 우리가 살 수 있는 땅이 줄어든다.","scoring_points":["실험 결과를 썼는가","해수면 상승과 이었는가","살 수 있는 땅이 줄어든다는 피해를 썼는가"]},"explanation":["실험을 떠올려요.","결과를 써요.","피해를 이어요."],"asset":{"type":"passage","lines":["① 바닷가 마을에 무엇이 있는지 생각해요.","② 붙임딱지에 쓴 다음 이쑤시개에 붙여 깃발을 만들어요.","③ 통 바닥에 색깔 점토를 붙이고 깃발을 꽂아 마을을 만들어요.","④ 천천히 물을 부으며 물에 잠기는 부분을 관찰해요.","⑤ 깃발을 꽂은 곳이 잠기면 어떤 피해가 있을지 이야기해요."],"title":"해수면 상승 모형실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_basic#1','sci',4,2,'u4','L05','g4_2_sci_u4_L05_basic','lesson_basic','SC4-2-u4-C22',1,'mc','auto','기후 변화와 우리 생활에 대해 알맞게 말한 것은 무엇인가요?',ARRAY['SC4-2-u4-X34']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C22","difficulty":1,"kind":"mc","stem":"기후 변화와 우리 생활에 대해 알맞게 말한 것은 무엇인가요?","options":[{"t":"기후 변화는 이미 우리 생활과 환경에 영향을 준다","correct":true},{"t":"기후 변화는 먼 미래에만 일어나는 일이다","mis":"SC4-2-u4-X34"},{"t":"기후 변화는 우리 생활과 아무 관계가 없다","mis":"SC4-2-u4-X34"},{"t":"기후 변화는 우리 환경을 바꾸지 않는다","mis":"SC4-2-u4-X34"}],"explanation":["불편했던 경험을 떠올려요.","벌써 일어나고 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_basic#2','sci',4,2,'u4','L05','g4_2_sci_u4_L05_basic','lesson_basic','SC4-2-u4-C24',1,'mc','auto','온열 질환은 무엇인가요?',ARRAY['SC4-2-u4-X37']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C24","difficulty":1,"kind":"mc","stem":"온열 질환은 무엇인가요?","options":[{"t":"폭염으로 몸의 체온이 급격히 올라가면서 발생하는 질환","correct":true},{"t":"한파로 손발이 차가워지는 질환","mis":"SC4-2-u4-X37"},{"t":"비를 많이 맞아서 생기는 질환","mis":"SC4-2-u4-X37"},{"t":"음식을 너무 많이 먹어서 생기는 질환","mis":"SC4-2-u4-X37"}],"explanation":["「온열」은 따뜻함이에요.","폭염과 관계있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_basic#3','sci',4,2,'u4','L05','g4_2_sci_u4_L05_basic','lesson_basic','SC4-2-u4-C26',1,'ox','auto','삼각책을 만들 때에는 모서리에 손이 스치지 않도록 조심해요.',ARRAY['SC4-2-u4-X40']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C26","difficulty":1,"kind":"ox","stem":"삼각책을 만들 때에는 모서리에 손이 스치지 않도록 조심해요.","answer":"O","reason_options":[{"t":"종이 모서리에 손이 베일 수 있기 때문에","correct":true},{"t":"삼각책은 모서리를 세게 문질러야 잘 완성되기 때문에","mis":"SC4-2-u4-X40"}],"mis":"SC4-2-u4-X40","explanation":["종이 모서리를 떠올려요.","손이 베일 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_basic#4','sci',4,2,'u4','L05','g4_2_sci_u4_L05_basic','lesson_basic','SC4-2-u4-C24',1,'sa','auto','폭염으로 몸의 체온이 급격히 올라가면서 발생하는 질환을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u4-C24","difficulty":1,"kind":"sa","stem":"폭염으로 몸의 체온이 급격히 올라가면서 발생하는 질환을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["온열 질환","온열질환"],"explanation":["「온열」로 시작해요.","질환이에요.","온열 질환이에요."],"mis":"SC4-2-u4-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_basic#5','sci',4,2,'u4','L05','g4_2_sci_u4_L05_basic','lesson_basic','SC4-2-u4-C23',2,'match','auto','그림 이름과 알맞은 설명을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-2-u4-C23","difficulty":2,"kind":"match","stem":"그림 이름과 알맞은 설명을 이으세요.","pairs":[{"l":"파괴되는 생태계","r":"동물과 식물들이 살 곳을 잃고 사라져요"},{"l":"심각해지는 자연재해","r":"폭염, 홍수, 태풍, 산불 등이 자주 일어나요"},{"l":"부족해지는 물","r":"비가 적게 와서 마실 물이 부족해져요"},{"l":"위협받는 건강","r":"온열 질환과 감염병으로 고통받는 사람이 늘어나요"}],"mis":"SC4-2-u4-X38","explanation":["그림 이름을 읽어요.","낱말이 힌트예요.","하나씩 이어요."],"asset":{"type":"passage","lines":["파괴되는 생태계","심각해지는 자연재해","부족해지는 물","위협받는 건강"],"title":"기후 변화가 미치는 영향 그림 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_basic#6','sci',4,2,'u4','L05','g4_2_sci_u4_L05_basic','lesson_basic','SC4-2-u4-C24',2,'mc','auto','모기나 진드기 같은 해충이 많아지면 어떤 일이 생길 수 있나요?',ARRAY['SC4-2-u4-X37','SC4-2-u4-X35']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C24","difficulty":2,"kind":"mc","stem":"모기나 진드기 같은 해충이 많아지면 어떤 일이 생길 수 있나요?","options":[{"t":"감염병이 증가할 수 있다","correct":true},{"t":"감염병이 모두 사라진다","mis":"SC4-2-u4-X37"},{"t":"마실 물이 풍부해진다","mis":"SC4-2-u4-X35"},{"t":"생태계가 더 건강해진다","mis":"SC4-2-u4-X35"}],"explanation":["해충은 병을 옮겨요.","건강을 위협해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_basic#7','sci',4,2,'u4','L05','g4_2_sci_u4_L05_basic','lesson_basic','SC4-2-u4-C22',2,'mc','auto','「폭염으로 기온이 너무 높아서 야외 활동을 할 수 없었어요.」는 어떤 모습인가요?',ARRAY['SC4-2-u4-X36','SC4-2-u4-X35','SC4-2-u4-X34']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C22","difficulty":2,"kind":"mc","stem":"「폭염으로 기온이 너무 높아서 야외 활동을 할 수 없었어요.」는 어떤 모습인가요?","options":[{"t":"기후 변화로 우리 생활이 불편해진 모습","correct":true},{"t":"기후 변화로 생태계가 파괴된 모습","mis":"SC4-2-u4-X36"},{"t":"기후 변화로 물과 식량이 풍부해진 모습","mis":"SC4-2-u4-X35"},{"t":"기후 변화와 관계없는 모습","mis":"SC4-2-u4-X34"}],"explanation":["누가 불편했나요?","우리가 밖에 못 나갔어요.","생활이 불편해졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_basic#8','sci',4,2,'u4','L05','g4_2_sci_u4_L05_basic','lesson_basic','SC4-2-u4-C22',2,'ox','auto','기후 변화 덕분에 자연재해가 줄어드는 좋은 점이 있어요.',ARRAY['SC4-2-u4-X35']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C22","difficulty":2,"kind":"ox","stem":"기후 변화 덕분에 자연재해가 줄어드는 좋은 점이 있어요.","answer":"X","reason_options":[{"t":"기후 변화로 폭염, 홍수, 태풍, 산불 같은 자연재해가 더욱 자주 일어나기 때문에","correct":true},{"t":"기온이 높아지면 자연재해가 모두 사라지기 때문에","mis":"SC4-2-u4-X35"}],"mis":"SC4-2-u4-X35","explanation":["그림 넷을 떠올려요.","자연재해가 심각해져요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_basic#9','sci',4,2,'u4','L05','g4_2_sci_u4_L05_basic','lesson_basic','SC4-2-u4-C26',2,'mc','auto','기후 변화의 영향을 조사할 때 알맞은 방법은 무엇인가요?',ARRAY['SC4-2-u4-X25','SC4-2-u4-X40']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C26","difficulty":2,"kind":"mc","stem":"기후 변화의 영향을 조사할 때 알맞은 방법은 무엇인가요?","options":[{"t":"신뢰할 수 있는 공공 사이트에서 조사하고 출처를 확인한다","correct":true},{"t":"아무 누리집의 정보나 확인하지 않고 옮겨 쓴다","mis":"SC4-2-u4-X25"},{"t":"전달하면 안 되는 내용도 그대로 알린다","mis":"SC4-2-u4-X25"},{"t":"조사보다 삼각책을 예쁘게 꾸미는 데 시간을 쓴다","mis":"SC4-2-u4-X40"}],"explanation":["조사의 약속을 떠올려요.","믿을 수 있는 곳이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_basic#10','sci',4,2,'u4','L05','g4_2_sci_u4_L05_basic','lesson_basic','SC4-2-u4-C25',3,'mc','auto','동해안에 오징어가 해마다 줄어드는 까닭은 무엇일까요?',ARRAY['SC4-2-u4-X39']::text[],false,'{"seq":10,"concept":"SC4-2-u4-C25","difficulty":3,"kind":"mc","stem":"동해안에 오징어가 해마다 줄어드는 까닭은 무엇일까요?","options":[{"t":"기후 변화로 동해안의 수온이 상승해서 오징어가 다른 곳으로 이동하기 때문에","correct":true},{"t":"동해안의 바닷물이 해마다 차가워지기 때문에","mis":"SC4-2-u4-X39"},{"t":"동해안에 비가 많이 내리기 때문에","mis":"SC4-2-u4-X39"},{"t":"오징어가 동해안에서만 새로 생겨나기 때문에","mis":"SC4-2-u4-X39"}],"explanation":["바닷물의 온도를 떠올려요.","따뜻해졌어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_challenge#1','sci',4,2,'u4','L05','g4_2_sci_u4_L05_challenge','lesson_challenge','SC4-2-u4-C24',2,'blank','auto','「비가 내리는 양이 줄어들어 마실 수 있는 (    )이 부족한 지역들이 늘어나고 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u4-X38']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C24","difficulty":2,"kind":"blank","stem":"「비가 내리는 양이 줄어들어 마실 수 있는 (    )이 부족한 지역들이 늘어나고 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"물","correct":true},{"t":"눈","mis":"SC4-2-u4-X38"},{"t":"모래","mis":"SC4-2-u4-X38"},{"t":"바람","mis":"SC4-2-u4-X38"}],"explanation":["비가 적게 와요.","마시는 것이에요.","물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_challenge#2','sci',4,2,'u4','L05','g4_2_sci_u4_L05_challenge','lesson_challenge','SC4-2-u4-C23',2,'mc','auto','「자연재해가 자주 발생하여 집이나 농작물에 피해를 입을 수 있어요.」는 어떤 영향인가요?',ARRAY['SC4-2-u4-X38','SC4-2-u4-X35']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C23","difficulty":2,"kind":"mc","stem":"「자연재해가 자주 발생하여 집이나 농작물에 피해를 입을 수 있어요.」는 어떤 영향인가요?","options":[{"t":"심각해지는 자연재해","correct":true},{"t":"부족해지는 물","mis":"SC4-2-u4-X38"},{"t":"위협받는 건강","mis":"SC4-2-u4-X38"},{"t":"자연재해가 줄어드는 좋은 점","mis":"SC4-2-u4-X35"}],"explanation":["무엇이 자주 발생했나요?","자연재해예요.","첫 번째예요."],"asset":{"type":"passage","lines":["파괴되는 생태계","심각해지는 자연재해","부족해지는 물","위협받는 건강"],"title":"기후 변화가 미치는 영향 그림 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_challenge#3','sci',4,2,'u4','L05','g4_2_sci_u4_L05_challenge','lesson_challenge','SC4-2-u4-C22',3,'error','auto','조사한 내용을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u4-X35','SC4-2-u4-X37','SC4-2-u4-X38']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C22","difficulty":3,"kind":"error","stem":"조사한 내용을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「기후 변화로 비가 적당히 내려서 물과 식량이 풍부해지고 있어.」","correct":true,"mis_target":"SC4-2-u4-X35"},{"t":"친구 가 — 「여름이 더 뜨거워지면서 열사병 환자가 늘어나.」","mis":"SC4-2-u4-X37"},{"t":"친구 나 — 「홍수나 가뭄으로 물과 식량이 부족해질 수 있어.」","mis":"SC4-2-u4-X38"}],"explanation":["기후 변화의 영향을 떠올려요.","부족해져요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_challenge#4','sci',4,2,'u4','L05','g4_2_sci_u4_L05_challenge','lesson_challenge','SC4-2-u4-C22',3,'mc','auto','「생태계가 파괴되어 동물과 식물들이 사라져요.」를 두 칸으로 나눈다면 어느 쪽인가요?',ARRAY['SC4-2-u4-X36','SC4-2-u4-X34','SC4-2-u4-X35']::text[],false,'{"seq":4,"concept":"SC4-2-u4-C22","difficulty":3,"kind":"mc","stem":"「생태계가 파괴되어 동물과 식물들이 사라져요.」를 두 칸으로 나눈다면 어느 쪽인가요?","options":[{"t":"환경이 달라진 모습","correct":true},{"t":"우리 생활이 불편해진 모습","mis":"SC4-2-u4-X36"},{"t":"기후 변화와 관계없는 모습","mis":"SC4-2-u4-X34"},{"t":"기후 변화로 좋아진 모습","mis":"SC4-2-u4-X35"}],"explanation":["누구에게 일어난 일인가요?","동물과 식물이에요.","환경이 달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_challenge#5','sci',4,2,'u4','L05','g4_2_sci_u4_L05_challenge','lesson_challenge','SC4-2-u4-C26',3,'ox','auto','삼각책은 가장 예쁘게 꾸미는 것이 제일 중요해요.',ARRAY['SC4-2-u4-X40']::text[],false,'{"seq":5,"concept":"SC4-2-u4-C26","difficulty":3,"kind":"ox","stem":"삼각책은 가장 예쁘게 꾸미는 것이 제일 중요해요.","answer":"X","reason_options":[{"t":"조사한 영향을 삼각책으로 친구들에게 설명하는 것이 중요하기 때문에","correct":true},{"t":"예쁜 삼각책이 가장 잘 설명한 삼각책이기 때문에","mis":"SC4-2-u4-X40"}],"mis":"SC4-2-u4-X40","explanation":["삼각책을 만든 까닭을 떠올려요.","설명하려고 만들었어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_challenge#6','sci',4,2,'u4','L05','g4_2_sci_u4_L05_challenge','lesson_challenge','SC4-2-u4-C24',3,'mc','auto','「위협받는 건강」 그림에 알맞은 이야기는 무엇인가요?',ARRAY['SC4-2-u4-X38','SC4-2-u4-X35']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C24","difficulty":3,"kind":"mc","stem":"「위협받는 건강」 그림에 알맞은 이야기는 무엇인가요?","options":[{"t":"뜨거운 햇볕으로 열사병과 같은 온열 질환에 걸린 환자가 많아진다","correct":true},{"t":"동물과 식물들이 살 곳을 잃는다","mis":"SC4-2-u4-X38"},{"t":"비가 적게 와서 마실 물이 부족해진다","mis":"SC4-2-u4-X38"},{"t":"사람들이 점점 더 건강해진다","mis":"SC4-2-u4-X35"}],"explanation":["건강과 관계있는 것을 찾아요.","질환이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["파괴되는 생태계","심각해지는 자연재해","부족해지는 물","위협받는 건강"],"title":"기후 변화가 미치는 영향 그림 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_challenge#7','sci',4,2,'u4','L05','g4_2_sci_u4_L05_challenge','lesson_challenge','SC4-2-u4-C23',3,'mc','auto','「파괴되는 생태계」로 일어나는 일은 무엇인가요?',ARRAY['SC4-2-u4-X35','SC4-2-u4-X38']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C23","difficulty":3,"kind":"mc","stem":"「파괴되는 생태계」로 일어나는 일은 무엇인가요?","options":[{"t":"동물과 식물들이 살 곳을 잃고 점점 사라진다","correct":true},{"t":"동물과 식물들이 점점 늘어난다","mis":"SC4-2-u4-X35"},{"t":"온열 질환 환자가 늘어난다","mis":"SC4-2-u4-X38"},{"t":"집이 물에 잠긴다","mis":"SC4-2-u4-X38"}],"explanation":["생태계는 생물들이 사는 곳이에요.","살 곳을 잃어요.","첫 번째예요."],"asset":{"type":"passage","lines":["파괴되는 생태계","심각해지는 자연재해","부족해지는 물","위협받는 건강"],"title":"기후 변화가 미치는 영향 그림 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_challenge#8','sci',4,2,'u4','L05','g4_2_sci_u4_L05_challenge','lesson_challenge','SC4-2-u4-C25',4,'mc','auto','친구가 「동해안 바닷물이 차가워져서 오징어가 줄어든 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X39','SC4-2-u4-X34']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C25","difficulty":4,"kind":"mc","stem":"친구가 「동해안 바닷물이 차가워져서 오징어가 줄어든 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「기후 변화로 동해안의 수온이 상승해서 오징어가 다른 곳으로 이동한 거야.」","correct":true},{"t":"「맞아, 바닷물이 차가워졌어.」","mis":"SC4-2-u4-X39"},{"t":"「비가 많이 와서 그래.」","mis":"SC4-2-u4-X39"},{"t":"「기후 변화는 바다와 상관없어.」","mis":"SC4-2-u4-X34"}],"explanation":["바닷물의 온도를 떠올려요.","따뜻해졌어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_challenge#9','sci',4,2,'u4','L05','g4_2_sci_u4_L05_challenge','lesson_challenge','SC4-2-u4-C26',4,'mc','auto','친구가 「우리 모둠 삼각책이 제일 예쁘니까 설명은 안 해도 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X40','SC4-2-u4-X25']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C26","difficulty":4,"kind":"mc","stem":"친구가 「우리 모둠 삼각책이 제일 예쁘니까 설명은 안 해도 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「삼각책은 조사한 영향을 설명하려고 만든 거야. 내용을 설명하고 다른 모둠의 설명도 들어 보자.」","correct":true},{"t":"「맞아, 예쁘면 끝이야.」","mis":"SC4-2-u4-X40"},{"t":"「출처 없이 아무 내용이나 쓰자.」","mis":"SC4-2-u4-X25"},{"t":"「색을 더 칠하면 설명이 저절로 돼.」","mis":"SC4-2-u4-X40"}],"explanation":["삼각책을 만든 까닭을 떠올려요.","설명이 중요해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L05_challenge#10','sci',4,2,'u4','L05','g4_2_sci_u4_L05_challenge','lesson_challenge','SC4-2-u4-C22',4,'essay','teacher','기후 변화로 우리 생활이 불편해진 모습과 환경이 달라진 모습을 하나씩 쓰고, 기후 변화가 언제 우리에게 영향을 미치는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u4-C22","difficulty":4,"kind":"essay","stem":"기후 변화로 우리 생활이 불편해진 모습과 환경이 달라진 모습을 하나씩 쓰고, 기후 변화가 언제 우리에게 영향을 미치는지 쓰세요.","answer_guide":{"answer":"예: 폭염으로 야외 활동을 할 수 없는 것처럼 우리 생활이 불편해진다. 생태계가 파괴되어 동물과 식물들이 사라지는 것처럼 환경이 달라진다. 기후 변화는 먼 미래의 일이 아니라 이미 우리 생활과 환경에 영향을 미치고 있다.","scoring_points":["생활이 불편해진 모습을 썼는가","환경이 달라진 모습을 썼는가","이미 영향을 미치고 있음을 썼는가"]},"explanation":["경험과 그림을 떠올려요.","둘로 나눠 써요.","언제인지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_basic#1','sci',4,2,'u4','L06','g4_2_sci_u4_L06_basic','lesson_basic','SC4-2-u4-C31',1,'mc','auto','가까운 거리를 걷는 것은 기후 변화 대응 방법일까요?',ARRAY['SC4-2-u4-X44','SC4-2-u4-X41']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C31","difficulty":1,"kind":"mc","stem":"가까운 거리를 걷는 것은 기후 변화 대응 방법일까요?","options":[{"t":"맞다, 기후 변화 대응 방법 가운데 하나이다","correct":true},{"t":"아니다, 가까운 거리도 자동차를 타야 한다","mis":"SC4-2-u4-X44"},{"t":"아니다, 걷기는 기후 변화와 관계가 없다","mis":"SC4-2-u4-X44"},{"t":"아니다, 대응 방법은 나라에서만 할 수 있다","mis":"SC4-2-u4-X41"}],"explanation":["붙임딱지 넷째 장이에요.","걸어 다녀요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_basic#2','sci',4,2,'u4','L06','g4_2_sci_u4_L06_basic','lesson_basic','SC4-2-u4-C30',1,'mc','auto','기후 변화로부터 지구를 지키는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u4-X44','SC4-2-u4-X45']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C30","difficulty":1,"kind":"mc","stem":"기후 변화로부터 지구를 지키는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"친환경 에너지를 사용하고 나무를 심어 숲을 되살린다","correct":true},{"t":"나무를 베어 건물을 많이 짓는다","mis":"SC4-2-u4-X44"},{"t":"일회용 비닐봉지를 자주 사용한다","mis":"SC4-2-u4-X44"},{"t":"화석 연료를 더 많이 사용한다","mis":"SC4-2-u4-X45"}],"explanation":["친구들의 생각을 떠올려요.","에너지와 숲이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_basic#3','sci',4,2,'u4','L06','g4_2_sci_u4_L06_basic','lesson_basic','SC4-2-u4-C27',1,'ox','auto','기후 변화 대응은 나 혼자서만 하면 돼요.',ARRAY['SC4-2-u4-X41']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C27","difficulty":1,"kind":"ox","stem":"기후 변화 대응은 나 혼자서만 하면 돼요.","answer":"X","reason_options":[{"t":"국가와 사회, 과학자, 사람들이 함께 대응해야 하기 때문에","correct":true},{"t":"한 사람의 노력만으로 모든 문제를 해결할 수 있기 때문에","mis":"SC4-2-u4-X41"}],"mis":"SC4-2-u4-X41","explanation":["누가 대응하나요?","여럿이 함께해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_basic#4','sci',4,2,'u4','L06','g4_2_sci_u4_L06_basic','lesson_basic','SC4-2-u4-C29',1,'sa','auto','무더운 여름철에 수확할 수 있도록 새로 개발한 사과 품종의 이름을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u4-C29","difficulty":1,"kind":"sa","stem":"무더운 여름철에 수확할 수 있도록 새로 개발한 사과 품종의 이름을 쓰세요.","answer":["서머킹"],"explanation":["생활 속 과학을 떠올려요.","여름의 왕이라는 뜻이에요.","서머킹이에요."],"mis":"SC4-2-u4-X43"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_basic#5','sci',4,2,'u4','L06','g4_2_sci_u4_L06_basic','lesson_basic','SC4-2-u4-C28',2,'match','auto','붙임딱지와 알맞은 예를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-2-u4-C28","difficulty":2,"kind":"match","stem":"붙임딱지와 알맞은 예를 이으세요.","pairs":[{"l":"나무를 심고 숲을 되살려요","r":"국가와 사회가 숲을 되살려요"},{"l":"대응하기 위한 기술을 연구해요","r":"새로운 품종의 사과를 개발해요"},{"l":"친환경 에너지를 사용해요","r":"태양 에너지, 풍력 에너지를 개발하고 사용해요"},{"l":"가까운 거리는 걸어 다녀요","r":"등하교 때 대중교통을 이용하거나 걸어서 다녀요"}],"mis":"SC4-2-u4-X42","explanation":["붙임딱지 네 장을 떠올려요.","예를 찾아요.","하나씩 이어요."],"asset":{"type":"passage","lines":["나무를 심고 숲을 되살려요","대응하기 위한 기술을 연구해요","친환경 에너지를 사용해요","가까운 거리는 걸어 다녀요"],"title":"기후 변화 대응 방법 붙임딱지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_basic#6','sci',4,2,'u4','L06','g4_2_sci_u4_L06_basic','lesson_basic','SC4-2-u4-C30',2,'mc','auto','친환경 에너지의 예로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u4-X45','SC4-2-u4-X44']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C30","difficulty":2,"kind":"mc","stem":"친환경 에너지의 예로 알맞은 것은 무엇인가요?","options":[{"t":"태양 에너지, 풍력 에너지","correct":true},{"t":"화석 연료를 더 많이 태우는 것","mis":"SC4-2-u4-X45"},{"t":"쓰지 않는 전기 제품을 켜 두는 것","mis":"SC4-2-u4-X44"},{"t":"석탄을 많이 캐는 것","mis":"SC4-2-u4-X45"}],"explanation":["붙임딱지 셋째 장이에요.","햇빛과 바람이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_basic#7','sci',4,2,'u4','L06','g4_2_sci_u4_L06_basic','lesson_basic','SC4-2-u4-C28',2,'mc','auto','국가와 사회가 하는 기후 변화 대응 노력은 무엇인가요?',ARRAY['SC4-2-u4-X42','SC4-2-u4-X44']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C28","difficulty":2,"kind":"mc","stem":"국가와 사회가 하는 기후 변화 대응 노력은 무엇인가요?","options":[{"t":"화석 연료 사용을 줄이기 위한 법과 제도를 만든다","correct":true},{"t":"양치할 때 컵에 물을 받아서 한다","mis":"SC4-2-u4-X42"},{"t":"급식을 먹을 만큼만 받는다","mis":"SC4-2-u4-X42"},{"t":"숲을 파괴하고 도로를 넓힌다","mis":"SC4-2-u4-X44"}],"explanation":["나라가 하는 일이에요.","규칙을 만들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_basic#8','sci',4,2,'u4','L06','g4_2_sci_u4_L06_basic','lesson_basic','SC4-2-u4-C29',2,'ox','auto','과학자들은 기후 변화에 강한 씨앗이나 친환경 에너지 개발 같은 새로운 기술을 연구해요.',ARRAY['SC4-2-u4-X43']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C29","difficulty":2,"kind":"ox","stem":"과학자들은 기후 변화에 강한 씨앗이나 친환경 에너지 개발 같은 새로운 기술을 연구해요.","answer":"O","reason_options":[{"t":"기후 변화에 대응하는 기술을 연구하는 것도 대응 방법이기 때문에","correct":true},{"t":"과학자는 기후 변화와 관계없는 일만 하기 때문에","mis":"SC4-2-u4-X43"}],"mis":"SC4-2-u4-X43","explanation":["붙임딱지 둘째 장이에요.","기술을 연구해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_basic#9','sci',4,2,'u4','L06','g4_2_sci_u4_L06_basic','lesson_basic','SC4-2-u4-C31',2,'mc','auto','학교에서 실천할 수 있는 기후 변화 대응 방법은 무엇일까요?',ARRAY['SC4-2-u4-X44']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C31","difficulty":2,"kind":"mc","stem":"학교에서 실천할 수 있는 기후 변화 대응 방법은 무엇일까요?","options":[{"t":"급식 시간에 먹을 만큼만 받고 음식물을 남기지 않는다","correct":true},{"t":"급식을 많이 받아 남긴다","mis":"SC4-2-u4-X44"},{"t":"빈 교실의 전등도 켜 둔다","mis":"SC4-2-u4-X44"},{"t":"가까워도 늘 자가용으로 등하교한다","mis":"SC4-2-u4-X44"}],"explanation":["학교생활을 떠올려요.","남기지 않아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
