INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_challenge#1','sci',4,2,'u4','L06','g4_2_sci_u4_L06_challenge','lesson_challenge','SC4-2-u4-C31',2,'blank','auto','「샤워를 너무 길게 하지 않고 세탁물을 모아서 세탁기를 돌려 (    )을 아껴요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u4-X44']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C31","difficulty":2,"kind":"blank","stem":"「샤워를 너무 길게 하지 않고 세탁물을 모아서 세탁기를 돌려 (    )을 아껴요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"물","correct":true},{"t":"시간","mis":"SC4-2-u4-X44"},{"t":"세제","mis":"SC4-2-u4-X44"},{"t":"옷","mis":"SC4-2-u4-X44"}],"explanation":["샤워와 세탁기를 떠올려요.","흐르는 것이에요.","물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_challenge#2','sci',4,2,'u4','L06','g4_2_sci_u4_L06_challenge','lesson_challenge','SC4-2-u4-C27',2,'mc','auto','기후 변화 대응에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u4-X41','SC4-2-u4-X42']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C27","difficulty":2,"kind":"mc","stem":"기후 변화 대응에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"국가와 사회, 과학자, 사람들이 함께 기후 변화에 대응한다","correct":true},{"t":"나 혼자서만 하면 된다","mis":"SC4-2-u4-X41"},{"t":"나라에서만 할 수 있다","mis":"SC4-2-u4-X41"},{"t":"과학자만 할 수 있다","mis":"SC4-2-u4-X42"}],"explanation":["정리해요를 떠올려요.","세 무리가 나와요.","함께 대응해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_challenge#3','sci',4,2,'u4','L06','g4_2_sci_u4_L06_challenge','lesson_challenge','SC4-2-u4-C31',3,'error','auto','기후 변화 대응 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u4-X44','SC4-2-u4-X41']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C31","difficulty":3,"kind":"error","stem":"기후 변화 대응 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「비닐봉지를 자주 쓰는 것도 대응 방법이야.」","correct":true,"mis_target":"SC4-2-u4-X44"},{"t":"친구 가 — 「불필요한 전등의 전원을 끄는 건 대응 방법이야.」","mis":"SC4-2-u4-X44"},{"t":"친구 다 — 「국가와 사회도 숲을 되살리며 대응해.」","mis":"SC4-2-u4-X41"}],"explanation":["쓰레기를 늘리는 것을 찾아요.","비닐봉지는 일회용품이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_challenge#4','sci',4,2,'u4','L06','g4_2_sci_u4_L06_challenge','lesson_challenge','SC4-2-u4-C28',3,'mc','auto','「국가와 사회, 과학자」가 하는 노력과 「사람들」이 하는 노력을 바르게 나눈 것은 무엇인가요?',ARRAY['SC4-2-u4-X42','SC4-2-u4-X41']::text[],false,'{"seq":4,"concept":"SC4-2-u4-C28","difficulty":3,"kind":"mc","stem":"「국가와 사회, 과학자」가 하는 노력과 「사람들」이 하는 노력을 바르게 나눈 것은 무엇인가요?","options":[{"t":"국가와 사회, 과학자 — 법과 제도 만들기, 씨앗 연구 / 사람들 — 에너지 절약, 일회용품 안 쓰기","correct":true},{"t":"국가와 사회, 과학자 — 에너지 절약 / 사람들 — 법과 제도 만들기","mis":"SC4-2-u4-X42"},{"t":"국가와 사회, 과학자 — 일회용품 안 쓰기 / 사람들 — 씨앗 연구","mis":"SC4-2-u4-X42"},{"t":"모두 사람들만 하는 노력이다","mis":"SC4-2-u4-X41"}],"explanation":["누가 하는 일인지 따져요.","법은 나라가, 연구는 과학자가 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_challenge#5','sci',4,2,'u4','L06','g4_2_sci_u4_L06_challenge','lesson_challenge','SC4-2-u4-C30',3,'ox','auto','화석 연료 사용을 줄이고 친환경 에너지를 사용하는 것은 기후 변화 대응 방법이에요.',ARRAY['SC4-2-u4-X45']::text[],false,'{"seq":5,"concept":"SC4-2-u4-C30","difficulty":3,"kind":"ox","stem":"화석 연료 사용을 줄이고 친환경 에너지를 사용하는 것은 기후 변화 대응 방법이에요.","answer":"O","reason_options":[{"t":"화석 연료 사용은 기후 변화를 심각하게 만들기 때문에","correct":true},{"t":"친환경 에너지는 화석 연료를 더 많이 쓰는 것이기 때문에","mis":"SC4-2-u4-X45"}],"mis":"SC4-2-u4-X45","explanation":["화석 연료를 떠올려요.","줄여야 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_challenge#6','sci',4,2,'u4','L06','g4_2_sci_u4_L06_challenge','lesson_challenge','SC4-2-u4-C31',3,'mc','auto','생활 속 대응 방법만 모은 것은 무엇인가요?',ARRAY['SC4-2-u4-X44','SC4-2-u4-X42']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C31","difficulty":3,"kind":"mc","stem":"생활 속 대응 방법만 모은 것은 무엇인가요?","options":[{"t":"전기 절약하기, 일회용품 줄이기, 음식물 쓰레기 줄이기","correct":true},{"t":"전기 절약하기, 비닐봉지 자주 쓰기, 음식 남기기","mis":"SC4-2-u4-X44"},{"t":"일회용품 많이 쓰기, 전등 켜 두기, 걸어 다니기","mis":"SC4-2-u4-X44"},{"t":"법과 제도 만들기, 씨앗 연구하기, 숲 되살리기","mis":"SC4-2-u4-X42"}],"explanation":["우리 생활에서 할 수 있는 것이에요.","아끼고 줄여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_challenge#7','sci',4,2,'u4','L06','g4_2_sci_u4_L06_challenge','lesson_challenge','SC4-2-u4-C29',3,'mc','auto','서머킹의 특징으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u4-X43']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C29","difficulty":3,"kind":"mc","stem":"서머킹의 특징으로 알맞은 것은 무엇인가요?","options":[{"t":"무더운 여름철에 수확할 수 있고 재배하기 쉬우며 새콤달콤하다","correct":true},{"t":"겨울에만 수확할 수 있다","mis":"SC4-2-u4-X43"},{"t":"재배하기가 아주 어렵다","mis":"SC4-2-u4-X43"},{"t":"기후 변화로 늘어난 사과밭에서만 자란다","mis":"SC4-2-u4-X43"}],"explanation":["생활 속 과학을 떠올려요.","여름에 거둬요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_challenge#8','sci',4,2,'u4','L06','g4_2_sci_u4_L06_challenge','lesson_challenge','SC4-2-u4-C27',4,'mc','auto','친구가 「기후 변화는 너무 커서 우리가 할 수 있는 일은 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X08','SC4-2-u4-X41','SC4-2-u4-X42']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C27","difficulty":4,"kind":"mc","stem":"친구가 「기후 변화는 너무 커서 우리가 할 수 있는 일은 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「국가와 사회, 과학자, 사람들이 함께 대응해. 우리도 걸어 다니기, 에너지 절약하기로 대응할 수 있어.」","correct":true},{"t":"「맞아, 무섭기만 해.」","mis":"SC4-2-u4-X08"},{"t":"「나라에서만 할 수 있어.」","mis":"SC4-2-u4-X41"},{"t":"「과학자만 하면 돼.」","mis":"SC4-2-u4-X42"}],"explanation":["누가 대응하나요?","우리도 할 수 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_challenge#9','sci',4,2,'u4','L06','g4_2_sci_u4_L06_challenge','lesson_challenge','SC4-2-u4-C30',4,'mc','auto','친구가 「친환경 에너지는 화석 연료를 더 많이 쓰는 방법이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X45','SC4-2-u4-X44','SC4-2-u4-X41']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C30","difficulty":4,"kind":"mc","stem":"친구가 「친환경 에너지는 화석 연료를 더 많이 쓰는 방법이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「친환경 에너지는 화석 연료 사용을 줄이고 태양 에너지, 풍력 에너지 같은 에너지를 쓰는 거야.」","correct":true},{"t":"「맞아, 화석 연료를 더 써야 해.」","mis":"SC4-2-u4-X45"},{"t":"「친환경 에너지는 전등을 켜 두는 거야.」","mis":"SC4-2-u4-X44"},{"t":"「친환경 에너지는 나 혼자만 쓰는 거야.」","mis":"SC4-2-u4-X41"}],"explanation":["붙임딱지 셋째 장을 떠올려요.","햇빛과 바람이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L06_challenge#10','sci',4,2,'u4','L06','g4_2_sci_u4_L06_challenge','lesson_challenge','SC4-2-u4-C27',4,'essay','teacher','국가와 사회, 과학자, 사람들이 할 수 있는 기후 변화 대응 방법을 하나씩 쓰고, 왜 함께 대응해야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u4-C27","difficulty":4,"kind":"essay","stem":"국가와 사회, 과학자, 사람들이 할 수 있는 기후 변화 대응 방법을 하나씩 쓰고, 왜 함께 대응해야 하는지 쓰세요.","answer_guide":{"answer":"예: 국가와 사회는 숲을 되살리고 법과 제도를 만든다. 과학자는 기후 변화에 강한 씨앗이나 친환경 에너지 같은 새로운 기술을 연구한다. 사람들은 가까운 거리를 걸어 다니고 에너지를 절약한다. 기후 변화는 한 사람이 해결할 수 없으므로 모두 함께 대응해야 한다.","scoring_points":["국가와 사회의 대응을 썼는가","과학자의 대응을 썼는가","사람들의 대응과 함께해야 하는 까닭을 썼는가"]},"explanation":["붙임딱지를 떠올려요.","셋을 나눠 써요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_basic#1','sci',4,2,'u4','L07','g4_2_sci_u4_L07_basic','lesson_basic','SC4-2-u4-C32',1,'mc','auto','기후 변화 대응 방법은 어떻게 실천하는 것이 중요할까요?',ARRAY['SC4-2-u4-X46']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C32","difficulty":1,"kind":"mc","stem":"기후 변화 대응 방법은 어떻게 실천하는 것이 중요할까요?","options":[{"t":"일상생활에서 함께 실천하는 것","correct":true},{"t":"일 년에 한 번만 실천하는 것","mis":"SC4-2-u4-X46"},{"t":"다른 사람이 할 때까지 기다리는 것","mis":"SC4-2-u4-X46"},{"t":"텔레비전에서만 보는 것","mis":"SC4-2-u4-X46"}],"explanation":["도전해요를 떠올려요.","날마다, 여럿이 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_basic#2','sci',4,2,'u4','L07','g4_2_sci_u4_L07_basic','lesson_basic','SC4-2-u4-C32',1,'mc','auto','생활 속에서 기후 변화 대응 방법을 실천하는 것이 중요한 까닭은 무엇일까요?',ARRAY['SC4-2-u4-X46','SC4-2-u4-X50']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C32","difficulty":1,"kind":"mc","stem":"생활 속에서 기후 변화 대응 방법을 실천하는 것이 중요한 까닭은 무엇일까요?","options":[{"t":"많은 사람들이 함께 실천하여 기후 변화가 더 심해지는 것을 막기 위해서","correct":true},{"t":"친구들보다 먼저 칭찬을 받기 위해서","mis":"SC4-2-u4-X46"},{"t":"계획표를 예쁘게 꾸미기 위해서","mis":"SC4-2-u4-X50"},{"t":"텔레비전에 나오기 위해서","mis":"SC4-2-u4-X46"}],"explanation":["왜 실천할까요?","더 심해지는 것을 막아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_basic#3','sci',4,2,'u4','L07','g4_2_sci_u4_L07_basic','lesson_basic','SC4-2-u4-C34',1,'ox','auto','계획을 세운 뒤에는 꾸준히 실천하고 점검하는 것이 중요해요.',ARRAY['SC4-2-u4-X49']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C34","difficulty":1,"kind":"ox","stem":"계획을 세운 뒤에는 꾸준히 실천하고 점검하는 것이 중요해요.","answer":"O","reason_options":[{"t":"매일 실천하는 습관이 있어야 목표를 이룰 수 있기 때문에","correct":true},{"t":"계획표만 만들면 실천하지 않아도 목표가 이루어지기 때문에","mis":"SC4-2-u4-X49"}],"mis":"SC4-2-u4-X49","explanation":["실천해요를 떠올려요.","꾸준히 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_basic#4','sci',4,2,'u4','L07','g4_2_sci_u4_L07_basic','lesson_basic','SC4-2-u4-C34',1,'sa','auto','매일 실천했는지 표시하며 확인하는 표를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u4-C34","difficulty":1,"kind":"sa","stem":"매일 실천했는지 표시하며 확인하는 표를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["점검표"],"explanation":["날마다 확인해요.","「점검」하는 표예요.","점검표예요."],"mis":"SC4-2-u4-X49"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_basic#5','sci',4,2,'u4','L07','g4_2_sci_u4_L07_basic','lesson_basic','SC4-2-u4-C33',2,'match','auto','계획표의 칸과 알맞은 내용을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-2-u4-C33","difficulty":2,"kind":"match","stem":"계획표의 칸과 알맞은 내용을 이으세요.","pairs":[{"l":"기후 변화 대응 목표","r":"생활 속 에너지를 절약하자!"},{"l":"실천 내용","r":"아무도 없는 방의 전등 끄기"},{"l":"제목","r":"생활 속 기후 변화 대응 에너지 절약왕"},{"l":"목표를 이루는 방법","r":"점검표를 만들어 매일 실천하고 점검하기"}],"mis":"SC4-2-u4-X47","explanation":["칸 이름을 읽어요.","칸마다 할 일이 달라요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_basic#6','sci',4,2,'u4','L07','g4_2_sci_u4_L07_basic','lesson_basic','SC4-2-u4-C33',2,'mc','auto','계획표의 「평소 나의 부족한 점」 칸에 쓸 내용은 무엇인가요?',ARRAY['SC4-2-u4-X47']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C33","difficulty":2,"kind":"mc","stem":"계획표의 「평소 나의 부족한 점」 칸에 쓸 내용은 무엇인가요?","options":[{"t":"계단 대신 승강기를 주로 이용한다","correct":true},{"t":"사용하지 않는 전자 제품의 플러그 뽑기","mis":"SC4-2-u4-X47"},{"t":"급식을 먹을 만큼만 받기","mis":"SC4-2-u4-X47"},{"t":"생활 속 에너지를 절약하자!","mis":"SC4-2-u4-X47"}],"explanation":["부족한 점은 고칠 습관이에요.","지금의 내 모습이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_basic#7','sci',4,2,'u4','L07','g4_2_sci_u4_L07_basic','lesson_basic','SC4-2-u4-C34',2,'mc','auto','목표를 이루는 데 도움이 되는 것은 무엇인가요?',ARRAY['SC4-2-u4-X49']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C34","difficulty":2,"kind":"mc","stem":"목표를 이루는 데 도움이 되는 것은 무엇인가요?","options":[{"t":"실천 계획표를 내 방 잘 보이는 곳에 붙여 놓는다","correct":true},{"t":"내일부터 해야겠다고 미룬다","mis":"SC4-2-u4-X49"},{"t":"난방기를 켤 때 창문을 열어 놓는다","mis":"SC4-2-u4-X49"},{"t":"계획표를 서랍 속에 넣어 둔다","mis":"SC4-2-u4-X49"}],"explanation":["잊지 않는 방법을 찾아요.","눈에 잘 보여요.","첫 번째예요."],"asset":{"type":"passage","lines":["기후 변화 대응 목표 — 생활 속 에너지를 절약하자!","실천 내용 — 쓰지 않는 전자 제품의 플러그 뽑기, 빈방 전등 끄기","제목 — 생활 속 기후 변화 대응 에너지 절약왕","목표를 이루는 방법 — 계획표를 내 방 잘 보이는 곳에 붙이기"],"title":"기후 변화 대응 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_basic#8','sci',4,2,'u4','L07','g4_2_sci_u4_L07_basic','lesson_basic','SC4-2-u4-C32',2,'ox','auto','기후 변화가 더 심해질까 봐 걱정만 하는 것이 가장 좋은 방법이에요.',ARRAY['SC4-2-u4-X08']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C32","difficulty":2,"kind":"ox","stem":"기후 변화가 더 심해질까 봐 걱정만 하는 것이 가장 좋은 방법이에요.","answer":"X","reason_options":[{"t":"걱정만 하기보다 나부터 계획을 세워 실천하는 것이 중요하기 때문에","correct":true},{"t":"걱정을 많이 하면 기후 변화가 저절로 줄어들기 때문에","mis":"SC4-2-u4-X08"}],"mis":"SC4-2-u4-X08","explanation":["만화의 마지막 말을 떠올려요.","나부터 실천해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_basic#9','sci',4,2,'u4','L07','g4_2_sci_u4_L07_basic','lesson_basic','SC4-2-u4-C35',2,'mc','auto','친구의 계획과 실천 결과를 평가할 때 살펴볼 것은 무엇인가요?',ARRAY['SC4-2-u4-X50']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C35","difficulty":2,"kind":"mc","stem":"친구의 계획과 실천 결과를 평가할 때 살펴볼 것은 무엇인가요?","options":[{"t":"생활 속에서 실천할 수 있는 계획을 세웠는가","correct":true},{"t":"친구들보다 먼저 끝냈는가","mis":"SC4-2-u4-X50"},{"t":"계획표를 가장 많은 색으로 칠했는가","mis":"SC4-2-u4-X50"},{"t":"계획표를 가장 크게 그렸는가","mis":"SC4-2-u4-X50"}],"explanation":["평가 기준을 떠올려요.","실천할 수 있는지 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
