INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_challenge#1','sci',4,2,'u4','L07','g4_2_sci_u4_L07_challenge','lesson_challenge','SC4-2-u4-C34',2,'blank','auto','「계획을 세운 뒤에는 (    ) 실천하고 점검해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u4-X48','SC4-2-u4-X49','SC4-2-u4-X46']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C34","difficulty":2,"kind":"blank","stem":"「계획을 세운 뒤에는 (    ) 실천하고 점검해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"꾸준히","correct":true},{"t":"한 번만","mis":"SC4-2-u4-X48"},{"t":"내일부터","mis":"SC4-2-u4-X49"},{"t":"친구만","mis":"SC4-2-u4-X46"}],"explanation":["실천해요를 떠올려요.","날마다 해요.","꾸준히예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_challenge#2','sci',4,2,'u4','L07','g4_2_sci_u4_L07_challenge','lesson_challenge','SC4-2-u4-C35',2,'mc','auto','기후 변화 퀴즈 대회에서 문제를 틀렸을 때 알맞은 행동은 무엇인가요?',ARRAY['SC4-2-u4-X50','SC4-2-u4-X46']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C35","difficulty":2,"kind":"mc","stem":"기후 변화 퀴즈 대회에서 문제를 틀렸을 때 알맞은 행동은 무엇인가요?","options":[{"t":"그 내용을 배운 차시로 돌아가 스스로 확인한다","correct":true},{"t":"다른 친구의 답을 그대로 베낀다","mis":"SC4-2-u4-X50"},{"t":"틀린 문제는 건너뛰고 빨리 끝낸다","mis":"SC4-2-u4-X50"},{"t":"퀴즈를 그만둔다","mis":"SC4-2-u4-X46"}],"explanation":["틀린 까닭을 찾아요.","배운 곳으로 돌아가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_challenge#3','sci',4,2,'u4','L07','g4_2_sci_u4_L07_challenge','lesson_challenge','SC4-2-u4-C33',3,'error','auto','계획표를 소개하며 친구들이 말했어요. 목표와 실천 내용이 이어지지 않는 친구는 누구인가요?',ARRAY['SC4-2-u4-X48','SC4-2-u4-X49','SC4-2-u4-X47']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C33","difficulty":3,"kind":"error","stem":"계획표를 소개하며 친구들이 말했어요. 목표와 실천 내용이 이어지지 않는 친구는 누구인가요?","options":[{"t":"친구 다 — 「목표는 전기를 아끼자인데, 실천 내용은 먹기 싫은 급식 버리기로 했어.」","correct":true,"mis_target":"SC4-2-u4-X48"},{"t":"친구 가 — 「실천 계획표를 잘 보이는 곳에 붙였어.」","mis":"SC4-2-u4-X49"},{"t":"친구 나 — 「아무도 없는 방의 전등을 끄기로 했어.」","mis":"SC4-2-u4-X47"}],"explanation":["목표와 실천 내용을 견줘요.","전기와 급식은 이어지지 않아요.","친구 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_challenge#4','sci',4,2,'u4','L07','g4_2_sci_u4_L07_challenge','lesson_challenge','SC4-2-u4-C34',3,'mc','auto','「내일부터 해야겠다고 미루는 마음이 들어서 어려웠어요.」라고 한 친구에게 알맞은 다음 다짐은 무엇인가요?',ARRAY['SC4-2-u4-X49','SC4-2-u4-X50','SC4-2-u4-X46']::text[],false,'{"seq":4,"concept":"SC4-2-u4-C34","difficulty":3,"kind":"mc","stem":"「내일부터 해야겠다고 미루는 마음이 들어서 어려웠어요.」라고 한 친구에게 알맞은 다음 다짐은 무엇인가요?","options":[{"t":"다음에는 미루지 않고 꾸준히 실천한다","correct":true},{"t":"어려우니 실천을 그만둔다","mis":"SC4-2-u4-X49"},{"t":"계획표를 예쁘게 다시 꾸미기만 한다","mis":"SC4-2-u4-X50"},{"t":"다른 사람이 할 때까지 기다린다","mis":"SC4-2-u4-X46"}],"explanation":["실천해요를 떠올려요.","미루지 않아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_challenge#5','sci',4,2,'u4','L07','g4_2_sci_u4_L07_challenge','lesson_challenge','SC4-2-u4-C35',3,'ox','auto','친구의 계획을 평가할 때에는 계획표를 가장 많은 색으로 칠했는지를 살펴봐요.',ARRAY['SC4-2-u4-X50']::text[],false,'{"seq":5,"concept":"SC4-2-u4-C35","difficulty":3,"kind":"ox","stem":"친구의 계획을 평가할 때에는 계획표를 가장 많은 색으로 칠했는지를 살펴봐요.","answer":"X","reason_options":[{"t":"대응 방법이 잘 나타나 있고 실천할 수 있는 계획인지를 살펴보아야 하기 때문에","correct":true},{"t":"색을 많이 칠한 계획표가 가장 잘 실천한 계획표이기 때문에","mis":"SC4-2-u4-X50"}],"mis":"SC4-2-u4-X50","explanation":["평가 기준을 떠올려요.","대응 방법과 실천이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_challenge#6','sci',4,2,'u4','L07','g4_2_sci_u4_L07_challenge','lesson_challenge','SC4-2-u4-C33',3,'mc','auto','계획표에서 「실천 내용」 칸에 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u4-X47','SC4-2-u4-X48']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C33","difficulty":3,"kind":"mc","stem":"계획표에서 「실천 내용」 칸에 알맞은 것은 무엇인가요?","options":[{"t":"사용하지 않는 전자 제품의 플러그 뽑기","correct":true},{"t":"일회용품을 자주 사용해요","mis":"SC4-2-u4-X47"},{"t":"생활 속 기후 변화 대응 에너지 절약왕","mis":"SC4-2-u4-X47"},{"t":"하늘의 구름 모두 없애기","mis":"SC4-2-u4-X48"}],"explanation":["실제로 할 일이에요.","날마다 할 수 있어요.","첫 번째예요."],"asset":{"type":"passage","lines":["기후 변화 대응 목표 — 생활 속 에너지를 절약하자!","실천 내용 — 쓰지 않는 전자 제품의 플러그 뽑기, 빈방 전등 끄기","제목 — 생활 속 기후 변화 대응 에너지 절약왕","목표를 이루는 방법 — 계획표를 내 방 잘 보이는 곳에 붙이기"],"title":"기후 변화 대응 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_challenge#7','sci',4,2,'u4','L07','g4_2_sci_u4_L07_challenge','lesson_challenge','SC4-2-u4-C32',3,'mc','auto','「나부터 실천해야겠어!」라는 말에 담긴 마음은 무엇인가요?',ARRAY['SC4-2-u4-X08','SC4-2-u4-X50','SC4-2-u4-X46']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C32","difficulty":3,"kind":"mc","stem":"「나부터 실천해야겠어!」라는 말에 담긴 마음은 무엇인가요?","options":[{"t":"다른 사람을 기다리지 않고 내가 먼저 생활 속에서 실천하려는 마음","correct":true},{"t":"기후 변화가 무서워서 아무것도 하지 않으려는 마음","mis":"SC4-2-u4-X08"},{"t":"친구보다 먼저 끝내 이기려는 마음","mis":"SC4-2-u4-X50"},{"t":"남이 하면 그때 따라 하려는 마음","mis":"SC4-2-u4-X46"}],"explanation":["「나부터」를 생각해요.","내가 먼저예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_challenge#8','sci',4,2,'u4','L07','g4_2_sci_u4_L07_challenge','lesson_challenge','SC4-2-u4-C34',4,'mc','auto','친구가 「일주일 동안 실천하는 건 힘드니까 딱 하루만 하면 충분해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X48','SC4-2-u4-X49','SC4-2-u4-X50']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C34","difficulty":4,"kind":"mc","stem":"친구가 「일주일 동안 실천하는 건 힘드니까 딱 하루만 하면 충분해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「매일 실천하는 습관이 중요해. 점검표를 만들어 매일 기록하면 꾸준히 할 수 있어.」","correct":true},{"t":"「맞아, 하루면 충분해.」","mis":"SC4-2-u4-X48"},{"t":"「내일부터 하면 돼.」","mis":"SC4-2-u4-X49"},{"t":"「계획표만 예쁘면 돼.」","mis":"SC4-2-u4-X50"}],"explanation":["실천해요를 떠올려요.","습관이 중요해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_challenge#9','sci',4,2,'u4','L07','g4_2_sci_u4_L07_challenge','lesson_challenge','SC4-2-u4-C33',4,'mc','auto','친구가 내 계획표를 보고 「목표와 실천 내용이 제목에 잘 드러나지 않아.」라고 했어요. 가장 알맞게 고친 것은 무엇인가요?',ARRAY['SC4-2-u4-X50','SC4-2-u4-X48','SC4-2-u4-X47']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C33","difficulty":4,"kind":"mc","stem":"친구가 내 계획표를 보고 「목표와 실천 내용이 제목에 잘 드러나지 않아.」라고 했어요. 가장 알맞게 고친 것은 무엇인가요?","options":[{"t":"제목을 「생활 속 기후 변화 대응 에너지 절약왕」처럼 목표가 드러나게 바꾼다","correct":true},{"t":"제목을 지우고 그림만 그린다","mis":"SC4-2-u4-X50"},{"t":"실천 내용을 「하늘의 구름 없애기」로 바꾼다","mis":"SC4-2-u4-X48"},{"t":"목표 칸과 제목 칸을 바꾸어 쓴다","mis":"SC4-2-u4-X47"}],"explanation":["평가 기준을 떠올려요.","제목에 목표가 보여야 해요.","첫 번째예요."],"asset":{"type":"passage","lines":["기후 변화 대응 목표 — 생활 속 에너지를 절약하자!","실천 내용 — 쓰지 않는 전자 제품의 플러그 뽑기, 빈방 전등 끄기","제목 — 생활 속 기후 변화 대응 에너지 절약왕","목표를 이루는 방법 — 계획표를 내 방 잘 보이는 곳에 붙이기"],"title":"기후 변화 대응 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L07_challenge#10','sci',4,2,'u4','L07','g4_2_sci_u4_L07_challenge','lesson_challenge','SC4-2-u4-C33',4,'essay','teacher','나만의 기후 변화 대응 계획표를 세우려고 해요. 목표, 목표와 이어지는 실천 내용 두 가지, 꾸준히 실천할 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u4-C33","difficulty":4,"kind":"essay","stem":"나만의 기후 변화 대응 계획표를 세우려고 해요. 목표, 목표와 이어지는 실천 내용 두 가지, 꾸준히 실천할 방법을 쓰세요.","answer_guide":{"answer":"예: 목표 — 생활 속 에너지를 절약하자! 실천 내용 — 사용하지 않는 전자 제품의 플러그 뽑기, 아무도 없는 방의 전등 끄기. 방법 — 점검표를 만들어 매일 실천하고 점검하며 계획표를 잘 보이는 곳에 붙여 둔다.","scoring_points":["목표를 썼는가","목표와 이어지고 실천할 수 있는 내용 두 가지를 썼는가","꾸준히 실천할 방법을 썼는가"]},"explanation":["계획표 칸을 떠올려요.","목표와 실천을 이어요.","방법을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_basic#1','sci',4,2,'u4','L08','g4_2_sci_u4_L08_basic','lesson_basic','SC4-2-u4-C36',1,'mc','auto','영구 동토는 어떤 땅인가요?',ARRAY['SC4-2-u4-X51']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C36","difficulty":1,"kind":"mc","stem":"영구 동토는 어떤 땅인가요?","options":[{"t":"오랜 기간 땅의 온도가 0 °C 이하로 유지되어 여름에도 얼어 있는 땅","correct":true},{"t":"봄이 되면 모두 녹는 땅","mis":"SC4-2-u4-X51"},{"t":"일 년 내내 뜨거운 모래 땅","mis":"SC4-2-u4-X51"},{"t":"늘 바닷물에 잠겨 있는 땅","mis":"SC4-2-u4-X51"}],"explanation":["「영구」는 오래 이어짐이에요.","「동토」는 언 땅이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_basic#2','sci',4,2,'u4','L08','g4_2_sci_u4_L08_basic','lesson_basic','SC4-2-u4-C36',1,'mc','auto','빙하를 「냉동 타임캡슐」이라고 부르기도 하는 까닭은 무엇인가요?',ARRAY['SC4-2-u4-X52']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C36","difficulty":1,"kind":"mc","stem":"빙하를 「냉동 타임캡슐」이라고 부르기도 하는 까닭은 무엇인가요?","options":[{"t":"지구 환경의 변화를 알 수 있어서","correct":true},{"t":"음식을 오래 보관하는 곳이라서","mis":"SC4-2-u4-X52"},{"t":"절대로 녹지 않아서","mis":"SC4-2-u4-X52"},{"t":"사람이 만든 냉동고라서","mis":"SC4-2-u4-X52"}],"explanation":["타임캡슐은 옛것을 담아요.","지구의 옛 모습을 담고 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_basic#3','sci',4,2,'u4','L08','g4_2_sci_u4_L08_basic','lesson_basic','SC4-2-u4-C39',1,'ox','auto','일회용품 사용을 줄이는 것은 영구 동토층을 보존하는 데 도움이 돼요.',ARRAY['SC4-2-u4-X55']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C39","difficulty":1,"kind":"ox","stem":"일회용품 사용을 줄이는 것은 영구 동토층을 보존하는 데 도움이 돼요.","answer":"O","reason_options":[{"t":"기후 변화에 대응하면 영구 동토와 빙하를 지킬 수 있기 때문에","correct":true},{"t":"일회용품은 영구 동토와 아무 관계가 없기 때문에","mis":"SC4-2-u4-X55"}],"mis":"SC4-2-u4-X55","explanation":["대응 방법을 떠올려요.","지킬 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_basic#4','sci',4,2,'u4','L08','g4_2_sci_u4_L08_basic','lesson_basic','SC4-2-u4-C36',1,'sa','auto','여름에도 얼어 있는 땅을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u4-C36","difficulty":1,"kind":"sa","stem":"여름에도 얼어 있는 땅을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["영구 동토","영구동토"],"explanation":["카드 첫 장이에요.","「영구」로 시작해요.","영구 동토예요."],"mis":"SC4-2-u4-X51"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_basic#5','sci',4,2,'u4','L08','g4_2_sci_u4_L08_basic','lesson_basic','SC4-2-u4-C37',2,'match','auto','낱말과 알맞은 설명을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-2-u4-C37","difficulty":2,"kind":"match","stem":"낱말과 알맞은 설명을 이으세요.","pairs":[{"l":"영구 동토","r":"여름에도 얼어 있는 땅이에요"},{"l":"빙하","r":"냉동 타임캡슐이라고 불리기도 해요"},{"l":"세균","r":"얼음 속에 묻혀 있다가 드러날 수 있어요"},{"l":"과학자","r":"구멍을 뚫어 얼음층을 캐낸 뒤 연구해요"}],"mis":"SC4-2-u4-X52","explanation":["카드를 떠올려요.","낱말의 뜻을 찾아요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_basic#6','sci',4,2,'u4','L08','g4_2_sci_u4_L08_basic','lesson_basic','SC4-2-u4-C37',2,'mc','auto','기후 변화로 영구 동토가 녹으면서 생기는 일은 무엇인가요?',ARRAY['SC4-2-u4-X53']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C37","difficulty":2,"kind":"mc","stem":"기후 변화로 영구 동토가 녹으면서 생기는 일은 무엇인가요?","options":[{"t":"오랫동안 얼음 속에 묻혀 있던 미생물이 되살아난다","correct":true},{"t":"땅이 더 단단하게 얼어붙는다","mis":"SC4-2-u4-X53"},{"t":"묻혀 있던 것들이 더 깊이 묻힌다","mis":"SC4-2-u4-X53"},{"t":"여름에도 얼어 있는 땅이 늘어난다","mis":"SC4-2-u4-X53"}],"explanation":["녹으면 무엇이 드러날까요?","묻혀 있던 것이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_basic#7','sci',4,2,'u4','L08','g4_2_sci_u4_L08_basic','lesson_basic','SC4-2-u4-C38',2,'mc','auto','과학자들은 빙하를 어떻게 연구하나요?',ARRAY['SC4-2-u4-X54']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C38","difficulty":2,"kind":"mc","stem":"과학자들은 빙하를 어떻게 연구하나요?","options":[{"t":"빙하에 깊게 구멍을 뚫어 잘 보존된 얼음층을 캐낸 뒤 연구한다","correct":true},{"t":"빙하를 모두 녹여 버린 뒤 연구한다","mis":"SC4-2-u4-X54"},{"t":"멀리서 사진만 찍고 연구를 마친다","mis":"SC4-2-u4-X54"},{"t":"빙하 위에서 놀이를 하며 연구한다","mis":"SC4-2-u4-X54"}],"explanation":["카드 셋째 장이에요.","구멍을 뚫어요.","첫 번째예요."],"asset":{"type":"passage","lines":["영구 동토 — 여름에도 얼어 있는 땅","빙하 — 지구 환경의 변화를 알 수 있는 냉동 타임캡슐","과학자 — 빙하에 깊게 구멍을 뚫어 얼음층을 캐낸 뒤 연구해요"],"title":"알아봐요 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_basic#8','sci',4,2,'u4','L08','g4_2_sci_u4_L08_basic','lesson_basic','SC4-2-u4-C38',2,'ox','auto','빙하 속 세균이 우리 사회에 미칠 영향은 이미 모두 밝혀졌어요.',ARRAY['SC4-2-u4-X54']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C38","difficulty":2,"kind":"ox","stem":"빙하 속 세균이 우리 사회에 미칠 영향은 이미 모두 밝혀졌어요.","answer":"X","reason_options":[{"t":"어떤 영향을 미칠지는 앞으로 연구가 더 필요하기 때문에","correct":true},{"t":"과학자들이 모든 세균을 이미 다 알아냈기 때문에","mis":"SC4-2-u4-X54"}],"mis":"SC4-2-u4-X54","explanation":["글의 끝을 떠올려요.","연구가 더 필요해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_basic#9','sci',4,2,'u4','L08','g4_2_sci_u4_L08_basic','lesson_basic','SC4-2-u4-C39',2,'mc','auto','영구 동토층을 보존하기 위해 우리가 할 수 있는 일은 무엇인가요?',ARRAY['SC4-2-u4-X55','SC4-2-u4-X08']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C39","difficulty":2,"kind":"mc","stem":"영구 동토층을 보존하기 위해 우리가 할 수 있는 일은 무엇인가요?","options":[{"t":"가까운 곳은 걸어서 이동한다","correct":true},{"t":"가까운 곳도 늘 자동차로 간다","mis":"SC4-2-u4-X55"},{"t":"일회용품을 자주 사용한다","mis":"SC4-2-u4-X55"},{"t":"할 수 있는 일이 없으니 걱정만 한다","mis":"SC4-2-u4-X08"}],"explanation":["대응 방법을 떠올려요.","걸어 다녀요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_basic#10','sci',4,2,'u4','L08','g4_2_sci_u4_L08_basic','lesson_basic','SC4-2-u4-C37',3,'mc','auto','「얼어 있을 때」의 모습은 무엇인가요?',ARRAY['SC4-2-u4-X53']::text[],false,'{"seq":10,"concept":"SC4-2-u4-C37","difficulty":3,"kind":"mc","stem":"「얼어 있을 때」의 모습은 무엇인가요?","options":[{"t":"미생물이 얼음 속에 묻혀 있다","correct":true},{"t":"미생물이 되살아난다","mis":"SC4-2-u4-X53"},{"t":"묻혀 있던 지층이 드러난다","mis":"SC4-2-u4-X53"},{"t":"빙하 속 세균이 드러난다","mis":"SC4-2-u4-X53"}],"explanation":["얼어 있으면 갇혀 있어요.","드러나는 것은 녹으면서예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_challenge#1','sci',4,2,'u4','L08','g4_2_sci_u4_L08_challenge','lesson_challenge','SC4-2-u4-C38',2,'blank','auto','「빙하 속에 있던 세균이 드러나면 우리 사회에 어떤 영향을 미칠지는 앞으로 (    )가 더 필요해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u4-X08','SC4-2-u4-X54']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C38","difficulty":2,"kind":"blank","stem":"「빙하 속에 있던 세균이 드러나면 우리 사회에 어떤 영향을 미칠지는 앞으로 (    )가 더 필요해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"연구","correct":true},{"t":"걱정","mis":"SC4-2-u4-X08"},{"t":"놀이","mis":"SC4-2-u4-X54"},{"t":"얼음","mis":"SC4-2-u4-X54"}],"explanation":["과학자가 하는 일이에요.","더 알아봐야 해요.","연구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_challenge#2','sci',4,2,'u4','L08','g4_2_sci_u4_L08_challenge','lesson_challenge','SC4-2-u4-C36',2,'mc','auto','영구 동토와 빙하는 요즈음 어떻게 되고 있나요?',ARRAY['SC4-2-u4-X51','SC4-2-u4-X52']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C36","difficulty":2,"kind":"mc","stem":"영구 동토와 빙하는 요즈음 어떻게 되고 있나요?","options":[{"t":"기후 변화로 녹고 있다","correct":true},{"t":"점점 더 커지고 있다","mis":"SC4-2-u4-X51"},{"t":"예전과 똑같다","mis":"SC4-2-u4-X51"},{"t":"절대로 녹지 않는다","mis":"SC4-2-u4-X52"}],"explanation":["떠올려요를 읽어요.","기후 변화 때문이에요.","녹고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_challenge#3','sci',4,2,'u4','L08','g4_2_sci_u4_L08_challenge','lesson_challenge','SC4-2-u4-C38',3,'error','auto','알아봐요 카드를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u4-X54','SC4-2-u4-X52','SC4-2-u4-X53']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C38","difficulty":3,"kind":"error","stem":"알아봐요 카드를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「세균이 사회에 미칠 영향은 이미 다 밝혀져서 더 연구할 필요가 없어.」","correct":true,"mis_target":"SC4-2-u4-X54"},{"t":"친구 가 — 「빙하는 지구 환경의 변화를 알 수 있어.」","mis":"SC4-2-u4-X52"},{"t":"친구 다 — 「영구 동토가 녹으면서 묻혀 있던 미생물이 되살아나.」","mis":"SC4-2-u4-X53"}],"explanation":["과학자 카드를 떠올려요.","연구가 더 필요해요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["영구 동토 — 여름에도 얼어 있는 땅","빙하 — 지구 환경의 변화를 알 수 있는 냉동 타임캡슐","과학자 — 빙하에 깊게 구멍을 뚫어 얼음층을 캐낸 뒤 연구해요"],"title":"알아봐요 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_challenge#4','sci',4,2,'u4','L08','g4_2_sci_u4_L08_challenge','lesson_challenge','SC4-2-u4-C37',3,'mc','auto','「녹으면서」 생기는 일끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u4-X53']::text[],false,'{"seq":4,"concept":"SC4-2-u4-C37","difficulty":3,"kind":"mc","stem":"「녹으면서」 생기는 일끼리 묶은 것은 무엇인가요?","options":[{"t":"묻혀 있던 지층이 드러난다, 미생물이 되살아난다","correct":true},{"t":"땅이 여름에도 얼어 있다, 미생물이 얼음 속에 묻혀 있다","mis":"SC4-2-u4-X53"},{"t":"땅이 여름에도 얼어 있다, 지층이 드러난다","mis":"SC4-2-u4-X53"},{"t":"미생물이 얼음 속에 묻혀 있다, 미생물이 되살아난다","mis":"SC4-2-u4-X53"}],"explanation":["녹으면 드러나요.","둘 다 드러나는 일이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_challenge#5','sci',4,2,'u4','L08','g4_2_sci_u4_L08_challenge','lesson_challenge','SC4-2-u4-C39',3,'ox','auto','빙하 이야기는 먼 곳의 일이라 우리 생활과 상관없어요.',ARRAY['SC4-2-u4-X07']::text[],false,'{"seq":5,"concept":"SC4-2-u4-C39","difficulty":3,"kind":"ox","stem":"빙하 이야기는 먼 곳의 일이라 우리 생활과 상관없어요.","answer":"X","reason_options":[{"t":"우리가 기후 변화에 대응하면 영구 동토와 빙하를 지킬 수 있기 때문에","correct":true},{"t":"빙하는 우리가 하는 일과 관계가 없기 때문에","mis":"SC4-2-u4-X07"}],"mis":"SC4-2-u4-X07","explanation":["생각해요를 떠올려요.","우리도 지킬 수 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_challenge#6','sci',4,2,'u4','L08','g4_2_sci_u4_L08_challenge','lesson_challenge','SC4-2-u4-C37',3,'mc','auto','「오래전 묻혔던 지층이 드러났어요.」는 언제 생긴 일인가요?',ARRAY['SC4-2-u4-X53','SC4-2-u4-X51','SC4-2-u4-X52']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C37","difficulty":3,"kind":"mc","stem":"「오래전 묻혔던 지층이 드러났어요.」는 언제 생긴 일인가요?","options":[{"t":"폭염으로 영구 동토가 녹으면서","correct":true},{"t":"영구 동토가 여름에도 꽁꽁 얼어 있을 때","mis":"SC4-2-u4-X53"},{"t":"빙하가 점점 커질 때","mis":"SC4-2-u4-X51"},{"t":"냉동고에 얼음을 넣을 때","mis":"SC4-2-u4-X52"}],"explanation":["드러나는 것은 녹으면서예요.","폭염이 땅을 녹였어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_challenge#7','sci',4,2,'u4','L08','g4_2_sci_u4_L08_challenge','lesson_challenge','SC4-2-u4-C39',3,'mc','auto','빙하 속에 있던 세균이 깨어나지 않도록 우리가 해야 할 일은 무엇일까요?',ARRAY['SC4-2-u4-X08','SC4-2-u4-X55']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C39","difficulty":3,"kind":"mc","stem":"빙하 속에 있던 세균이 깨어나지 않도록 우리가 해야 할 일은 무엇일까요?","options":[{"t":"일회용품 사용을 줄이고 가까운 곳은 걸어서 이동한다","correct":true},{"t":"할 수 있는 일이 없으니 걱정만 한다","mis":"SC4-2-u4-X08"},{"t":"일회용품을 더 많이 사용한다","mis":"SC4-2-u4-X55"},{"t":"가까운 곳도 자동차를 타고 간다","mis":"SC4-2-u4-X55"}],"explanation":["지난 시간의 대응 방법을 떠올려요.","줄이고 걸어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_challenge#8','sci',4,2,'u4','L08','g4_2_sci_u4_L08_challenge','lesson_challenge','SC4-2-u4-C38',4,'mc','auto','친구가 「세균 이야기를 들으니 너무 무서워. 아무것도 할 수 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X08','SC4-2-u4-X54','SC4-2-u4-X07']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C38","difficulty":4,"kind":"mc","stem":"친구가 「세균 이야기를 들으니 너무 무서워. 아무것도 할 수 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「과학자들이 빙하를 연구하고 있고 앞으로 연구가 더 필요해. 우리는 일회용품 줄이기, 걸어서 이동하기로 함께 지킬 수 있어.」","correct":true},{"t":"「맞아, 무섭기만 해.」","mis":"SC4-2-u4-X08"},{"t":"「이미 다 밝혀져서 신경 쓸 것도 없어.」","mis":"SC4-2-u4-X54"},{"t":"「빙하 이야기는 우리랑 상관없어.」","mis":"SC4-2-u4-X07"}],"explanation":["과학자 카드와 생각해요를 떠올려요.","연구하고 지킬 수 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_challenge#9','sci',4,2,'u4','L08','g4_2_sci_u4_L08_challenge','lesson_challenge','SC4-2-u4-C36',4,'mc','auto','친구가 「냉동 타임캡슐이라니까 빙하는 절대 녹지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X52','SC4-2-u4-X51']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C36","difficulty":4,"kind":"mc","stem":"친구가 「냉동 타임캡슐이라니까 빙하는 절대 녹지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「빙하는 지구 환경의 변화를 알 수 있어서 그렇게 불리는 거야. 기후 변화로 빙하는 녹고 있어.」","correct":true},{"t":"「맞아, 빙하는 절대 녹지 않아.」","mis":"SC4-2-u4-X52"},{"t":"「빙하는 사람이 만든 냉동고야.」","mis":"SC4-2-u4-X52"},{"t":"「빙하는 봄마다 모두 녹아.」","mis":"SC4-2-u4-X51"}],"explanation":["냉동 타임캡슐의 뜻을 떠올려요.","변화를 알 수 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_L08_challenge#10','sci',4,2,'u4','L08','g4_2_sci_u4_L08_challenge','lesson_challenge','SC4-2-u4-C37',4,'essay','teacher','영구 동토나 빙하가 녹으면 생기는 일, 과학자가 하는 일, 우리가 할 수 있는 일을 차례로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u4-C37","difficulty":4,"kind":"essay","stem":"영구 동토나 빙하가 녹으면 생기는 일, 과학자가 하는 일, 우리가 할 수 있는 일을 차례로 쓰세요.","answer_guide":{"answer":"예: 기후 변화로 영구 동토나 빙하가 녹으면서 얼음 속에 묻혀 있던 미생물이 되살아나고 세균이 드러날 수 있다. 과학자들은 빙하의 얼음층을 캐내어 연구하며, 세균이 미칠 영향은 앞으로 연구가 더 필요하다. 우리는 일회용품 사용을 줄이고 가까운 곳은 걸어서 이동하며 함께 지킬 수 있다.","scoring_points":["녹으면 생기는 일을 썼는가","과학자가 하는 일을 썼는가","우리가 할 수 있는 일을 썼는가"]},"explanation":["글의 차례를 떠올려요.","셋을 나눠 써요.","우리가 할 일로 마무리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#1','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C3',1,'mc','auto','바다반 일지 ①에서 접을 때마다 줄어든 종이는 무엇을 뜻하나요?',ARRAY['SC4-2-u4-X04','SC4-2-u4-X05']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C3","difficulty":1,"kind":"mc","stem":"바다반 일지 ①에서 접을 때마다 줄어든 종이는 무엇을 뜻하나요?","options":[{"t":"기후 변화로 녹아 작아지는 빙하","correct":true},{"t":"누가 오래 버티는지 겨루는 규칙","mis":"SC4-2-u4-X04"},{"t":"종이를 아끼자는 약속","mis":"SC4-2-u4-X05"},{"t":"종이접기 연습","mis":"SC4-2-u4-X05"}],"explanation":["흰 종이는 빙하예요.","작아졌어요.","녹는 빙하예요."],"asset":{"type":"passage","lines":["모둠 친구 넷이 흰 종이 위에 올라갔다.","신호에 따라 종이를 반으로 접을 때마다 올라설 자리가 줄었다.","세 번 접으니 버티기가 무척 힘들었다.","친구 가 — 「가장 오래 버틴 우리 모둠이 이긴 거야.」"],"title":"바다반 일지 ① 줄어드는 빙하 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#2','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C6',1,'mc','auto','바다반 일지 ②의 그래프에서 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u4-X11']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C6","difficulty":1,"kind":"mc","stem":"바다반 일지 ②의 그래프에서 알 수 있는 것은 무엇인가요?","options":[{"t":"우리나라의 평균 기온이 점차 올라간다","correct":true},{"t":"평균 기온이 점차 낮아진다","mis":"SC4-2-u4-X11"},{"t":"평균 기온이 늘 같다","mis":"SC4-2-u4-X11"},{"t":"그래프로는 기온을 알 수 없다","mis":"SC4-2-u4-X11"}],"explanation":["첫 줄을 읽어요.","올라가요.","첫 번째예요."],"asset":{"type":"passage","lines":["연평균 기온 그래프 — 평균 기온이 점차 올라간다.","폭염 일수와 한파 일수가 예전보다 늘었다.","연간 강수량은 늘고, 가을~봄 강수량은 줄었다.","친구 나 — 「우리나라는 기후 변화와 상관없어.」"],"title":"바다반 일지 ② 기후 변화 현상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#3','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C12',1,'mc','auto','바다반 일지 ③의 ㉠은 무엇을 과도하게 사용하는 모습인가요?',ARRAY['SC4-2-u4-X21']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C12","difficulty":1,"kind":"mc","stem":"바다반 일지 ③의 ㉠은 무엇을 과도하게 사용하는 모습인가요?","options":[{"t":"화석 연료","correct":true},{"t":"친환경 에너지","mis":"SC4-2-u4-X21"},{"t":"빗물","mis":"SC4-2-u4-X21"},{"t":"나무 그늘","mis":"SC4-2-u4-X21"}],"explanation":["승용차를 떠올려요.","연료를 써요.","화석 연료예요."],"asset":{"type":"passage","lines":["㉠ 가까운 거리도 승용차를 타고 간다.","㉡ 일회용 컵을 하루에 여러 개 쓴다.","㉢ 아무도 없는 방의 전등을 끈다.","토의할 때 친구의 의견을 끝까지 들었다."],"title":"바다반 일지 ③ 생활 속 인간의 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#4','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C16',1,'mc','auto','바다반 일지 ④에서 모형에 물을 붓는 것은 무엇을 뜻하나요?',ARRAY['SC4-2-u4-X29','SC4-2-u4-X30','SC4-2-u4-X26']::text[],false,'{"seq":4,"concept":"SC4-2-u4-C16","difficulty":1,"kind":"mc","stem":"바다반 일지 ④에서 모형에 물을 붓는 것은 무엇을 뜻하나요?","options":[{"t":"해수면이 높아지는 것","correct":true},{"t":"육지가 넓어지는 것","mis":"SC4-2-u4-X29"},{"t":"비가 그치는 것","mis":"SC4-2-u4-X30"},{"t":"산이 높아지는 것","mis":"SC4-2-u4-X26"}],"explanation":["물은 바닷물이에요.","높아져요.","해수면 상승이에요."],"asset":{"type":"passage","lines":["색깔 점토로 육지와 섬을 만들고 깃발을 꽂았다.","물을 천천히 부으니 주택가 깃발이 잠겼다.","물을 더 부으니 섬 깃발도 잠겼다.","친구 다 — 「컵 속 얼음이 녹으면 물이 넘칠 거야.」"],"title":"바다반 일지 ④ 해수면 상승 모형실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#5','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C24',1,'mc','auto','바다반 일지 ⑤ 삼각책의 「부족해지는 물」에 알맞은 설명은 무엇인가요?',ARRAY['SC4-2-u4-X38','SC4-2-u4-X35']::text[],false,'{"seq":5,"concept":"SC4-2-u4-C24","difficulty":1,"kind":"mc","stem":"바다반 일지 ⑤ 삼각책의 「부족해지는 물」에 알맞은 설명은 무엇인가요?","options":[{"t":"비가 적게 와서 마실 물이 부족해진다","correct":true},{"t":"온열 질환 환자가 늘어난다","mis":"SC4-2-u4-X38"},{"t":"동물과 식물이 사라진다","mis":"SC4-2-u4-X38"},{"t":"비가 많이 와 물이 넘쳐 난다","mis":"SC4-2-u4-X35"}],"explanation":["둘째 줄을 읽어요.","마실 물이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["우리 모둠 삼각책 — 「부족해지는 물」","비가 적게 와서 마실 물이 부족한 곳이 늘어난다.","폭염으로 열사병 환자가 늘어난다는 것도 알았다.","공공 사이트에서 조사하고 출처를 적었다."],"title":"바다반 일지 ⑤ 삼각책 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#6','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C27',1,'mc','auto','바다반 일지 ⑥ 친구 가의 말을 바르게 고친 것은 무엇인가요?',ARRAY['SC4-2-u4-X41','SC4-2-u4-X42']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C27","difficulty":1,"kind":"mc","stem":"바다반 일지 ⑥ 친구 가의 말을 바르게 고친 것은 무엇인가요?","options":[{"t":"대응은 국가와 사회, 과학자, 사람들이 함께 할 수 있다","correct":true},{"t":"대응은 나라에서만 할 수 있다","mis":"SC4-2-u4-X41"},{"t":"대응은 나 혼자서만 하면 된다","mis":"SC4-2-u4-X41"},{"t":"대응은 과학자만 할 수 있다","mis":"SC4-2-u4-X42"}],"explanation":["일지의 세 줄을 읽어요.","세 무리가 있어요.","함께해요."],"asset":{"type":"passage","lines":["국가와 사회 — 숲을 되살리고 법과 제도를 만든다.","과학자 — 기후 변화에 강한 씨앗을 연구한다.","우리 반 — 급식을 먹을 만큼만 받는다.","친구 가 — 「대응은 나라에서만 할 수 있어.」"],"title":"바다반 일지 ⑥ 대응 방법 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#7','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C34',1,'mc','auto','바다반 일지 ⑦ 친구 나의 말을 바르게 고친 것은 무엇인가요?',ARRAY['SC4-2-u4-X48','SC4-2-u4-X49']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C34","difficulty":1,"kind":"mc","stem":"바다반 일지 ⑦ 친구 나의 말을 바르게 고친 것은 무엇인가요?","options":[{"t":"매일 꾸준히 실천하는 것이 중요하다","correct":true},{"t":"딱 하루만 하면 충분하다","mis":"SC4-2-u4-X48"},{"t":"내일부터 하면 된다","mis":"SC4-2-u4-X49"},{"t":"계획표만 만들면 된다","mis":"SC4-2-u4-X49"}],"explanation":["셋째 줄을 읽어요.","매일 표시해요.","첫 번째예요."],"asset":{"type":"passage","lines":["목표 — 물을 아끼자!","실천 내용 — 양치할 때 컵에 물을 받아서 하기","방법 — 점검표를 만들어 매일 표시하기","친구 나 — 「딱 하루만 하면 충분해.」"],"title":"바다반 일지 ⑦ 나의 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#8','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C36',1,'mc','auto','바다반 일지 ⑧의 영구 동토는 어떤 땅인가요?',ARRAY['SC4-2-u4-X51']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C36","difficulty":1,"kind":"mc","stem":"바다반 일지 ⑧의 영구 동토는 어떤 땅인가요?","options":[{"t":"여름에도 얼어 있는 땅","correct":true},{"t":"봄이면 모두 녹는 땅","mis":"SC4-2-u4-X51"},{"t":"뜨거운 모래 땅","mis":"SC4-2-u4-X51"},{"t":"바닷물에 잠긴 땅","mis":"SC4-2-u4-X51"}],"explanation":["첫 줄을 읽어요.","여름에도 얼어요.","첫 번째예요."],"asset":{"type":"passage","lines":["영구 동토 — 여름에도 얼어 있는 땅","기후 변화로 녹으면서 묻혀 있던 미생물이 되살아난다.","과학자들은 빙하의 얼음층을 캐내어 연구한다.","친구 다 — 「세균 이야기는 이미 다 밝혀졌대.」"],"title":"바다반 일지 ⑧ 빙하 속 세균"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#9','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C1',2,'blank','auto','「요즈음 북극은 많이 춥지 않고 (    )의 크기도 많이 작아졌어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u4-X01']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C1","difficulty":2,"kind":"blank","stem":"「요즈음 북극은 많이 춥지 않고 (    )의 크기도 많이 작아졌어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"빙하","correct":true},{"t":"사막","mis":"SC4-2-u4-X01"},{"t":"섬","mis":"SC4-2-u4-X01"},{"t":"바다","mis":"SC4-2-u4-X01"}],"explanation":["북극곰이 뛰어놀던 곳이에요.","얼음덩어리예요.","빙하예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#10','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C8',2,'match','auto','날씨가 달라질 때 생길 수 있는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u4-C8","difficulty":2,"kind":"match","stem":"날씨가 달라질 때 생길 수 있는 일을 알맞게 이으세요.","pairs":[{"l":"강수량이 급격히 늘어나요","r":"기습 폭우로 인한 홍수"},{"l":"강수량이 급격히 줄어들어요","r":"극심한 가뭄"},{"l":"여름 기온이 크게 올라요","r":"장기간 폭염"},{"l":"겨울 기온이 크게 떨어져요","r":"강한 한파"}],"mis":"SC4-2-u4-X13","explanation":["비가 많고 적음을 봐요.","덥고 추움을 봐요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#11','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C14',2,'error','auto','바다반 일지 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u4-X19','SC4-2-u4-X21','SC4-2-u4-X22']::text[],false,'{"seq":11,"concept":"SC4-2-u4-C14","difficulty":2,"kind":"error","stem":"바다반 일지 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「㉢도 기후 변화를 심각하게 만드는 활동이야.」","correct":true,"mis_target":"SC4-2-u4-X19"},{"t":"친구 가 — 「㉠은 화석 연료를 많이 쓰는 거야.」","mis":"SC4-2-u4-X21"},{"t":"친구 나 — 「㉡은 쓰레기를 많이 만들어.」","mis":"SC4-2-u4-X22"}],"explanation":["㉢을 읽어요.","전등을 끄는 건 돕는 일이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 가까운 거리도 승용차를 타고 간다.","㉡ 일회용 컵을 하루에 여러 개 쓴다.","㉢ 아무도 없는 방의 전등을 끈다.","토의할 때 친구의 의견을 끝까지 들었다."],"title":"바다반 일지 ③ 생활 속 인간의 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#12','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C20',2,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SC4-2-u4-C20","difficulty":2,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"빙하","r":"육지를 덮고 있는 얼음덩어리"},{"l":"빙산","r":"빙하에서 떨어져 나와 물에 떠 있는 얼음덩어리"},{"l":"해수면 상승","r":"바닷물의 높이가 높아지는 현상"},{"l":"사막화","r":"비가 적게 와 사막이 늘어나는 것"}],"mis":"SC4-2-u4-X32","explanation":["얼음덩어리가 어디에 있나요?","육지와 물을 나눠요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#13','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C24',2,'error','auto','바다반 일지 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u4-X37','SC4-2-u4-X38','SC4-2-u4-X25']::text[],false,'{"seq":13,"concept":"SC4-2-u4-C24","difficulty":2,"kind":"error","stem":"바다반 일지 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「폭염이 심해지면 열사병 환자가 줄어들어.」","correct":true,"mis_target":"SC4-2-u4-X37"},{"t":"친구 가 — 「비가 적게 오면 마실 물이 부족해져.」","mis":"SC4-2-u4-X38"},{"t":"친구 다 — 「공공 사이트에서 찾고 출처를 적었어.」","mis":"SC4-2-u4-X25"}],"explanation":["셋째 줄을 읽어요.","늘어나요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["우리 모둠 삼각책 — 「부족해지는 물」","비가 적게 와서 마실 물이 부족한 곳이 늘어난다.","폭염으로 열사병 환자가 늘어난다는 것도 알았다.","공공 사이트에서 조사하고 출처를 적었다."],"title":"바다반 일지 ⑤ 삼각책 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#14','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C31',2,'error','auto','바다반 일지 ⑥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u4-X41','SC4-2-u4-X44','SC4-2-u4-X43']::text[],false,'{"seq":14,"concept":"SC4-2-u4-C31","difficulty":2,"kind":"error","stem":"바다반 일지 ⑥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「대응은 나라에서만 할 수 있어.」","correct":true,"mis_target":"SC4-2-u4-X41"},{"t":"친구 나 — 「급식을 먹을 만큼만 받는 것도 대응이야.」","mis":"SC4-2-u4-X44"},{"t":"친구 다 — 「과학자는 강한 씨앗을 연구해.」","mis":"SC4-2-u4-X43"}],"explanation":["셋째 줄을 읽어요.","우리 반도 해요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["국가와 사회 — 숲을 되살리고 법과 제도를 만든다.","과학자 — 기후 변화에 강한 씨앗을 연구한다.","우리 반 — 급식을 먹을 만큼만 받는다.","친구 가 — 「대응은 나라에서만 할 수 있어.」"],"title":"바다반 일지 ⑥ 대응 방법 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#15','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C34',2,'error','auto','바다반 일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u4-X48','SC4-2-u4-X49','SC4-2-u4-X47']::text[],false,'{"seq":15,"concept":"SC4-2-u4-C34","difficulty":2,"kind":"error","stem":"바다반 일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「딱 하루만 하면 충분해.」","correct":true,"mis_target":"SC4-2-u4-X48"},{"t":"친구 가 — 「점검표에 매일 표시하면 꾸준히 할 수 있어.」","mis":"SC4-2-u4-X49"},{"t":"친구 다 — 「물을 아끼자는 목표와 양치 컵이 이어져.」","mis":"SC4-2-u4-X47"}],"explanation":["넷째 줄을 읽어요.","꾸준히 해야 해요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["목표 — 물을 아끼자!","실천 내용 — 양치할 때 컵에 물을 받아서 하기","방법 — 점검표를 만들어 매일 표시하기","친구 나 — 「딱 하루만 하면 충분해.」"],"title":"바다반 일지 ⑦ 나의 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
