INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#17','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C8',3,'error','auto','바다반 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u4-X13','SC4-2-u4-X14','SC4-2-u4-X11']::text[],false,'{"seq":17,"concept":"SC4-2-u4-C8","difficulty":3,"kind":"error","stem":"바다반 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「가을~봄 강수량이 줄었으니 홍수가 심해질 거야.」","correct":true,"mis_target":"SC4-2-u4-X13"},{"t":"친구 가 — 「연간 강수량이 늘어 홍수가 심해질 수 있어.」","mis":"SC4-2-u4-X14"},{"t":"친구 나 — 「평균 기온이 점차 오르고 있어.」","mis":"SC4-2-u4-X11"}],"explanation":["셋째 줄을 읽어요.","줄면 가뭄이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["연평균 기온 그래프 — 평균 기온이 점차 올라간다.","폭염 일수와 한파 일수가 예전보다 늘었다.","연간 강수량은 늘고, 가을~봄 강수량은 줄었다.","친구 나 — 「우리나라는 기후 변화와 상관없어.」"],"title":"바다반 일지 ② 기후 변화 현상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#18','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C14',3,'mc','auto','바다반 일지 ③의 ㉠~㉢ 가운데 기후 변화를 심각하게 만드는 활동을 바르게 고른 것은 무엇인가요?',ARRAY['SC4-2-u4-X19','SC4-2-u4-X18']::text[],false,'{"seq":18,"concept":"SC4-2-u4-C14","difficulty":3,"kind":"mc","stem":"바다반 일지 ③의 ㉠~㉢ 가운데 기후 변화를 심각하게 만드는 활동을 바르게 고른 것은 무엇인가요?","options":[{"t":"㉠, ㉡","correct":true},{"t":"㉠, ㉢","mis":"SC4-2-u4-X19"},{"t":"㉡, ㉢","mis":"SC4-2-u4-X19"},{"t":"㉠, ㉡, ㉢","mis":"SC4-2-u4-X18"}],"explanation":["하나씩 따져요.","㉢은 돕는 일이에요.","㉠과 ㉡이에요."],"asset":{"type":"passage","lines":["㉠ 가까운 거리도 승용차를 타고 간다.","㉡ 일회용 컵을 하루에 여러 개 쓴다.","㉢ 아무도 없는 방의 전등을 끈다.","토의할 때 친구의 의견을 끝까지 들었다."],"title":"바다반 일지 ③ 생활 속 인간의 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#19','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C20',3,'mc','auto','바다반 일지 ④ 친구 다의 말을 바르게 고친 것은 무엇인가요?',ARRAY['SC4-2-u4-X32']::text[],false,'{"seq":19,"concept":"SC4-2-u4-C20","difficulty":3,"kind":"mc","stem":"바다반 일지 ④ 친구 다의 말을 바르게 고친 것은 무엇인가요?","options":[{"t":"컵 속 얼음이 녹아도 물의 높이는 변하지 않아","correct":true},{"t":"컵 속 얼음이 녹으면 물이 넘쳐","mis":"SC4-2-u4-X32"},{"t":"빙산이 녹으면 해수면이 크게 올라가","mis":"SC4-2-u4-X32"},{"t":"얼음은 녹아도 물이 되지 않아","mis":"SC4-2-u4-X32"}],"explanation":["넷째 줄을 읽어요.","떠 있는 얼음이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["색깔 점토로 육지와 섬을 만들고 깃발을 꽂았다.","물을 천천히 부으니 주택가 깃발이 잠겼다.","물을 더 부으니 섬 깃발도 잠겼다.","친구 다 — 「컵 속 얼음이 녹으면 물이 넘칠 거야.」"],"title":"바다반 일지 ④ 해수면 상승 모형실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#20','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C26',3,'mc','auto','바다반 일지 ⑤의 모둠이 다음에 할 일로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u4-X40','SC4-2-u4-X25']::text[],false,'{"seq":20,"concept":"SC4-2-u4-C26","difficulty":3,"kind":"mc","stem":"바다반 일지 ⑤의 모둠이 다음에 할 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"완성한 삼각책으로 조사한 영향을 친구들에게 설명한다","correct":true},{"t":"삼각책을 더 예쁘게 꾸미기만 한다","mis":"SC4-2-u4-X40"},{"t":"적어 둔 출처를 지운다","mis":"SC4-2-u4-X25"},{"t":"다른 모둠의 설명은 듣지 않는다","mis":"SC4-2-u4-X40"}],"explanation":["삼각책을 만든 까닭을 떠올려요.","설명해요.","첫 번째예요."],"asset":{"type":"passage","lines":["우리 모둠 삼각책 — 「부족해지는 물」","비가 적게 와서 마실 물이 부족한 곳이 늘어난다.","폭염으로 열사병 환자가 늘어난다는 것도 알았다.","공공 사이트에서 조사하고 출처를 적었다."],"title":"바다반 일지 ⑤ 삼각책 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#21','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C28',3,'mc','auto','바다반 일지 ⑥의 노력을 누가 하는지 바르게 나눈 것은 무엇인가요?',ARRAY['SC4-2-u4-X42','SC4-2-u4-X41']::text[],false,'{"seq":21,"concept":"SC4-2-u4-C28","difficulty":3,"kind":"mc","stem":"바다반 일지 ⑥의 노력을 누가 하는지 바르게 나눈 것은 무엇인가요?","options":[{"t":"숲 되살리기·법과 제도 — 국가와 사회 / 씨앗 연구 — 과학자 / 급식 먹을 만큼 받기 — 우리 반","correct":true},{"t":"숲 되살리기 — 과학자 / 씨앗 연구 — 우리 반 / 급식 — 국가와 사회","mis":"SC4-2-u4-X42"},{"t":"모두 국가와 사회의 노력","mis":"SC4-2-u4-X41"},{"t":"모두 우리 반만의 노력","mis":"SC4-2-u4-X41"}],"explanation":["일지 세 줄을 읽어요.","줄마다 주인이 있어요.","첫 번째예요."],"asset":{"type":"passage","lines":["국가와 사회 — 숲을 되살리고 법과 제도를 만든다.","과학자 — 기후 변화에 강한 씨앗을 연구한다.","우리 반 — 급식을 먹을 만큼만 받는다.","친구 가 — 「대응은 나라에서만 할 수 있어.」"],"title":"바다반 일지 ⑥ 대응 방법 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#22','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C33',3,'mc','auto','바다반 일지 ⑦의 계획에서 「실천 내용」은 무엇인가요?',ARRAY['SC4-2-u4-X47','SC4-2-u4-X48']::text[],false,'{"seq":22,"concept":"SC4-2-u4-C33","difficulty":3,"kind":"mc","stem":"바다반 일지 ⑦의 계획에서 「실천 내용」은 무엇인가요?","options":[{"t":"양치할 때 컵에 물을 받아서 하기","correct":true},{"t":"물을 아끼자!","mis":"SC4-2-u4-X47"},{"t":"점검표를 만들어 매일 표시하기","mis":"SC4-2-u4-X47"},{"t":"딱 하루만 하기","mis":"SC4-2-u4-X48"}],"explanation":["칸 이름을 봐요.","날마다 할 일이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["목표 — 물을 아끼자!","실천 내용 — 양치할 때 컵에 물을 받아서 하기","방법 — 점검표를 만들어 매일 표시하기","친구 나 — 「딱 하루만 하면 충분해.」"],"title":"바다반 일지 ⑦ 나의 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#23','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C9',4,'essay','teacher','바다반 일지 ②를 보고 우리나라의 기후가 어떻게 변하고 있는지 두 가지 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC4-2-u4-C9","difficulty":4,"kind":"essay","stem":"바다반 일지 ②를 보고 우리나라의 기후가 어떻게 변하고 있는지 두 가지 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 우리나라의 평균 기온이 점차 올라가고, 폭염 일수와 한파 일수가 늘었다. 연간 강수량은 늘고 가을~봄 강수량은 줄어 홍수와 가뭄이 심해질 수 있다. 우리나라도 기후 변화와 상관있으며, 폭염, 한파, 가뭄, 홍수, 폭설이 더 크고 자주 일어나고 있다.","scoring_points":["변화 하나를 썼는가","변화 또 하나를 썼는가","친구 나의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","두 가지를 골라요.","고쳐 써요."],"asset":{"type":"passage","lines":["연평균 기온 그래프 — 평균 기온이 점차 올라간다.","폭염 일수와 한파 일수가 예전보다 늘었다.","연간 강수량은 늘고, 가을~봄 강수량은 줄었다.","친구 나 — 「우리나라는 기후 변화와 상관없어.」"],"title":"바다반 일지 ② 기후 변화 현상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#24','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C3',4,'mc','auto','친구가 「줄어드는 빙하 놀이는 가장 오래 버틴 모둠을 가리는 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X04','SC4-2-u4-X05','SC4-2-u4-X07']::text[],false,'{"seq":24,"concept":"SC4-2-u4-C3","difficulty":4,"kind":"mc","stem":"친구가 「줄어드는 빙하 놀이는 가장 오래 버틴 모둠을 가리는 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「누가 이기는지가 아니라, 작아지는 종이로 녹아 줄어드는 빙하와 북극곰의 어려움을 느껴 보는 놀이야.」","correct":true},{"t":"「맞아, 이긴 모둠이 최고야.」","mis":"SC4-2-u4-X04"},{"t":"「종이를 아끼는 놀이야.」","mis":"SC4-2-u4-X05"},{"t":"「북극곰 일은 우리랑 상관없어.」","mis":"SC4-2-u4-X07"}],"explanation":["흰 종이의 뜻을 떠올려요.","작아지는 빙하예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_a#25','sci',4,2,'u4','','g4_2_sci_u4_review_a','unit_review','SC4-2-u4-C31',4,'essay','teacher','생활 속에서 실천할 수 있는 기후 변화 대응 방법 두 가지를 찾아 그 까닭과 함께 소개하는 글을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-2-u4-C31","difficulty":4,"kind":"essay","stem":"생활 속에서 실천할 수 있는 기후 변화 대응 방법 두 가지를 찾아 그 까닭과 함께 소개하는 글을 쓰세요.","answer_guide":{"answer":"예: 음식을 배달시켜 먹을 때 일회용 숟가락과 젓가락을 받지 않는다. 쓰레기를 줄일 수 있기 때문이다. 양치할 때 컵에 물을 받아서 한다. 물을 절약할 수 있기 때문이다.","scoring_points":["대응 방법 두 가지를 썼는가","방법마다 까닭을 썼는가","방법과 까닭이 바르게 이어졌는가"]},"explanation":["생활을 떠올려요.","방법을 골라요.","까닭을 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#1','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C2',1,'ox','auto','바다반 일지 ①처럼 종이를 접을 때에는 신호에 따라 접어요.',ARRAY['SC4-2-u4-X03']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C2","difficulty":1,"kind":"ox","stem":"바다반 일지 ①처럼 종이를 접을 때에는 신호에 따라 접어요.","answer":"O","reason_options":[{"t":"신호를 듣고 함께 접어야 안전하고 놀이 차례를 지킬 수 있기 때문에","correct":true},{"t":"빨리 접는 모둠이 이기기 때문에","mis":"SC4-2-u4-X03"}],"mis":"SC4-2-u4-X03","explanation":["둘째 줄을 읽어요.","신호에 따라요.","그래서 O예요."],"asset":{"type":"passage","lines":["모둠 친구 넷이 흰 종이 위에 올라갔다.","신호에 따라 종이를 반으로 접을 때마다 올라설 자리가 줄었다.","세 번 접으니 버티기가 무척 힘들었다.","친구 가 — 「가장 오래 버틴 우리 모둠이 이긴 거야.」"],"title":"바다반 일지 ① 줄어드는 빙하 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#2','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C5',1,'ox','auto','바다반 일지 ② 친구 나의 말처럼 우리나라는 기후 변화와 상관없어요.',ARRAY['SC4-2-u4-X09']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C5","difficulty":1,"kind":"ox","stem":"바다반 일지 ② 친구 나의 말처럼 우리나라는 기후 변화와 상관없어요.","answer":"X","reason_options":[{"t":"우리나라에서도 폭염, 한파, 가뭄, 홍수, 폭설이 일어나기 때문에","correct":true},{"t":"기후 변화는 다른 나라에서만 일어나기 때문에","mis":"SC4-2-u4-X09"}],"mis":"SC4-2-u4-X09","explanation":["둘째와 셋째 줄을 읽어요.","우리나라 이야기예요.","그래서 X예요."],"asset":{"type":"passage","lines":["연평균 기온 그래프 — 평균 기온이 점차 올라간다.","폭염 일수와 한파 일수가 예전보다 늘었다.","연간 강수량은 늘고, 가을~봄 강수량은 줄었다.","친구 나 — 「우리나라는 기후 변화와 상관없어.」"],"title":"바다반 일지 ② 기후 변화 현상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#3','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C15',1,'ox','auto','바다반 일지 ③처럼 토의할 때 친구의 의견을 끝까지 들어요.',ARRAY['SC4-2-u4-X24']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C15","difficulty":1,"kind":"ox","stem":"바다반 일지 ③처럼 토의할 때 친구의 의견을 끝까지 들어요.","answer":"O","reason_options":[{"t":"다른 사람의 의견을 주의 깊게 들어야 함께 생각을 모을 수 있기 때문에","correct":true},{"t":"내 의견만 말하면 되기 때문에","mis":"SC4-2-u4-X24"}],"mis":"SC4-2-u4-X24","explanation":["넷째 줄을 읽어요.","끝까지 들었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 가까운 거리도 승용차를 타고 간다.","㉡ 일회용 컵을 하루에 여러 개 쓴다.","㉢ 아무도 없는 방의 전등을 끈다.","토의할 때 친구의 의견을 끝까지 들었다."],"title":"바다반 일지 ③ 생활 속 인간의 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#4','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C17',1,'ox','auto','모형실험에서 물은 한꺼번에 쏟아부어요.',ARRAY['SC4-2-u4-X28']::text[],false,'{"seq":4,"concept":"SC4-2-u4-C17","difficulty":1,"kind":"ox","stem":"모형실험에서 물은 한꺼번에 쏟아부어요.","answer":"X","reason_options":[{"t":"물을 흘리지 않도록 천천히 부어야 하기 때문에","correct":true},{"t":"빨리 부어야 결과를 정확히 볼 수 있기 때문에","mis":"SC4-2-u4-X28"}],"mis":"SC4-2-u4-X28","explanation":["둘째 줄을 읽어요.","천천히 부었어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#5','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C26',1,'ox','auto','바다반 일지 ⑤처럼 조사할 때에는 공공 사이트에서 찾고 출처를 적어요.',ARRAY['SC4-2-u4-X25']::text[],false,'{"seq":5,"concept":"SC4-2-u4-C26","difficulty":1,"kind":"ox","stem":"바다반 일지 ⑤처럼 조사할 때에는 공공 사이트에서 찾고 출처를 적어요.","answer":"O","reason_options":[{"t":"신뢰할 수 있는 정보를 찾고 옳은 정보와 거짓 정보를 구분하기 위해서","correct":true},{"t":"누리망 정보는 모두 옳기 때문에","mis":"SC4-2-u4-X25"}],"mis":"SC4-2-u4-X25","explanation":["넷째 줄을 읽어요.","출처를 적었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["우리 모둠 삼각책 — 「부족해지는 물」","비가 적게 와서 마실 물이 부족한 곳이 늘어난다.","폭염으로 열사병 환자가 늘어난다는 것도 알았다.","공공 사이트에서 조사하고 출처를 적었다."],"title":"바다반 일지 ⑤ 삼각책 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#6','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C31',1,'ox','auto','급식을 먹을 만큼만 받는 것은 기후 변화 대응 방법이에요.',ARRAY['SC4-2-u4-X44']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C31","difficulty":1,"kind":"ox","stem":"급식을 먹을 만큼만 받는 것은 기후 변화 대응 방법이에요.","answer":"O","reason_options":[{"t":"음식물 쓰레기를 줄일 수 있기 때문에","correct":true},{"t":"급식은 기후 변화와 관계가 없기 때문에","mis":"SC4-2-u4-X44"}],"mis":"SC4-2-u4-X44","explanation":["남기지 않아요.","쓰레기가 줄어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#7','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C33',1,'ox','auto','바다반 일지 ⑦의 계획은 목표와 실천 내용이 서로 이어져 있어요.',ARRAY['SC4-2-u4-X48']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C33","difficulty":1,"kind":"ox","stem":"바다반 일지 ⑦의 계획은 목표와 실천 내용이 서로 이어져 있어요.","answer":"O","reason_options":[{"t":"물을 아끼자는 목표와 컵에 물을 받아 양치하는 실천이 이어지기 때문에","correct":true},{"t":"목표와 실천 내용은 서로 관계없어도 되기 때문에","mis":"SC4-2-u4-X48"}],"mis":"SC4-2-u4-X48","explanation":["첫째와 둘째 줄을 견줘요.","둘 다 물이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["목표 — 물을 아끼자!","실천 내용 — 양치할 때 컵에 물을 받아서 하기","방법 — 점검표를 만들어 매일 표시하기","친구 나 — 「딱 하루만 하면 충분해.」"],"title":"바다반 일지 ⑦ 나의 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#8','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C38',1,'ox','auto','바다반 일지 ⑧ 친구 다의 말처럼 세균 이야기는 이미 다 밝혀졌어요.',ARRAY['SC4-2-u4-X54']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C38","difficulty":1,"kind":"ox","stem":"바다반 일지 ⑧ 친구 다의 말처럼 세균 이야기는 이미 다 밝혀졌어요.","answer":"X","reason_options":[{"t":"세균이 우리 사회에 미칠 영향은 앞으로 연구가 더 필요하기 때문에","correct":true},{"t":"과학자들이 이미 모든 것을 알아냈기 때문에","mis":"SC4-2-u4-X54"}],"mis":"SC4-2-u4-X54","explanation":["셋째 줄을 읽어요.","연구하고 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["영구 동토 — 여름에도 얼어 있는 땅","기후 변화로 녹으면서 묻혀 있던 미생물이 되살아난다.","과학자들은 빙하의 얼음층을 캐내어 연구한다.","친구 다 — 「세균 이야기는 이미 다 밝혀졌대.」"],"title":"바다반 일지 ⑧ 빙하 속 세균"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#9','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C3',2,'mc','auto','세 번 접은 종이 위에서 모둠 친구 넷이 버티기 힘든 모습은 무엇을 나타내나요?',ARRAY['SC4-2-u4-X04','SC4-2-u4-X02','SC4-2-u4-X06']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C3","difficulty":2,"kind":"mc","stem":"세 번 접은 종이 위에서 모둠 친구 넷이 버티기 힘든 모습은 무엇을 나타내나요?","options":[{"t":"북극곰이 북극에서 살기가 어려워지는 모습","correct":true},{"t":"북극곰이 놀이에서 이기는 모습","mis":"SC4-2-u4-X04"},{"t":"북극곰이 이사를 가는 모습","mis":"SC4-2-u4-X02"},{"t":"빙하가 커지는 모습","mis":"SC4-2-u4-X06"}],"explanation":["자리가 줄었어요.","버티기 힘들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#10','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C7',2,'error','auto','기후 변화 현상 카드를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u4-X12','SC4-2-u4-X14','SC4-2-u4-X13']::text[],false,'{"seq":10,"concept":"SC4-2-u4-C7","difficulty":2,"kind":"error","stem":"기후 변화 현상 카드를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「폭염은 영하 12 ℃ 이하로 떨어지는 날씨야.」","correct":true,"mis_target":"SC4-2-u4-X12"},{"t":"친구 가 — 「폭염 일수가 예전보다 늘었어.」","mis":"SC4-2-u4-X14"},{"t":"친구 나 — 「연간 강수량이 늘어 홍수가 심해질 수 있어.」","mis":"SC4-2-u4-X13"}],"explanation":["폭염의 뜻을 떠올려요.","아주 더운 날씨예요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#11','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C11',2,'mc','auto','건물을 짓기 위해 나무를 베는 것은 어떤 인간의 활동인가요?',ARRAY['SC4-2-u4-X20','SC4-2-u4-X19']::text[],false,'{"seq":11,"concept":"SC4-2-u4-C11","difficulty":2,"kind":"mc","stem":"건물을 짓기 위해 나무를 베는 것은 어떤 인간의 활동인가요?","options":[{"t":"숲 파괴","correct":true},{"t":"화석 연료 사용","mis":"SC4-2-u4-X20"},{"t":"에너지 절약","mis":"SC4-2-u4-X19"},{"t":"쓰레기 줄이기","mis":"SC4-2-u4-X20"}],"explanation":["나무를 베어요.","숲이 사라져요.","숲 파괴예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#12','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C20',2,'error','auto','바다반 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u4-X32','SC4-2-u4-X31','SC4-2-u4-X30']::text[],false,'{"seq":12,"concept":"SC4-2-u4-C20","difficulty":2,"kind":"error","stem":"바다반 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「컵 속 얼음이 녹으면 물이 넘칠 거야.」","correct":true,"mis_target":"SC4-2-u4-X32"},{"t":"친구 가 — 「물을 부으니 주택가 깃발이 잠겼어.」","mis":"SC4-2-u4-X31"},{"t":"친구 나 — 「물을 붓는 건 해수면이 높아지는 걸 뜻해.」","mis":"SC4-2-u4-X30"}],"explanation":["컵 속 얼음을 떠올려요.","물의 높이는 그대로예요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["색깔 점토로 육지와 섬을 만들고 깃발을 꽂았다.","물을 천천히 부으니 주택가 깃발이 잠겼다.","물을 더 부으니 섬 깃발도 잠겼다.","친구 다 — 「컵 속 얼음이 녹으면 물이 넘칠 거야.」"],"title":"바다반 일지 ④ 해수면 상승 모형실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#13','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C22',2,'mc','auto','기후 변화로 「환경이 달라진」 모습은 무엇인가요?',ARRAY['SC4-2-u4-X36']::text[],false,'{"seq":13,"concept":"SC4-2-u4-C22","difficulty":2,"kind":"mc","stem":"기후 변화로 「환경이 달라진」 모습은 무엇인가요?","options":[{"t":"육지와 바다에 사는 많은 동물과 식물들이 사라진다","correct":true},{"t":"폭염으로 야외 활동을 할 수 없다","mis":"SC4-2-u4-X36"},{"t":"한파로 외출을 할 수 없다","mis":"SC4-2-u4-X36"},{"t":"폭설로 자동차를 이용할 수 없다","mis":"SC4-2-u4-X36"}],"explanation":["생활과 환경을 나눠요.","동물과 식물이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#14','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C28',2,'mc','auto','법과 제도를 만들어 기후 변화에 대응하는 것은 누구인가요?',ARRAY['SC4-2-u4-X42','SC4-2-u4-X41']::text[],false,'{"seq":14,"concept":"SC4-2-u4-C28","difficulty":2,"kind":"mc","stem":"법과 제도를 만들어 기후 변화에 대응하는 것은 누구인가요?","options":[{"t":"국가와 사회","correct":true},{"t":"과학자","mis":"SC4-2-u4-X42"},{"t":"사람들 한 명 한 명","mis":"SC4-2-u4-X42"},{"t":"아무도 하지 않는다","mis":"SC4-2-u4-X41"}],"explanation":["규칙을 만드는 곳이에요.","나라예요.","국가와 사회예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#15','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C33',2,'mc','auto','계획표의 「목표를 효과적으로 달성할 수 있는 방법」에 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u4-X47','SC4-2-u4-X49']::text[],false,'{"seq":15,"concept":"SC4-2-u4-C33","difficulty":2,"kind":"mc","stem":"계획표의 「목표를 효과적으로 달성할 수 있는 방법」에 알맞은 것은 무엇인가요?","options":[{"t":"점검표를 만들어 매일 실천하고 점검한다","correct":true},{"t":"일회용품을 자주 사용한다","mis":"SC4-2-u4-X47"},{"t":"생활 속 에너지를 절약하자!","mis":"SC4-2-u4-X47"},{"t":"내일부터 하기로 미룬다","mis":"SC4-2-u4-X49"}],"explanation":["칸 이름을 읽어요.","목표를 이루는 방법이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#16','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C36',2,'match','auto','빙하 이야기의 낱말과 설명을 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"SC4-2-u4-C36","difficulty":2,"kind":"match","stem":"빙하 이야기의 낱말과 설명을 알맞게 이으세요.","pairs":[{"l":"영구 동토","r":"여름에도 얼어 있는 땅"},{"l":"빙하","r":"냉동 타임캡슐이라고 불려요"},{"l":"얼음층","r":"과학자가 캐내어 연구해요"},{"l":"미생물","r":"녹으면서 되살아나요"}],"mis":"SC4-2-u4-X52","explanation":["카드를 떠올려요.","뜻을 찾아요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#17','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C7',3,'mc','auto','바다반 일지 ②에서 「기온」과 관계있는 변화만 고른 것은 무엇인가요?',ARRAY['SC4-2-u4-X15','SC4-2-u4-X14']::text[],false,'{"seq":17,"concept":"SC4-2-u4-C7","difficulty":3,"kind":"mc","stem":"바다반 일지 ②에서 「기온」과 관계있는 변화만 고른 것은 무엇인가요?","options":[{"t":"평균 기온이 오름, 폭염 일수가 늘어남, 한파 일수가 늘어남","correct":true},{"t":"연간 강수량이 늘어남, 가을~봄 강수량이 줄어듦","mis":"SC4-2-u4-X15"},{"t":"평균 기온이 오름, 연간 강수량이 늘어남","mis":"SC4-2-u4-X15"},{"t":"한파 일수가 줄어듦, 폭염 일수가 줄어듦","mis":"SC4-2-u4-X14"}],"explanation":["덥고 추운 것만 골라요.","강수량은 빼요.","첫 번째예요."],"asset":{"type":"passage","lines":["연평균 기온 그래프 — 평균 기온이 점차 올라간다.","폭염 일수와 한파 일수가 예전보다 늘었다.","연간 강수량은 늘고, 가을~봄 강수량은 줄었다.","친구 나 — 「우리나라는 기후 변화와 상관없어.」"],"title":"바다반 일지 ② 기후 변화 현상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#18','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C12',3,'mc','auto','바다반 일지 ③의 ㉠을 바꾸는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u4-X21']::text[],false,'{"seq":18,"concept":"SC4-2-u4-C12","difficulty":3,"kind":"mc","stem":"바다반 일지 ③의 ㉠을 바꾸는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"가까운 거리는 걸어서 간다","correct":true},{"t":"더 큰 승용차를 탄다","mis":"SC4-2-u4-X21"},{"t":"가까운 거리도 늘 승용차를 탄다","mis":"SC4-2-u4-X21"},{"t":"승용차를 켜 둔 채 기다린다","mis":"SC4-2-u4-X21"}],"explanation":["㉠을 읽어요.","연료를 덜 써요.","첫 번째예요."],"asset":{"type":"passage","lines":["㉠ 가까운 거리도 승용차를 타고 간다.","㉡ 일회용 컵을 하루에 여러 개 쓴다.","㉢ 아무도 없는 방의 전등을 끈다.","토의할 때 친구의 의견을 끝까지 들었다."],"title":"바다반 일지 ③ 생활 속 인간의 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#19','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C18',3,'mc','auto','바다반 일지 ④에서 「섬 깃발도 잠겼다」는 무엇을 뜻하나요?',ARRAY['SC4-2-u4-X29','SC4-2-u4-X34','SC4-2-u4-X30']::text[],false,'{"seq":19,"concept":"SC4-2-u4-C18","difficulty":3,"kind":"mc","stem":"바다반 일지 ④에서 「섬 깃발도 잠겼다」는 무엇을 뜻하나요?","options":[{"t":"해수면이 더 높아지면 섬이 바닷물에 잠겨 사라질 수도 있다","correct":true},{"t":"섬은 더 넓어진다","mis":"SC4-2-u4-X29"},{"t":"섬과 해수면은 관계가 없다","mis":"SC4-2-u4-X34"},{"t":"물을 부으면 섬이 더 높아진다","mis":"SC4-2-u4-X30"}],"explanation":["셋째 줄을 읽어요.","섬도 잠겼어요.","첫 번째예요."],"asset":{"type":"passage","lines":["색깔 점토로 육지와 섬을 만들고 깃발을 꽂았다.","물을 천천히 부으니 주택가 깃발이 잠겼다.","물을 더 부으니 섬 깃발도 잠겼다.","친구 다 — 「컵 속 얼음이 녹으면 물이 넘칠 거야.」"],"title":"바다반 일지 ④ 해수면 상승 모형실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#20','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C24',3,'mc','auto','바다반 일지 ⑤에서 「위협받는 건강」과 관계있는 내용은 무엇인가요?',ARRAY['SC4-2-u4-X38','SC4-2-u4-X35']::text[],false,'{"seq":20,"concept":"SC4-2-u4-C24","difficulty":3,"kind":"mc","stem":"바다반 일지 ⑤에서 「위협받는 건강」과 관계있는 내용은 무엇인가요?","options":[{"t":"폭염으로 열사병 환자가 늘어난다","correct":true},{"t":"비가 적게 와서 마실 물이 부족하다","mis":"SC4-2-u4-X38"},{"t":"동물과 식물이 사라진다","mis":"SC4-2-u4-X38"},{"t":"사람들이 더 건강해진다","mis":"SC4-2-u4-X35"}],"explanation":["셋째 줄을 읽어요.","질환이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["우리 모둠 삼각책 — 「부족해지는 물」","비가 적게 와서 마실 물이 부족한 곳이 늘어난다.","폭염으로 열사병 환자가 늘어난다는 것도 알았다.","공공 사이트에서 조사하고 출처를 적었다."],"title":"바다반 일지 ⑤ 삼각책 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#21','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C31',3,'mc','auto','대응 방법과 그 까닭을 바르게 이은 것은 무엇인가요?',ARRAY['SC4-2-u4-X44']::text[],false,'{"seq":21,"concept":"SC4-2-u4-C31","difficulty":3,"kind":"mc","stem":"대응 방법과 그 까닭을 바르게 이은 것은 무엇인가요?","options":[{"t":"일회용 젓가락을 받지 않는다 — 쓰레기를 줄일 수 있어서","correct":true},{"t":"일회용 젓가락을 받지 않는다 — 물을 절약할 수 있어서","mis":"SC4-2-u4-X44"},{"t":"컵에 물을 받아 양치한다 — 쓰레기를 늘릴 수 있어서","mis":"SC4-2-u4-X44"},{"t":"전등을 켜 둔다 — 전기를 아낄 수 있어서","mis":"SC4-2-u4-X44"}],"explanation":["방법과 까닭을 이어 봐요.","젓가락은 쓰레기예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#22','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C34',3,'mc','auto','바다반 일지 ⑦의 계획을 꾸준히 지키는 데 가장 도움이 되는 것은 무엇인가요?',ARRAY['SC4-2-u4-X49','SC4-2-u4-X48']::text[],false,'{"seq":22,"concept":"SC4-2-u4-C34","difficulty":3,"kind":"mc","stem":"바다반 일지 ⑦의 계획을 꾸준히 지키는 데 가장 도움이 되는 것은 무엇인가요?","options":[{"t":"점검표에 매일 표시하며 스스로 점검한다","correct":true},{"t":"내일부터 하겠다고 미룬다","mis":"SC4-2-u4-X49"},{"t":"하루만 하고 그만둔다","mis":"SC4-2-u4-X48"},{"t":"계획표를 서랍에 넣어 둔다","mis":"SC4-2-u4-X49"}],"explanation":["셋째 줄을 읽어요.","매일 표시해요.","첫 번째예요."],"asset":{"type":"passage","lines":["목표 — 물을 아끼자!","실천 내용 — 양치할 때 컵에 물을 받아서 하기","방법 — 점검표를 만들어 매일 표시하기","친구 나 — 「딱 하루만 하면 충분해.」"],"title":"바다반 일지 ⑦ 나의 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#23','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C14',4,'essay','teacher','바다반 일지 ③의 ㉠~㉢ 가운데 기후 변화를 더욱 심각하게 만드는 활동을 모두 고르고, 각각의 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC4-2-u4-C14","difficulty":4,"kind":"essay","stem":"바다반 일지 ③의 ㉠~㉢ 가운데 기후 변화를 더욱 심각하게 만드는 활동을 모두 고르고, 각각의 까닭을 쓰세요.","answer_guide":{"answer":"예: ㉠은 가까운 거리에도 승용차를 타서 화석 연료를 과도하게 사용하므로 기후 변화를 심각하게 만든다. ㉡은 일회용 컵을 많이 써서 쓰레기를 많이 만들므로 기후 변화를 심각하게 만든다. ㉢은 전기를 아끼는 일이라 해당하지 않는다.","scoring_points":["㉠과 ㉡을 골랐는가","각각의 까닭을 썼는가","㉢이 해당하지 않음을 알았는가"]},"explanation":["일지를 읽어요.","하나씩 따져요.","까닭을 써요."],"asset":{"type":"passage","lines":["㉠ 가까운 거리도 승용차를 타고 간다.","㉡ 일회용 컵을 하루에 여러 개 쓴다.","㉢ 아무도 없는 방의 전등을 끈다.","토의할 때 친구의 의견을 끝까지 들었다."],"title":"바다반 일지 ③ 생활 속 인간의 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#24','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C10',4,'mc','auto','친구가 「기후 변화는 자연이 일으키는 거라 사람과는 상관없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X17','SC4-2-u4-X18','SC4-2-u4-X19']::text[],false,'{"seq":24,"concept":"SC4-2-u4-C10","difficulty":4,"kind":"mc","stem":"친구가 「기후 변화는 자연이 일으키는 거라 사람과는 상관없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「자연에 의해서도 일어나지만 숲 파괴, 화석 연료 사용처럼 환경을 생각하지 않는 인간의 활동과도 관련이 있어.」","correct":true},{"t":"「맞아, 사람과는 관련이 없어.」","mis":"SC4-2-u4-X17"},{"t":"「사람이 하는 모든 일이 기후 변화를 만들어.」","mis":"SC4-2-u4-X18"},{"t":"「나무를 심으면 기후 변화가 더 심해져.」","mis":"SC4-2-u4-X19"}],"explanation":["인간의 활동을 떠올려요.","관련이 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_b#25','sci',4,2,'u4','','g4_2_sci_u4_review_b','unit_review','SC4-2-u4-C27',4,'essay','teacher','바다반 일지 ⑥을 보고 국가와 사회, 과학자, 우리가 하는 대응 방법을 하나씩 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-2-u4-C27","difficulty":4,"kind":"essay","stem":"바다반 일지 ⑥을 보고 국가와 사회, 과학자, 우리가 하는 대응 방법을 하나씩 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 국가와 사회는 숲을 되살리고 법과 제도를 만든다. 과학자는 기후 변화에 강한 씨앗을 연구한다. 우리 반은 급식을 먹을 만큼만 받는다. 대응은 나라에서만 하는 것이 아니라 국가와 사회, 과학자, 사람들이 함께 할 수 있다.","scoring_points":["세 무리의 대응을 바르게 썼는가","우리가 할 수 있는 일을 썼는가","친구 가의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","셋을 나눠 써요.","고쳐 써요."],"asset":{"type":"passage","lines":["국가와 사회 — 숲을 되살리고 법과 제도를 만든다.","과학자 — 기후 변화에 강한 씨앗을 연구한다.","우리 반 — 급식을 먹을 만큼만 받는다.","친구 가 — 「대응은 나라에서만 할 수 있어.」"],"title":"바다반 일지 ⑥ 대응 방법 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#1','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C1',1,'mc','auto','북극곰이 편지에서 친구들의 도움이 필요하다고 한 까닭은 무엇인가요?',ARRAY['SC4-2-u4-X01','SC4-2-u4-X02']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C1","difficulty":1,"kind":"mc","stem":"북극곰이 편지에서 친구들의 도움이 필요하다고 한 까닭은 무엇인가요?","options":[{"t":"기후 변화로 빙하가 작아져 북극에서 살기 어려워졌기 때문에","correct":true},{"t":"북극이 더 추워졌기 때문에","mis":"SC4-2-u4-X01"},{"t":"놀이에서 이기고 싶기 때문에","mis":"SC4-2-u4-X02"},{"t":"빙하가 너무 커졌기 때문에","mis":"SC4-2-u4-X01"}],"explanation":["편지를 떠올려요.","빙하가 작아졌어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#2','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C7',1,'mc','auto','겨울에 강한 한파가 발생하는 것과 관계있는 카드는 무엇인가요?',ARRAY['SC4-2-u4-X15','SC4-2-u4-X12']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C7","difficulty":1,"kind":"mc","stem":"겨울에 강한 한파가 발생하는 것과 관계있는 카드는 무엇인가요?","options":[{"t":"한파 일수","correct":true},{"t":"연간 강수량","mis":"SC4-2-u4-X15"},{"t":"가을~봄 강수량","mis":"SC4-2-u4-X15"},{"t":"폭염 일수","mis":"SC4-2-u4-X12"}],"explanation":["겨울의 추위예요.","한파예요.","한파 일수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#3','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C13',1,'mc','auto','바다반 일지 ③에서 쓰레기를 많이 만드는 모습은 무엇인가요?',ARRAY['SC4-2-u4-X19','SC4-2-u4-X21','SC4-2-u4-X22']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C13","difficulty":1,"kind":"mc","stem":"바다반 일지 ③에서 쓰레기를 많이 만드는 모습은 무엇인가요?","options":[{"t":"㉡ 일회용 컵을 하루에 여러 개 쓴다","correct":true},{"t":"㉢ 아무도 없는 방의 전등을 끈다","mis":"SC4-2-u4-X19"},{"t":"㉠ 가까운 거리도 승용차를 타고 간다","mis":"SC4-2-u4-X21"},{"t":"토의할 때 친구의 의견을 끝까지 들었다","mis":"SC4-2-u4-X22"}],"explanation":["버리는 것을 찾아요.","일회용이에요.","㉡이에요."],"asset":{"type":"passage","lines":["㉠ 가까운 거리도 승용차를 타고 간다.","㉡ 일회용 컵을 하루에 여러 개 쓴다.","㉢ 아무도 없는 방의 전등을 끈다.","토의할 때 친구의 의견을 끝까지 들었다."],"title":"바다반 일지 ③ 생활 속 인간의 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#4','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C18',1,'mc','auto','바다반 일지 ④의 결과로 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u4-X29','SC4-2-u4-X34']::text[],false,'{"seq":4,"concept":"SC4-2-u4-C18","difficulty":1,"kind":"mc","stem":"바다반 일지 ④의 결과로 알 수 있는 것은 무엇인가요?","options":[{"t":"해수면이 높아지면 살 수 있는 땅이 줄어든다","correct":true},{"t":"해수면이 높아지면 땅이 넓어진다","mis":"SC4-2-u4-X29"},{"t":"섬은 절대 잠기지 않는다","mis":"SC4-2-u4-X29"},{"t":"우리와 상관없는 일이다","mis":"SC4-2-u4-X34"}],"explanation":["깃발이 잠겼어요.","땅이 줄어요.","첫 번째예요."],"asset":{"type":"passage","lines":["색깔 점토로 육지와 섬을 만들고 깃발을 꽂았다.","물을 천천히 부으니 주택가 깃발이 잠겼다.","물을 더 부으니 섬 깃발도 잠겼다.","친구 다 — 「컵 속 얼음이 녹으면 물이 넘칠 거야.」"],"title":"바다반 일지 ④ 해수면 상승 모형실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#5','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C24',1,'mc','auto','열사병과 같은 온열 질환은 무엇과 관계가 깊나요?',ARRAY['SC4-2-u4-X37']::text[],false,'{"seq":5,"concept":"SC4-2-u4-C24","difficulty":1,"kind":"mc","stem":"열사병과 같은 온열 질환은 무엇과 관계가 깊나요?","options":[{"t":"폭염","correct":true},{"t":"한파","mis":"SC4-2-u4-X37"},{"t":"폭설","mis":"SC4-2-u4-X37"},{"t":"홍수","mis":"SC4-2-u4-X37"}],"explanation":["「온열」은 따뜻함이에요.","아주 더운 날씨예요.","폭염이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#6','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C29',1,'mc','auto','바다반 일지 ⑥에서 과학자가 하는 노력은 무엇인가요?',ARRAY['SC4-2-u4-X42','SC4-2-u4-X43']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C29","difficulty":1,"kind":"mc","stem":"바다반 일지 ⑥에서 과학자가 하는 노력은 무엇인가요?","options":[{"t":"기후 변화에 강한 씨앗을 연구한다","correct":true},{"t":"급식을 먹을 만큼만 받는다","mis":"SC4-2-u4-X42"},{"t":"법과 제도를 만든다","mis":"SC4-2-u4-X42"},{"t":"씨앗을 모두 버린다","mis":"SC4-2-u4-X43"}],"explanation":["둘째 줄을 읽어요.","연구해요.","첫 번째예요."],"asset":{"type":"passage","lines":["국가와 사회 — 숲을 되살리고 법과 제도를 만든다.","과학자 — 기후 변화에 강한 씨앗을 연구한다.","우리 반 — 급식을 먹을 만큼만 받는다.","친구 가 — 「대응은 나라에서만 할 수 있어.」"],"title":"바다반 일지 ⑥ 대응 방법 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#7','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C32',1,'mc','auto','생활 속 실천은 어떻게 하는 것이 중요한가요?',ARRAY['SC4-2-u4-X46','SC4-2-u4-X08']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C32","difficulty":1,"kind":"mc","stem":"생활 속 실천은 어떻게 하는 것이 중요한가요?","options":[{"t":"일상생활에서 함께 실천한다","correct":true},{"t":"일 년에 한 번만 한다","mis":"SC4-2-u4-X46"},{"t":"다른 사람이 할 때까지 기다린다","mis":"SC4-2-u4-X46"},{"t":"걱정만 한다","mis":"SC4-2-u4-X08"}],"explanation":["실천의 뜻을 떠올려요.","날마다 함께예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#8','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C37',1,'mc','auto','영구 동토가 녹으면 얼음 속에 묻혀 있던 것은 어떻게 되나요?',ARRAY['SC4-2-u4-X53']::text[],false,'{"seq":8,"concept":"SC4-2-u4-C37","difficulty":1,"kind":"mc","stem":"영구 동토가 녹으면 얼음 속에 묻혀 있던 것은 어떻게 되나요?","options":[{"t":"묻혀 있던 미생물이 되살아난다","correct":true},{"t":"더 단단하게 언다","mis":"SC4-2-u4-X53"},{"t":"더 깊이 묻힌다","mis":"SC4-2-u4-X53"},{"t":"모두 사라진다","mis":"SC4-2-u4-X53"}],"explanation":["녹으면 드러나요.","되살아나요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#9','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C4',2,'error','auto','줄어드는 빙하 놀이를 돌아보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u4-X07','SC4-2-u4-X08','SC4-2-u4-X06']::text[],false,'{"seq":9,"concept":"SC4-2-u4-C4","difficulty":2,"kind":"error","stem":"줄어드는 빙하 놀이를 돌아보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「북극곰 일은 우리랑 상관없어.」","correct":true,"mis_target":"SC4-2-u4-X07"},{"t":"친구 가 — 「북극곰을 돕고 싶은 마음이 생겼어.」","mis":"SC4-2-u4-X08"},{"t":"친구 다 — 「점점 작아지는 종이 위에서 버티기 힘들었어.」","mis":"SC4-2-u4-X06"}],"explanation":["편지 끝 줄을 떠올려요.","도움이 필요해요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#10','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C5',2,'mc','auto','자연재해가 점점 심해지는 까닭은 무엇과 관련이 있나요?',ARRAY['SC4-2-u4-X10','SC4-2-u4-X09','SC4-2-u4-X11']::text[],false,'{"seq":10,"concept":"SC4-2-u4-C5","difficulty":2,"kind":"mc","stem":"자연재해가 점점 심해지는 까닭은 무엇과 관련이 있나요?","options":[{"t":"기후 변화가 심해지고 있다","correct":true},{"t":"기후 변화가 사라지고 있다","mis":"SC4-2-u4-X10"},{"t":"다른 나라에서만 일어난다","mis":"SC4-2-u4-X09"},{"t":"평균 기온이 낮아지고 있다","mis":"SC4-2-u4-X11"}],"explanation":["기후 변화를 떠올려요.","심해지고 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
