INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#12','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C17',2,'mc','auto','이쑤시개 깃발을 만들 때 알맞은 행동은 무엇인가요?',ARRAY['SC4-2-u4-X28']::text[],false,'{"seq":12,"concept":"SC4-2-u4-C17","difficulty":2,"kind":"mc","stem":"이쑤시개 깃발을 만들 때 알맞은 행동은 무엇인가요?","options":[{"t":"면장갑을 끼고 장난치지 않는다","correct":true},{"t":"이쑤시개로 친구를 찌르며 논다","mis":"SC4-2-u4-X28"},{"t":"맨손으로 이쑤시개를 마구 다룬다","mis":"SC4-2-u4-X28"},{"t":"물을 바닥에 쏟는다","mis":"SC4-2-u4-X28"}],"explanation":["이쑤시개는 뾰족해요.","손을 보호해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#13','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C25',2,'mc','auto','동해안의 수온이 상승하면 오징어는 어떻게 되나요?',ARRAY['SC4-2-u4-X39','SC4-2-u4-X34']::text[],false,'{"seq":13,"concept":"SC4-2-u4-C25","difficulty":2,"kind":"mc","stem":"동해안의 수온이 상승하면 오징어는 어떻게 되나요?","options":[{"t":"다른 곳으로 이동해 동해안에서 줄어든다","correct":true},{"t":"동해안에서 더 늘어난다","mis":"SC4-2-u4-X39"},{"t":"동해안에서만 새로 생겨난다","mis":"SC4-2-u4-X39"},{"t":"수온과 관계없이 그대로이다","mis":"SC4-2-u4-X34"}],"explanation":["바닷물이 따뜻해져요.","오징어가 떠나요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#14','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C31',2,'mc','auto','물을 아끼는 기후 변화 대응 방법은 무엇인가요?',ARRAY['SC4-2-u4-X44']::text[],false,'{"seq":14,"concept":"SC4-2-u4-C31","difficulty":2,"kind":"mc","stem":"물을 아끼는 기후 변화 대응 방법은 무엇인가요?","options":[{"t":"샤워를 너무 길게 하지 않는다","correct":true},{"t":"물을 틀어 놓고 양치한다","mis":"SC4-2-u4-X44"},{"t":"빨래 한 장마다 세탁기를 돌린다","mis":"SC4-2-u4-X44"},{"t":"수도꼭지를 잠그지 않는다","mis":"SC4-2-u4-X44"}],"explanation":["물을 쓰는 곳을 떠올려요.","짧게 써요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#15','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C34',2,'mc','auto','목표를 이루는 데 방해가 되는 것은 무엇인가요?',ARRAY['SC4-2-u4-X49']::text[],false,'{"seq":15,"concept":"SC4-2-u4-C34","difficulty":2,"kind":"mc","stem":"목표를 이루는 데 방해가 되는 것은 무엇인가요?","options":[{"t":"난방기를 사용할 때 창문을 열어 놓는다","correct":true},{"t":"계획표를 잘 보이는 곳에 붙인다","mis":"SC4-2-u4-X49"},{"t":"점검표에 매일 표시한다","mis":"SC4-2-u4-X49"},{"t":"여러 사람 앞에서 약속한다","mis":"SC4-2-u4-X49"}],"explanation":["에너지를 낭비하는 것을 찾아요.","창문이 열려 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#16','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C39',2,'mc','auto','기후 변화에 대응하면 영구 동토와 빙하는 어떻게 될까요?',ARRAY['SC4-2-u4-X55','SC4-2-u4-X07','SC4-2-u4-X08']::text[],false,'{"seq":16,"concept":"SC4-2-u4-C39","difficulty":2,"kind":"mc","stem":"기후 변화에 대응하면 영구 동토와 빙하는 어떻게 될까요?","options":[{"t":"지킬 수 있다","correct":true},{"t":"더 빨리 녹는다","mis":"SC4-2-u4-X55"},{"t":"아무 관계가 없다","mis":"SC4-2-u4-X07"},{"t":"걱정만 커진다","mis":"SC4-2-u4-X08"}],"explanation":["생각해요를 떠올려요.","지킬 수 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#17','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C5',3,'mc','auto','바다반 일지 ② 친구 나의 말을 바르게 고친 것은 무엇인가요?',ARRAY['SC4-2-u4-X09','SC4-2-u4-X10','SC4-2-u4-X11']::text[],false,'{"seq":17,"concept":"SC4-2-u4-C5","difficulty":3,"kind":"mc","stem":"바다반 일지 ② 친구 나의 말을 바르게 고친 것은 무엇인가요?","options":[{"t":"우리나라에서도 폭염, 한파, 가뭄, 홍수, 폭설이 일어나고 있어","correct":true},{"t":"기후 변화는 다른 나라에서만 일어나","mis":"SC4-2-u4-X09"},{"t":"우리나라 자연재해는 줄어들고 있어","mis":"SC4-2-u4-X10"},{"t":"평균 기온은 늘 같아","mis":"SC4-2-u4-X11"}],"explanation":["일지의 위 세 줄을 읽어요.","우리나라 이야기예요.","첫 번째예요."],"asset":{"type":"passage","lines":["연평균 기온 그래프 — 평균 기온이 점차 올라간다.","폭염 일수와 한파 일수가 예전보다 늘었다.","연간 강수량은 늘고, 가을~봄 강수량은 줄었다.","친구 나 — 「우리나라는 기후 변화와 상관없어.」"],"title":"바다반 일지 ② 기후 변화 현상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#18','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C10',3,'ox','auto','숲에 나무를 심는 것도 기후 변화를 더욱 심각하게 만드는 인간의 활동이에요.',ARRAY['SC4-2-u4-X18']::text[],false,'{"seq":18,"concept":"SC4-2-u4-C10","difficulty":3,"kind":"ox","stem":"숲에 나무를 심는 것도 기후 변화를 더욱 심각하게 만드는 인간의 활동이에요.","answer":"X","reason_options":[{"t":"기후 변화를 심각하게 만드는 것은 숲을 파괴하는 것처럼 환경을 생각하지 않는 활동이기 때문에","correct":true},{"t":"사람이 하는 일은 모두 기후 변화를 심각하게 만들기 때문에","mis":"SC4-2-u4-X18"}],"mis":"SC4-2-u4-X18","explanation":["숲 파괴와 견줘요.","나무를 심는 건 반대예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#19','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C19',3,'mc','auto','남태평양의 몇몇 섬들이 사라질 수도 있는 까닭은 무엇인가요?',ARRAY['SC4-2-u4-X26','SC4-2-u4-X33','SC4-2-u4-X29']::text[],false,'{"seq":19,"concept":"SC4-2-u4-C19","difficulty":3,"kind":"mc","stem":"남태평양의 몇몇 섬들이 사라질 수도 있는 까닭은 무엇인가요?","options":[{"t":"해수면이 상승하여 바닷물에 잠길 수 있기 때문에","correct":true},{"t":"해수면이 낮아지기 때문에","mis":"SC4-2-u4-X26"},{"t":"사막이 줄어들기 때문에","mis":"SC4-2-u4-X33"},{"t":"섬이 스스로 움직이기 때문에","mis":"SC4-2-u4-X29"}],"explanation":["모형실험을 떠올려요.","섬 깃발이 잠겼어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#20','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C22',3,'mc','auto','기후 변화의 영향을 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u4-X35','SC4-2-u4-X34']::text[],false,'{"seq":20,"concept":"SC4-2-u4-C22","difficulty":3,"kind":"mc","stem":"기후 변화의 영향을 바르게 말한 것은 무엇인가요?","options":[{"t":"생태계를 파괴하고 자연재해를 자주 일어나게 하는 등 부정적인 영향을 준다","correct":true},{"t":"자연재해를 줄여 주는 좋은 영향을 준다","mis":"SC4-2-u4-X35"},{"t":"먼 미래에만 영향을 준다","mis":"SC4-2-u4-X34"},{"t":"환경에는 영향이 없다","mis":"SC4-2-u4-X34"}],"explanation":["그림 넷을 떠올려요.","좋지 않은 영향이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#21','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C30',3,'mc','auto','친환경 에너지를 쓰는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u4-X45','SC4-2-u4-X41']::text[],false,'{"seq":21,"concept":"SC4-2-u4-C30","difficulty":3,"kind":"mc","stem":"친환경 에너지를 쓰는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"화석 연료 사용을 줄일 수 있기 때문에","correct":true},{"t":"화석 연료를 더 많이 쓰기 위해서","mis":"SC4-2-u4-X45"},{"t":"기후 변화와 관계없이 재미있어서","mis":"SC4-2-u4-X45"},{"t":"나 혼자만 쓰기 위해서","mis":"SC4-2-u4-X41"}],"explanation":["화석 연료를 떠올려요.","줄여야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#22','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C37',3,'mc','auto','바다반 일지 ⑧에서 영구 동토가 녹으면서 생기는 일은 무엇인가요?',ARRAY['SC4-2-u4-X53','SC4-2-u4-X51']::text[],false,'{"seq":22,"concept":"SC4-2-u4-C37","difficulty":3,"kind":"mc","stem":"바다반 일지 ⑧에서 영구 동토가 녹으면서 생기는 일은 무엇인가요?","options":[{"t":"묻혀 있던 미생물이 되살아난다","correct":true},{"t":"여름에도 얼어 있는 땅이 늘어난다","mis":"SC4-2-u4-X53"},{"t":"미생물이 모두 사라진다","mis":"SC4-2-u4-X53"},{"t":"빙하가 더 커진다","mis":"SC4-2-u4-X51"}],"explanation":["둘째 줄을 읽어요.","되살아나요.","첫 번째예요."],"asset":{"type":"passage","lines":["영구 동토 — 여름에도 얼어 있는 땅","기후 변화로 녹으면서 묻혀 있던 미생물이 되살아난다.","과학자들은 빙하의 얼음층을 캐내어 연구한다.","친구 다 — 「세균 이야기는 이미 다 밝혀졌대.」"],"title":"바다반 일지 ⑧ 빙하 속 세균"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#23','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C18',4,'essay','teacher','바다반 일지 ④의 결과를 쓰고, 해수면이 높아지면 어떤 피해가 생기는지 쓰세요. 친구 다의 말도 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC4-2-u4-C18","difficulty":4,"kind":"essay","stem":"바다반 일지 ④의 결과를 쓰고, 해수면이 높아지면 어떤 피해가 생기는지 쓰세요. 친구 다의 말도 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 물을 부으니 주택가 깃발이 잠기고, 더 부으니 섬 깃발도 잠겼다. 해수면이 높아지면 해안 도시와 낮은 땅, 섬이 바닷물에 잠겨 우리가 살 수 있는 땅이 줄어든다. 컵 속 얼음은 물에 떠 있으므로 녹아도 물의 높이가 변하지 않는다.","scoring_points":["실험 결과를 썼는가","해수면 상승의 피해를 썼는가","친구 다의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","결과와 피해를 써요.","고쳐 써요."],"asset":{"type":"passage","lines":["색깔 점토로 육지와 섬을 만들고 깃발을 꽂았다.","물을 천천히 부으니 주택가 깃발이 잠겼다.","물을 더 부으니 섬 깃발도 잠겼다.","친구 다 — 「컵 속 얼음이 녹으면 물이 넘칠 거야.」"],"title":"바다반 일지 ④ 해수면 상승 모형실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#24','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C32',4,'mc','auto','친구가 「기후 변화가 더 심해지면 어떡하지? 걱정만 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X08','SC4-2-u4-X46','SC4-2-u4-X48']::text[],false,'{"seq":24,"concept":"SC4-2-u4-C32","difficulty":4,"kind":"mc","stem":"친구가 「기후 변화가 더 심해지면 어떡하지? 걱정만 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「걱정만 하기보다 나부터 계획을 세워 꾸준히 실천하자. 많은 사람이 함께하면 기후 변화가 더 심해지는 것을 막을 수 있어.」","correct":true},{"t":"「맞아, 걱정만 하자.」","mis":"SC4-2-u4-X08"},{"t":"「다른 사람이 할 때까지 기다리자.」","mis":"SC4-2-u4-X46"},{"t":"「딱 하루만 해 보자.」","mis":"SC4-2-u4-X48"}],"explanation":["만화의 마지막 말을 떠올려요.","나부터 실천해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_c#25','sci',4,2,'u4','','g4_2_sci_u4_review_c','unit_review','SC4-2-u4-C33',4,'essay','teacher','바다반 일지 ⑦의 계획에서 잘된 점을 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-2-u4-C33","difficulty":4,"kind":"essay","stem":"바다반 일지 ⑦의 계획에서 잘된 점을 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 물을 아끼자는 목표와 양치할 때 컵에 물을 받아서 하는 실천 내용이 잘 이어지고, 점검표로 매일 표시해 꾸준히 실천할 수 있다. 하루만 하면 충분한 것이 아니라 매일 꾸준히 실천하는 습관이 중요하다.","scoring_points":["목표와 실천 내용이 이어짐을 썼는가","점검 방법의 좋은 점을 썼는가","친구 나의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","잘된 점을 찾아요.","고쳐 써요."],"asset":{"type":"passage","lines":["목표 — 물을 아끼자!","실천 내용 — 양치할 때 컵에 물을 받아서 하기","방법 — 점검표를 만들어 매일 표시하기","친구 나 — 「딱 하루만 하면 충분해.」"],"title":"바다반 일지 ⑦ 나의 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_d#1','sci',4,2,'u4','','g4_2_sci_u4_review_d','unit_review','SC4-2-u4-C4',1,'mc','auto','바다반 일지 ①의 놀이를 하고 든 마음으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u4-X08','SC4-2-u4-X07','SC4-2-u4-X04']::text[],false,'{"seq":1,"concept":"SC4-2-u4-C4","difficulty":1,"kind":"mc","stem":"바다반 일지 ①의 놀이를 하고 든 마음으로 알맞은 것은 무엇인가요?","options":[{"t":"북극곰의 마음을 이해하고 돕고 싶은 마음이 생겼다","correct":true},{"t":"무섭기만 하고 할 수 있는 일이 없다","mis":"SC4-2-u4-X08"},{"t":"북극의 일이라 상관없다","mis":"SC4-2-u4-X07"},{"t":"이긴 모둠만 기억하면 된다","mis":"SC4-2-u4-X04"}],"explanation":["느낀 점을 떠올려요.","돕고 싶어요.","첫 번째예요."],"asset":{"type":"passage","lines":["모둠 친구 넷이 흰 종이 위에 올라갔다.","신호에 따라 종이를 반으로 접을 때마다 올라설 자리가 줄었다.","세 번 접으니 버티기가 무척 힘들었다.","친구 가 — 「가장 오래 버틴 우리 모둠이 이긴 거야.」"],"title":"바다반 일지 ① 줄어드는 빙하 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_d#2','sci',4,2,'u4','','g4_2_sci_u4_review_d','unit_review','SC4-2-u4-C8',1,'mc','auto','가을~봄 강수량이 줄어들면 무엇이 심해질 수 있나요?',ARRAY['SC4-2-u4-X13','SC4-2-u4-X15']::text[],false,'{"seq":2,"concept":"SC4-2-u4-C8","difficulty":1,"kind":"mc","stem":"가을~봄 강수량이 줄어들면 무엇이 심해질 수 있나요?","options":[{"t":"가뭄","correct":true},{"t":"홍수","mis":"SC4-2-u4-X13"},{"t":"폭설","mis":"SC4-2-u4-X13"},{"t":"한파","mis":"SC4-2-u4-X15"}],"explanation":["비가 적게 와요.","메말라요.","가뭄이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_d#3','sci',4,2,'u4','','g4_2_sci_u4_review_d','unit_review','SC4-2-u4-C10',1,'mc','auto','기후 변화와 인간의 활동에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u4-X17','SC4-2-u4-X18']::text[],false,'{"seq":3,"concept":"SC4-2-u4-C10","difficulty":1,"kind":"mc","stem":"기후 변화와 인간의 활동에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"인간의 활동과 기후 변화는 밀접한 관련이 있다","correct":true},{"t":"기후 변화는 자연에 의해서만 일어난다","mis":"SC4-2-u4-X17"},{"t":"인간의 활동은 기후 변화와 관련이 없다","mis":"SC4-2-u4-X17"},{"t":"사람이 하는 모든 일이 기후 변화를 심각하게 만든다","mis":"SC4-2-u4-X18"}],"explanation":["인간의 활동을 떠올려요.","관련이 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_d#4','sci',4,2,'u4','','g4_2_sci_u4_review_d','unit_review','SC4-2-u4-C19',1,'mc','auto','기후 변화로 바닷물의 온도가 높아지면 생기는 일은 무엇인가요?',ARRAY['SC4-2-u4-X33','SC4-2-u4-X26']::text[],false,'{"seq":4,"concept":"SC4-2-u4-C19","difficulty":1,"kind":"mc","stem":"기후 변화로 바닷물의 온도가 높아지면 생기는 일은 무엇인가요?","options":[{"t":"산호초가 하얗게 변한다","correct":true},{"t":"산호초가 더 알록달록해진다","mis":"SC4-2-u4-X33"},{"t":"사막이 줄어든다","mis":"SC4-2-u4-X33"},{"t":"바닷물이 차가워진다","mis":"SC4-2-u4-X26"}],"explanation":["세계 곳곳의 피해를 떠올려요.","색이 빠져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_d#5','sci',4,2,'u4','','g4_2_sci_u4_review_d','unit_review','SC4-2-u4-C22',1,'mc','auto','기후 변화는 언제 우리 생활에 영향을 미치나요?',ARRAY['SC4-2-u4-X34','SC4-2-u4-X35']::text[],false,'{"seq":5,"concept":"SC4-2-u4-C22","difficulty":1,"kind":"mc","stem":"기후 변화는 언제 우리 생활에 영향을 미치나요?","options":[{"t":"이미 우리 생활과 환경에 영향을 미치고 있다","correct":true},{"t":"먼 미래에만 영향을 미친다","mis":"SC4-2-u4-X34"},{"t":"우리 생활에는 영향을 미치지 않는다","mis":"SC4-2-u4-X34"},{"t":"좋은 영향만 미친다","mis":"SC4-2-u4-X35"}],"explanation":["불편했던 경험을 떠올려요.","벌써예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_d#6','sci',4,2,'u4','','g4_2_sci_u4_review_d','unit_review','SC4-2-u4-C30',1,'mc','auto','친환경 에너지로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u4-X45','SC4-2-u4-X44']::text[],false,'{"seq":6,"concept":"SC4-2-u4-C30","difficulty":1,"kind":"mc","stem":"친환경 에너지로 알맞은 것은 무엇인가요?","options":[{"t":"풍력 에너지","correct":true},{"t":"화석 연료","mis":"SC4-2-u4-X45"},{"t":"일회용품","mis":"SC4-2-u4-X44"},{"t":"쓰레기 태우기","mis":"SC4-2-u4-X45"}],"explanation":["바람을 떠올려요.","바람의 힘이에요.","풍력 에너지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_d#7','sci',4,2,'u4','','g4_2_sci_u4_review_d','unit_review','SC4-2-u4-C35',1,'mc','auto','친구의 계획을 평가할 때 살펴볼 것은 무엇인가요?',ARRAY['SC4-2-u4-X50']::text[],false,'{"seq":7,"concept":"SC4-2-u4-C35","difficulty":1,"kind":"mc","stem":"친구의 계획을 평가할 때 살펴볼 것은 무엇인가요?","options":[{"t":"친구가 계획에 따라 일주일 동안 잘 실천했는가","correct":true},{"t":"친구들보다 먼저 끝냈는가","mis":"SC4-2-u4-X50"},{"t":"가장 많은 색으로 칠했는가","mis":"SC4-2-u4-X50"},{"t":"계획표가 가장 큰가","mis":"SC4-2-u4-X50"}],"explanation":["평가 기준을 떠올려요.","실천했는지 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
