INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_d#18','sci',4,2,'u4','','g4_2_sci_u4_review_d','unit_review','SC4-2-u4-C13',3,'mc','auto','과도하게 쓰는 전기 에너지가 기후 변화와 관련 있는 까닭은 무엇인가요?',ARRAY['SC4-2-u4-X23']::text[],false,'{"seq":18,"concept":"SC4-2-u4-C13","difficulty":3,"kind":"mc","stem":"과도하게 쓰는 전기 에너지가 기후 변화와 관련 있는 까닭은 무엇인가요?","options":[{"t":"전기 에너지를 만들기 위해 화석 연료를 사용하기 때문에","correct":true},{"t":"전기는 기후 변화와 관계가 없기 때문에","mis":"SC4-2-u4-X23"},{"t":"전기를 많이 쓸수록 기후 변화가 줄어들기 때문에","mis":"SC4-2-u4-X23"},{"t":"전기는 나무에서만 만들기 때문에","mis":"SC4-2-u4-X23"}],"explanation":["전기를 만드는 방법을 떠올려요.","연료를 태워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_d#19','sci',4,2,'u4','','g4_2_sci_u4_review_d','unit_review','SC4-2-u4-C16',3,'mc','auto','극지방 빙하가 녹을 때 생기는 일을 바르게 이은 것은 무엇인가요?',ARRAY['SC4-2-u4-X26','SC4-2-u4-X27','SC4-2-u4-X32']::text[],false,'{"seq":19,"concept":"SC4-2-u4-C16","difficulty":3,"kind":"mc","stem":"극지방 빙하가 녹을 때 생기는 일을 바르게 이은 것은 무엇인가요?","options":[{"t":"빙하가 녹음 → 해수면 상승 → 낮은 땅이 잠김","correct":true},{"t":"빙하가 녹음 → 해수면 하강 → 땅이 넓어짐","mis":"SC4-2-u4-X26"},{"t":"빙하가 녹음 → 강수량 증가 → 산이 높아짐","mis":"SC4-2-u4-X27"},{"t":"빙산이 녹음 → 해수면 크게 상승 → 섬이 잠김","mis":"SC4-2-u4-X32"}],"explanation":["차례를 따져요.","바닷물이 높아져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_d#20','sci',4,2,'u4','','g4_2_sci_u4_review_d','unit_review','SC4-2-u4-C24',3,'mc','auto','모기나 진드기가 많아지는 것과 관계있는 영향은 무엇인가요?',ARRAY['SC4-2-u4-X38','SC4-2-u4-X37','SC4-2-u4-X35']::text[],false,'{"seq":20,"concept":"SC4-2-u4-C24","difficulty":3,"kind":"mc","stem":"모기나 진드기가 많아지는 것과 관계있는 영향은 무엇인가요?","options":[{"t":"감염병이 증가할 수 있다","correct":true},{"t":"마실 물이 많아진다","mis":"SC4-2-u4-X38"},{"t":"온열 질환이 사라진다","mis":"SC4-2-u4-X37"},{"t":"생태계가 되살아난다","mis":"SC4-2-u4-X35"}],"explanation":["해충은 병을 옮겨요.","건강이 위협받아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_d#21','sci',4,2,'u4','','g4_2_sci_u4_review_d','unit_review','SC4-2-u4-C27',3,'mc','auto','바다반 일지 ⑥ 친구 가에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u4-X41','SC4-2-u4-X42','SC4-2-u4-X08']::text[],false,'{"seq":21,"concept":"SC4-2-u4-C27","difficulty":3,"kind":"mc","stem":"바다반 일지 ⑥ 친구 가에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"「우리 반이 급식을 먹을 만큼만 받는 것처럼 우리도 대응할 수 있어.」","correct":true},{"t":"「맞아, 우리는 아무것도 할 수 없어.」","mis":"SC4-2-u4-X41"},{"t":"「대응은 과학자만 하는 거야.」","mis":"SC4-2-u4-X42"},{"t":"「무섭기만 하니 하지 말자.」","mis":"SC4-2-u4-X08"}],"explanation":["셋째 줄을 읽어요.","우리도 해요.","첫 번째예요."],"asset":{"type":"passage","lines":["국가와 사회 — 숲을 되살리고 법과 제도를 만든다.","과학자 — 기후 변화에 강한 씨앗을 연구한다.","우리 반 — 급식을 먹을 만큼만 받는다.","친구 가 — 「대응은 나라에서만 할 수 있어.」"],"title":"바다반 일지 ⑥ 대응 방법 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_d#22','sci',4,2,'u4','','g4_2_sci_u4_review_d','unit_review','SC4-2-u4-C38',3,'mc','auto','바다반 일지 ⑧ 친구 다의 말을 바르게 고친 것은 무엇인가요?',ARRAY['SC4-2-u4-X54','SC4-2-u4-X07']::text[],false,'{"seq":22,"concept":"SC4-2-u4-C38","difficulty":3,"kind":"mc","stem":"바다반 일지 ⑧ 친구 다의 말을 바르게 고친 것은 무엇인가요?","options":[{"t":"세균이 미칠 영향은 앞으로 연구가 더 필요해","correct":true},{"t":"세균 이야기는 이미 다 밝혀졌어","mis":"SC4-2-u4-X54"},{"t":"빙하 연구는 필요 없어","mis":"SC4-2-u4-X54"},{"t":"세균은 우리와 상관없어","mis":"SC4-2-u4-X07"}],"explanation":["셋째 줄을 읽어요.","연구하고 있어요.","첫 번째예요."],"asset":{"type":"passage","lines":["영구 동토 — 여름에도 얼어 있는 땅","기후 변화로 녹으면서 묻혀 있던 미생물이 되살아난다.","과학자들은 빙하의 얼음층을 캐내어 연구한다.","친구 다 — 「세균 이야기는 이미 다 밝혀졌대.」"],"title":"바다반 일지 ⑧ 빙하 속 세균"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_d#23','sci',4,2,'u4','','g4_2_sci_u4_review_d','unit_review','SC4-2-u4-C22',4,'essay','teacher','바다반 일지 ⑤를 보고 기후 변화가 우리 생활과 환경에 미치는 영향을 두 가지 쓰고, 조사할 때 지킨 점을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC4-2-u4-C22","difficulty":4,"kind":"essay","stem":"바다반 일지 ⑤를 보고 기후 변화가 우리 생활과 환경에 미치는 영향을 두 가지 쓰고, 조사할 때 지킨 점을 쓰세요.","answer_guide":{"answer":"예: 비가 적게 와서 마실 물이 부족한 곳이 늘어나고, 폭염으로 열사병 같은 온열 질환 환자가 늘어난다. 조사할 때에는 신뢰할 수 있는 공공 사이트에서 찾고 출처를 확인해 적었다.","scoring_points":["영향 하나를 썼는가","영향 또 하나를 썼는가","조사할 때 지킨 점을 썼는가"]},"explanation":["일지를 읽어요.","두 가지를 써요.","지킨 점을 써요."],"asset":{"type":"passage","lines":["우리 모둠 삼각책 — 「부족해지는 물」","비가 적게 와서 마실 물이 부족한 곳이 늘어난다.","폭염으로 열사병 환자가 늘어난다는 것도 알았다.","공공 사이트에서 조사하고 출처를 적었다."],"title":"바다반 일지 ⑤ 삼각책 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_d#24','sci',4,2,'u4','','g4_2_sci_u4_review_d','unit_review','SC4-2-u4-C39',4,'mc','auto','친구가 「빙하 속 세균 이야기는 너무 무서워서 생각하기 싫어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u4-X08','SC4-2-u4-X54','SC4-2-u4-X55']::text[],false,'{"seq":24,"concept":"SC4-2-u4-C39","difficulty":4,"kind":"mc","stem":"친구가 「빙하 속 세균 이야기는 너무 무서워서 생각하기 싫어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「과학자들이 연구하고 있고, 우리도 일회용품을 줄이고 가까운 곳은 걸어 다니며 영구 동토와 빙하를 지킬 수 있어.」","correct":true},{"t":"「맞아, 무섭기만 해.」","mis":"SC4-2-u4-X08"},{"t":"「이미 다 밝혀졌으니 신경 쓰지 마.」","mis":"SC4-2-u4-X54"},{"t":"「일회용품을 더 쓰면 괜찮아.」","mis":"SC4-2-u4-X55"}],"explanation":["우리가 할 일을 떠올려요.","지킬 수 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u4_review_d#25','sci',4,2,'u4','','g4_2_sci_u4_review_d','unit_review','SC4-2-u4-C37',4,'essay','teacher','바다반 일지 ⑧을 보고 영구 동토가 녹으면 생기는 일과 과학자가 하는 일을 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-2-u4-C37","difficulty":4,"kind":"essay","stem":"바다반 일지 ⑧을 보고 영구 동토가 녹으면 생기는 일과 과학자가 하는 일을 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 영구 동토가 녹으면서 묻혀 있던 미생물이 되살아난다. 과학자들은 빙하의 얼음층을 캐내어 연구한다. 세균 이야기는 이미 다 밝혀진 것이 아니라 우리 사회에 미칠 영향을 앞으로 더 연구해야 한다.","scoring_points":["녹으면 생기는 일을 썼는가","과학자가 하는 일을 썼는가","친구 다의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","두 가지를 써요.","고쳐 써요."],"asset":{"type":"passage","lines":["영구 동토 — 여름에도 얼어 있는 땅","기후 변화로 녹으면서 묻혀 있던 미생물이 되살아난다.","과학자들은 빙하의 얼음층을 캐내어 연구한다.","친구 다 — 「세균 이야기는 이미 다 밝혀졌대.」"],"title":"바다반 일지 ⑧ 빙하 속 세균"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
